// ===== lang ==================================================================
// Which language the mod's messages are in, shared by hooks/register.js and hooks/compact-flow.mjs.
// The state lives here (one set per Claude Code session, put back by resetLang) so both files speak
// the same language. A mod's analyser follows `$` only into function declarations, so these are
// declarations, not injected callbacks.
const VOTES_KEPT = 5
const votes = []
let settingPromise
let storedPromise
let storedLang

function resetLang() {
  settingPromise = undefined
  storedPromise = undefined
  storedLang = undefined
  votes.length = 0
}

// The language of one typed prompt ('tr', 'en'); the last few decide the session's language.
function addLanguageVote(verdict) {
  votes.push(verdict)
  if (votes.length > VOTES_KEPT) votes.shift()
}

async function loadLanguageSetting($) {
  try {
    const settings = await $.settings.read()
    return typeof settings.language === 'string' ? settings.language : undefined
  } catch (err) {
    // No settings to read: the other signals still decide.
    return undefined
  }
}

async function loadStoredLanguage($) {
  try {
    const value = await $.store.get('lang')
    return value === 'tr' || value === 'en' ? value : undefined
  } catch (err) {
    // No store: the language is simply not remembered.
    return undefined
  }
}

// The language of the messages. Cheap to call: the settings and the stored language are read once
// per session (the promises are kept, so two overlapping calls share one read), and a language
// read off the prompts is remembered (that one word, "tr" or "en") so the next session can ask its
// first question in it, before any prompt has been typed.
async function resolveLang($) {
  const override = await $.env.get('CREW_CHIEF_LANG')
  const locale = await $.env.get('LANG')
  if (settingPromise === undefined) settingPromise = loadLanguageSetting($)
  if (storedPromise === undefined) storedPromise = loadStoredLanguage($)
  const setting = await settingPromise
  if (storedLang === undefined) storedLang = await storedPromise
  const pick = pickLanguage({ override, setting, votes, stored: storedLang, locale })
  if (pick.source === 'prompts' && pick.lang !== storedLang) {
    storedLang = pick.lang
    try {
      await $.store.set('lang', pick.lang)
    } catch (err) {
      // Not remembered; it is detected again next time.
    }
  }
  return pick.lang
}

// ===== config ================================================================
// /crew-config: one place to see and change the numbers the mod uses (when the compact flow speaks up, how
// the saver asks, how long a question waits). A value is kept in the plugin's store, so it survives the
// session; the environment variable of the same name, when set, still wins (kept for scripts).
// Nothing is written to settings.json or any project file.
const storeKey = (key) => 'cfg_' + key.replace('.', '_')

// A mod must spell environment variable names as literals in $.env.get, so each one is written out.
async function envRaw($, key) {
  try {
    switch (key) {
      case 'compact.enabled':
        return await $.env.get('CREW_CHIEF_COMPACT')
      case 'compact.arm':
        return await $.env.get('CREW_CHIEF_COMPACT_ARM')
      case 'compact.ask':
        return await $.env.get('CREW_CHIEF_COMPACT_ASK')
      case 'saver.ask':
        return await $.env.get('CREW_CHIEF_SAVER')
      case 'saver.five':
        return await $.env.get('CREW_CHIEF_SAVER_FIVE_HOUR')
      case 'saver.seven':
        return await $.env.get('CREW_CHIEF_SAVER_SEVEN_DAY')
      case 'ask.timeout':
        return await $.env.get('CREW_CHIEF_ASK_TIMEOUT_MIN')
      case 'night.ask':
        return await $.env.get('CREW_CHIEF_NIGHT_ASK_MIN')
      case 'handoff.mode':
        return await $.env.get('CREW_CHIEF_HANDOFF')
      case 'notify.agent':
        return await $.env.get('CREW_CHIEF_NOTIFY_AGENT')
      case 'notify.native':
        return await $.env.get('CREW_CHIEF_NOTIFY_NATIVE')
      case 'notify.min':
        return await $.env.get('CREW_CHIEF_NOTIFY_MIN')
      case 'panel.style':
        return await $.env.get('CREW_CHIEF_PANEL_STYLE')
      case 'panel.click':
        return await $.env.get('CREW_CHIEF_PANEL_CLICK')
      case 'panel.perf':
        return await $.env.get('CREW_CHIEF_PANEL_PERF')
      case 'ui.statusline':
        return await $.env.get('CREW_CHIEF_UI_STATUSLINE')
      default:
        return undefined
    }
  } catch (err) {
    return undefined
  }
}

async function storedRaw($, key) {
  try {
    return await $.store.get(storeKey(key))
  } catch (err) {
    return undefined
  }
}

// The value in force and where it came from: { value, source: 'env' | 'saved' | 'default' }.
async function cfgState($, key) {
  return resolveSetting(key, await envRaw($, key), await storedRaw($, key))
}

async function cfgGet($, key) {
  return (await cfgState($, key)).value
}

// Saves one value as /crew-config set does (for the short forms other commands offer, such as /crew-ui panel).
// { ok: true, value, source } with the value in force afterwards, or { ok: false, error: 'invalid' | 'store' }.
async function cfgSet($, key, text) {
  const parsed = parseSetting(key, text)
  if (!parsed.ok) return { ok: false, error: 'invalid' }
  try {
    await $.store.set(storeKey(key), storeText(key, parsed.value))
  } catch (err) {
    return { ok: false, error: 'store' }
  }
  const st = await cfgState($, key)
  return { ok: true, value: st.value, source: st.source }
}

async function allValues($) {
  const out = {}
  for (const key of SETTING_KEYS) out[key] = (await cfgState($, key)).value
  return out
}

// panel.perf theme|all with no theme mod reading ~/.claude/perf-mode.json (perfReaderKnown): it works as agents.
function perfNote(key, value) {
  if (key !== 'panel.perf' || perfReaderKnown() || (value !== 'theme' && value !== 'all')) return ''
  return ' (works as agents: no theme mod reads ~/.claude/perf-mode.json, see the README)'
}

async function listText($) {
  await perfReaderRefresh($).catch(() => false)
  const lines = ['crew-config: the numbers crew-chief uses. Change one with /crew-config set <name> <value>, put one back with /crew-config reset <name> (or all).', '']
  let group = ''
  for (const key of SETTING_KEYS) {
    const def = SETTINGS[key]
    if (def.group !== group) {
      group = def.group
      lines.push(group + ':')
    }
    const st = await cfgState($, key)
    const mark = st.source === 'default' ? '' : st.source === 'env' ? ` [${envName(key)} in the environment wins]` : ' [saved]'
    lines.push(`  ${key} = ${formatSetting(key, st.value)}${mark}${perfNote(key, st.value)}  ${def.what}`)
  }
  const problems = checkSettings(await allValues($))
  if (problems.length > 0) lines.push('', 'Note: ' + problems.join('; ') + '.')
  return lines.join('\n')
}

async function configSessionStart($) {
  try {
    await $.command.register({ name: 'crew-config', description: 'Show or change crew-chief\'s thresholds (compact, saver, question deadline)', immediate: true, argumentHint: '[set <name> <value> | reset <name>|all]' })
  } catch (err) {
    // The name is taken, or an older Claude Code: the environment variables still work.
  }
}

function registerConfig(on) {
  on('command.run', { command: 'crew-config' }, async ($, e) => {
    const words = String(e.args || '').trim().split(/\s+/).filter(Boolean)
    const verb = (words[0] || '').toLowerCase()
    if (verb === '' || verb === 'status' || verb === 'list' || verb === 'show') return { text: await listText($) }
    if (verb === 'reset') {
      const target = (words[1] || '').toLowerCase()
      const keys = target === 'all' ? SETTING_KEYS : SETTING_KEYS.includes(target) ? [target] : []
      if (keys.length === 0) return { text: 'crew-config: reset <name> or reset all. Names: ' + SETTING_KEYS.join(', ') + '.' }
      for (const key of keys) {
        try {
          await $.store.set(storeKey(key), '')
        } catch (err) {
          return { text: 'crew-config: the plugin store is not available here, so nothing can be saved or reset (the environment variables still work).' }
        }
      }
      if (keys.includes('panel.perf')) await perfFileWrite($)
      return { text: `crew-config: ${target === 'all' ? 'every value is' : target + ' is'} back to the default${target === 'all' ? '' : ' (' + formatSetting(target, SETTINGS[target].def) + ')'}.` }
    }
    const rest = verb === 'set' ? words.slice(1) : words
    const key = (rest[0] || '').toLowerCase()
    if (!SETTING_KEYS.includes(key)) return { text: `crew-config: "${rest[0] ?? ''}" is not a setting. Names: ${SETTING_KEYS.join(', ')}. /crew-config shows them with what they do.` }
    const raw = rest.slice(1).join(' ')
    const parsed = parseSetting(key, raw)
    if (!parsed.ok) return { text: `crew-config: "${raw}" is not valid for ${key}: ${SETTINGS[key].what}.` }
    try {
      await $.store.set(storeKey(key), storeText(key, parsed.value))
    } catch (err) {
      return { text: 'crew-config: the plugin store is not available here, so the value cannot be saved (use the environment variable instead).' }
    }
    if (key === 'panel.perf') {
      await perfFileWrite($)
      await perfReaderRefresh($).catch(() => false)
    }
    const st = await cfgState($, key)
    const envNote = (st.source === 'env' ? ` ${envName(key)} is set in the environment and still wins (${formatSetting(key, st.value)}).` : '') + perfNote(key, st.value).replace(/^ \((.*)\)$/, ' It $1.')
    const problems = checkSettings(await allValues($))
    return { text: `crew-config: ${key} = ${formatSetting(key, parsed.value)}, saved.${envNote}${problems.length > 0 ? ' Note: ' + problems.join('; ') + '.' : ''}` }
  })
}

// ===== ask ===================================================================
// crew-chief questions with a deadline. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
// $.ui.ask has no timeout, so a question nobody answers (a long job left running overnight) would stay open
// for good. Every question the mod asks goes through askWithDeadline, which notes the question's text here.
// $.ui.ask opens the dialog as a tool.call of AskUserQuestion that this mod's own hooks see; the hook below
// races that call against a timer, and when the timer wins it returns the flow's safe default as the
// answer: the engine closes the dialog and $.ui.ask resolves to that label, exactly as if it was clicked.
// (That hook is only reached while the asking hook still runs; see askWithDeadline for the other case.)
// Only questions noted here are raced: an AskUserQuestion that Claude raises itself passes through, except in a
// night's opening phase (hooks/src/night.js), where it is closed with a NO_ANSWER label after night.ask minutes.
// CREW_CHIEF_ASK_TIMEOUT_MIN sets the minutes (default 20, at most 30; "off" or "0" = no deadline).
// question text -> { fallback, ms, lang, announced }
const deadlines = new Map()
const EXPIRED = Symbol('expired')

// Asks like $.ui.ask (same answer, same rejection when dismissed or when nobody can be asked), but an
// unanswered question resolves to `fallback` after the deadline. Two things enforce it:
//   - the sibling hook in registerAsk closes the dialog with that answer. It is only reached while the
//     hook that asks is still running (a $ call made after its hook returned skips this mod's own hooks);
//   - the race below, so the flow moves on with the default in every case, even when the dialog could
//     not be closed (then a late click on it changes nothing).
// `look` (optional) only changes how the band draws the question outside the terminal (see uiAskStart).
// `night` (optional): while a night is open (hooks/src/night.js) the question is never shown; it is answered at once
// with `night.answer` when given (it may be the yes), else with `fallback`. `night.hold`: that answer starts a compaction.
async function askWithDeadline($, question, answers, fallback, look, night) {
  let quiet
  try {
    quiet = await nightQuietAnswer($, question, answers, fallback, night)
  } catch (err) {
    quiet = undefined
  }
  if (quiet !== undefined) return quiet
  let entry
  try {
    const ms = (await cfgGet($, 'ask.timeout')) * 60_000
    const label = pickFallback(answers, fallback)
    if (ms > 0 && label === undefined) {
      $.ui.log('crew-chief: no safe default for a question, it has no deadline: ' + String(fallback), { to: 'debug' })
    }
    if (ms > 0 && label !== undefined) {
      // Two questions with the same text at once share the first one's entry.
      entry = deadlines.get(question) ?? { fallback: label, ms, lang: await resolveLang($), question, announced: false }
    }
  } catch (err) {
    entry = undefined // no deadline then; the question itself still goes out
  }
  await rowRefreshSurfaces($)
  if (entry === undefined) {
    const band = uiAskStart($, question, answers, look)
    if (band === undefined) return $.ui.ask(question, answers)
    try {
      return await band.promise
    } finally {
      band.close()
    }
  }
  const owner = !deadlines.has(question)
  if (owner) deadlines.set(question, entry)
  let timer
  const band = uiAskStart($, question, answers, look)
  try {
    const asked = band !== undefined ? band.promise : $.ui.ask(question, answers)
    asked.catch(() => {}) // dismissed after the deadline: nobody is listening any more
    const expired = new Promise((resolve) => {
      timer = $.clock.after(entry.ms, () => resolve(EXPIRED))
    })
    const first = await Promise.race([asked, expired])
    if (first !== EXPIRED) return first
    announceExpiry($, entry)
    return entry.fallback
  } finally {
    try {
      if (timer) timer.cancel()
    } catch (err) {
      // Already fired.
    }
    if (band !== undefined) band.close() // an expired question leaves the band
    if (owner && deadlines.get(question) === entry) deadlines.delete(question)
  }
}

function deadlineFor(e) {
  const qs = Array.isArray(e.questions) ? e.questions : []
  if (qs.length !== 1 || !qs[0] || typeof qs[0].question !== 'string') return undefined
  return deadlines.get(qs[0].question)
}

// Once per question, whichever of the two deadlines comes first.
function announceExpiry($, d) {
  if (d.announced) return
  d.announced = true
  try {
    const min = minutesLabel(d.ms)
    $.ui.log('crew-chief: question unanswered for ' + min + ' min, answered "' + d.fallback + '": ' + d.question.slice(0, 120), { to: 'debug' })
    $.ui.toast(t(d.lang, 'ask_expired_toast', { min, answer: d.fallback }), { timeoutMs: 15000 })
  } catch (err) {
    // The default answer stands either way.
  }
}

function registerAsk(on) {
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    let d
    try {
      d = deadlineFor(e)
    } catch (err) {
      d = undefined
    }
    if (d === undefined) {
      try {
        d = await nightOpeningDeadline($)
      } catch (err) {
        d = undefined
      }
    }
    if (d === undefined) return next(e)
    let timer
    let answered
    try {
      const expired = new Promise((resolve) => {
        timer = $.clock.after(d.ms, () => resolve(EXPIRED))
      })
      answered = next(e)
      answered.catch(() => {})
      const first = await Promise.race([answered.then((r) => ({ r })), expired])
      if (first === EXPIRED) {
        if (d.night !== undefined) {
          // The night's opening interview: every question of the batch is answered with the NO_ANSWER label.
          const qs = (Array.isArray(e.questions) ? e.questions : []).filter((q) => q && typeof q.question === 'string')
          await nightAnnounceExpiry($, d, qs.length)
          return { result: { questions: e.questions, answers: Object.fromEntries(qs.map((q) => [q.question, d.fallback])), afkTimeoutMs: d.ms } }
        }
        announceExpiry($, d)
        return { result: { questions: e.questions, answers: { [d.question]: d.fallback }, afkTimeoutMs: d.ms } }
      }
      return first.r
    } catch (err) {
      // A dismissed dialog rejects `answered`: pass that on unchanged. Anything else: no deadline.
      return answered !== undefined ? answered : next(e)
    } finally {
      try {
        if (timer) timer.cancel()
      } catch (err) {
        // Already fired.
      }
    }
  })
}

// ===== handoff ===============================================================
// Finds the project's handoff files (see skills/crew-handoff) for the compact flow and /crew-tidy.
// The lookup order matches scripts/compact-restore.sh: STATUS.md (or durum.md) next to the working
// directory, then at the repository root, then one level down. A mod's analyser follows `$` only into
// function declarations, so this is one, shared by the files that need it.

// Shared by every part of the bundle: a call that may throw, with a fallback value.
async function safe(fn, fallback) {
  try {
    return await fn()
  } catch (err) {
    return fallback
  }
}

async function findHandoff($) {
  const cwd = await safe(() => $.session.cwd(), undefined)
  if (!cwd) return undefined
  const root = (await safe(() => $.session.root(), cwd)) || cwd
  const dirs = [...new Set([cwd, root])]
  const names = ['STATUS.md', 'durum.md']
  let dir
  let status
  for (const d of dirs) {
    for (const n of names) {
      if (!status && (await safe(() => $.fs.exists(`${d}/${n}`), false))) {
        dir = d
        status = `${d}/${n}`
      }
    }
  }
  if (!status) {
    const entries = await safe(() => $.fs.list(root), [])
    for (const entry of entries) {
      if (status || entry.kind !== 'dir' || entry.name.startsWith('.') || entry.name === 'node_modules') continue
      for (const n of names) {
        if (!status && (await safe(() => $.fs.exists(`${root}/${entry.name}/${n}`), false))) {
          dir = `${root}/${entry.name}`
          status = `${dir}/${n}`
        }
      }
    }
  }
  let tasks
  for (const d of [dir, cwd, root]) {
    if (!tasks && d && (await safe(() => $.fs.exists(`${d}/tasks.json`), false))) tasks = `${d}/tasks.json`
  }
  let progress
  if (dir) {
    for (const n of ['PROGRESS.md', 'ilerleme.md']) {
      if (!progress && (await safe(() => $.fs.exists(`${dir}/${n}`), false))) progress = `${dir}/${n}`
    }
  }
  if (!status && !tasks) return undefined
  return { dir, status, tasks, progress }
}

// ===== stats-flow ============================================================
// /crew-report and the cache-cooling hint. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
//   /crew-report   tokens (exact) and cost (approximate) by role (main or subagent) and model, plus how
//                  much of the output came from subagents and from Sonnet or Haiku: whether the routing
//                  is moving work to cheaper tiers. Claude Code reports one session total, so each
//                  request is credited with what the total grew by since the previous one ended.
//   cache hint     a toast on your next prompt when the prompt cache has probably gone cold during an
//                  idle gap and the context is big, because that message re-reads it at the full price.
//                  The cache lifetime is learned from the usage numbers (see report-logic.mjs); until an
//                  expiry has been seen nothing is warned. CREW_CHIEF_CACHE_HINT=off turns it off.
// Nothing is written outside the plugin's store (the learned gap lengths). Nothing leaves the machine.
function freshStats() {
  return { stats: newStats(), runs: new Map(), lastCost: undefined, lastMainEndAt: undefined, lastMainContext: 0, stepGap: undefined, hint: undefined, warnedFor: undefined }
}

let sf = freshStats()

async function loadHint($) {
  if (sf.hint !== undefined) return sf.hint
  const text = await safe(() => $.store.get('cache_hint'), undefined)
  sf.hint = typeof text === 'string' ? parseHint(text) : {}
  return sf.hint
}

async function statsSessionStart($) {
  sf = freshStats()
  try {
    await $.command.register({
      name: 'crew-report',
      description: t(await resolveLang($), 'cmd_report_description'),
      argumentHint: '',
    })
  } catch (err) {
    // The name is taken: the rest still works.
  }
}

function statsReset() {
  sf = freshStats()
}

// A compaction (or any change of conversation) guarantees a cache miss on the next request: that gap
// must not be mistaken for the cache's lifetime.
function statsNoteBoundary() {
  sf.lastMainEndAt = undefined
  sf.stepGap = undefined
}

// Before a request goes out: how long the main conversation sat idle since its last one.
async function statsStepStart($, e) {
  if (e.agentId !== undefined) return
  const now = await $.clock.now()
  sf.stepGap = sf.lastMainEndAt === undefined ? undefined : now - sf.lastMainEndAt
}

// After a request: add it to the tallies, and learn from it how long the cache lives.
async function statsStepEnd($, e, result) {
  try {
    const main = e.agentId === undefined
    const usage = result?.usage ?? undefined
    const family = modelFamily(usage?.model ?? e.model)
    const now = await $.clock.now()
    const cost = await safe(() => $.session.usage(), undefined)
    const usd = cost?.cost?.usd
    // The total starts at 0 and falls back to 0 after /clear: a drop means a freshStats total, all of it new.
    let grew
    if (typeof usd === 'number') {
      const base = sf.lastCost ?? 0
      grew = usd >= base ? usd - base : usd
      sf.lastCost = usd
    }
    addStep(sf.stats, { role: main ? 'main' : 'subagent', family, usage, usd: grew })
    if (!main) addRun(sf.runs, { id: e.agentId, family, usage, usd: grew })
    if (main && usage) {
      const input = Number(usage.input_tokens) || 0
      const cacheRead = Number(usage.cache_read_input_tokens) || 0
      const cacheWrite = Number(usage.cache_creation_input_tokens) || 0
      const verdict = classifyGap({ gapMs: sf.stepGap, input, cacheRead, cacheWrite })
      if (verdict !== undefined) {
        const hint = nextHint(await loadHint($), sf.stepGap, verdict)
        sf.hint = hint
        await safe(() => $.store.set('cache_hint', JSON.stringify(hint)), undefined)
      }
      sf.lastMainContext = input + cacheRead + cacheWrite
    }
    if (main) sf.lastMainEndAt = now
  } catch (err) {
    // The tallies are a convenience; never get in the way of a request.
  }
}

// On a typed prompt: warn once per idle gap if the cache has probably gone cold.
async function cacheOnPrompt($) {
  try {
    if ((await safe(() => $.env.get('CREW_CHIEF_CACHE_HINT'), undefined)) === 'off') return
    if (sf.lastMainEndAt === undefined || sf.warnedFor === sf.lastMainEndAt) return
    const now = await $.clock.now()
    const gap = now - sf.lastMainEndAt
    if (!shouldWarnCold(await loadHint($), gap, sf.lastMainContext)) return
    sf.warnedFor = sf.lastMainEndAt
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'cache_cold', { idle: formatDuration(gap, unitsFor(lang)), tokens: fmtTokens(sf.lastMainContext) }), { timeoutMs: 12000 })
  } catch (err) {
    // A missing hint is better than a broken prompt.
  }
}

async function buildStatsReport($) {
  const lang = await resolveLang($)
  const rows = statsRows(sf.stats)
  if (rows.length === 0) return t(lang, 'report_none')
  const out = [t(lang, 'report_title')]
  for (const r of rows) {
    out.push(
      '- ' +
        t(lang, 'report_row', {
          role: t(lang, r.role === 'main' ? 'role_main' : 'role_subagent'),
          model: r.family,
          requests: r.requests,
          input: fmtTokens(r.input),
          cacheRead: fmtTokens(r.cacheRead),
          cacheWrite: fmtTokens(r.cacheWrite),
          output: fmtTokens(r.output),
          usd: fmtUsd(r.usd),
        }),
    )
  }
  const total = await safe(() => $.session.usage(), undefined)
  if (typeof total?.cost?.usd === 'number') out.push(t(lang, 'report_total', { usd: fmtUsd(total.cost.usd) }))
  const share = routingShare(rows)
  if (share.total > 0) out.push(t(lang, 'report_share', { sub: share.subagent, cheaper: share.cheaper }))
  const top = topRuns(sf.runs, 3)
  if (top.length > 0) {
    const agents = await safe(() => $.agent.list(), [])
    out.push(t(lang, 'report_runs_head'))
    for (const r of top) {
      const known = Array.isArray(agents) ? agents.find((a) => a.id === r.id) : undefined
      const name = known ? String(known.description || known.type || r.id).slice(0, 40) : r.id.slice(0, 12)
      out.push('- ' + t(lang, 'report_run_row', { name, model: r.family, requests: r.requests, usd: fmtUsd(r.usd) }))
    }
  }
  out.push(t(lang, 'report_note'))
  return out.join('\n')
}

function registerStats(on) {
  on('command.run', { command: 'crew-report' }, async ($) => ({ text: await buildStatsReport($) }))
}

// ===== reset-flow ============================================================
// crew-chief reset flow: tells you when a plan limit you were close to has reset, and, when a limit
// actually stops Claude, offers to send "continue" for you at the moment it resets. Part of the mod in
// hooks/register.js.
//
//   - Measurements only arrive after a response, so nothing would wake an idle session when a window
//     rolls over. A timer is set for each window that was close to full (90 % or more) and is due to
//     reset within 12 hours; it fires a toast at the reset time.
//   - A limit that really stops a turn arrives as the StopFailure event with error "rate_limit" (not the
//     100 % mark: with usage credits you keep working past it). Then the person is asked whether to
//     send "continue" at the reset. Only on a yes, only for a reset within 6 hours, and never if the
//     person typed something in the meantime. The message says who sent it (it is not sent as the
//     person's own words).
// CREW_CHIEF_RESET=off turns both off. Timers last as long as the session does.
const NEAR_FULL_PERCENT = 90
const TOAST_HORIZON_MS = 12 * 60 * 60 * 1000
const CONTINUE_HORIZON_MS = 6 * 60 * 60 * 1000
const BUFFER_MS = 15_000

const CONTINUE_TEXT =
  'crew-chief: the usage limit has reset, as the user asked in advance. Continue where you left off, with the same task.'

let generation = 0

function freshReset() {
  return { scheduled: new Set(), planned: new Set(), never: false, asking: false, lastPromptAt: 0 }
}

let rf = freshReset()

// A timer set before /clear or a new session must not act in the next one: each carries the generation
// it was set in.
function resetResetFlow() {
  rf = freshReset()
  generation += 1
  open.reset = false
}

function resetNotePrompt(now) {
  rf.lastPromptAt = now
}

async function off($) {
  try {
    return (await $.env.get('CREW_CHIEF_RESET')) === 'off'
  } catch (err) {
    return false
  }
}

function resetMs(window) {
  const at = typeof window.resetsAt === 'string' ? Date.parse(window.resetsAt) : NaN
  return Number.isFinite(at) ? at : undefined
}

// Called with each usage reading. Sets one timer per (window, reset time) for a window that is close
// to full and resets soon; the toast comes when the window rolls over, even if the session is idle.
async function resetOnUsage($, usage) {
  if (await off($)) return
  const now = await $.clock.now()
  for (const w of usage?.rateLimits ?? []) {
    if (w.kind !== 'five_hour' && w.kind !== 'seven_day') continue
    const at = resetMs(w)
    if (at === undefined || w.percentUsed < NEAR_FULL_PERCENT) continue
    const wait = at - now
    const key = w.kind + '|' + at
    if (wait <= 0 || wait > TOAST_HORIZON_MS || rf.scheduled.has(key)) continue
    rf.scheduled.add(key)
    const born = generation
    $.clock.after(wait + BUFFER_MS, () => (born === generation ? announceReset($, w.kind) : undefined))
  }
}

async function announceReset($, kind) {
  if (await off($)) return
  const lang = await resolveLang($)
  $.ui.toast(t(lang, 'reset_toast', { window: windowName(lang, kind) }), { timeoutMs: 15000 })
}

// The window that stopped the turn: the fullest one that has a reset time in the future.
function blockingWindow(usage, now) {
  let best
  for (const w of usage?.rateLimits ?? []) {
    const at = resetMs(w)
    if (at === undefined || at <= now) continue
    if (best === undefined || w.percentUsed > best.window.percentUsed) best = { window: w, at }
  }
  return best
}

async function offerContinue($) {
  if (rf.asking || open.saver || open.compact || open.reset) return
  const now = await $.clock.now()
  const usage = await $.session.usage()
  const hit = blockingWindow(usage, now)
  if (!hit) return
  const wait = hit.at - now
  const key = hit.window.kind + '|' + hit.at
  if (wait > CONTINUE_HORIZON_MS || rf.planned.has(key) || rf.never) return
  rf.asking = true
  open.reset = true
  try {
    const lang = await resolveLang($)
    const answers = [t(lang, 'limit_yes'), t(lang, 'limit_no'), t(lang, 'limit_never')]
    let answer
    try {
      answer = await askWithDeadline(
        $,
        t(lang, 'limit_ask', { window: windowName(lang, hit.window.kind), duration: formatDuration(wait, unitsFor(lang)) }),
        answers,
        answers[1],
      )
    } catch (err) {
      return
    }
    if (answer === answers[2]) {
      rf.never = true
    } else if (answer === answers[0]) {
      rf.planned.add(key)
      const askedAt = now
      const born = generation
      $.clock.after(wait + BUFFER_MS, () => (born === generation ? sendContinue($, askedAt, hit.window.kind) : undefined))
    }
  } finally {
    rf.asking = false
    open.reset = false
  }
}

async function sendContinue($, askedAt, kind) {
  if (await off($)) return
  if (rf.lastPromptAt > askedAt) return // the person is back and typing: leave it to them
  try {
    $.prompt.submit({ text: CONTINUE_TEXT }).catch(() => {})
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'limit_continue_toast', { window: windowName(lang, kind) }), { timeoutMs: 10000 })
  } catch (err) {
    // The session cannot take a prompt right now; nothing more to do.
  }
}

function registerReset(on) {
  // StopFailure: a turn ended on an error. Only a rate limit matters here. (Settings-hook events do not
  // reach a mod where an organization manages Claude Code; then the offer simply never comes.)
  on('classic.StopFailure', async ($, e, next) => {
    if (e.error === 'rate_limit' && !(await off($))) offerContinue($) // not awaited: the hook must not wait
    return next(e)
  })
}

// ===== compact-flow ==========================================================
// crew-chief compact flow: gets a long conversation compacted at a good moment, with nothing important
// lost, and only after the person says yes. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
// How it works (every step below was checked live on Claude Code 2.1.300, see CHANGELOG 0.6.0):
//   1. Past the "arm" size (250k tokens on a 1M window, 60 % of a small one) the next prompt carries a
//      one-time note telling Claude to call the tool crew_compact_checkpoint at the next natural phase
//      boundary (never mid-task). Claude decides when a phase is over.
//   2. The tool only takes note and returns at once (a tool that waited for the person would hold the turn
//      open, overnight if nobody is there). The person is asked after the turn has ended cleanly and the
//      session has stayed quiet for 10 seconds with no subagent running; otherwise at the next clean turn
//      end. If Claude never calls the tool, the same happens once the "ask" size is passed (400k, 85 % of
//      a small window). Nothing is compacted without a yes; an unanswered question counts as "not now".
//   3. On yes, Claude updates STATUS.md / tasks.json / PROGRESS.md (the handoff files, when the project
//      has them). Compaction waits until STATUS.md has changed (the gate) or the person overrides.
//   4. The compaction runs between turns with a detailed brief for the summarizer (compact-logic.mjs).
//      The same brief is added to a /compact the person types and to an automatic compaction.
//   5. After any compaction: the raw summary is saved, the summary is checked for the person's pinned
//      constraints and the open tasks, a toast says what was missing, and the transcript is checked for
//      lost lines. scripts/compact-restore.sh (SessionStart, compact) puts the pinned lines back.
// Environment: CREW_CHIEF_COMPACT=off turns the whole flow off; CREW_CHIEF_COMPACT_FOCUS=off only stops
// the brief being added to compactions; CREW_CHIEF_COMPACT_ARM / CREW_CHIEF_COMPACT_ASK set the sizes
// ("250k", "400k"). Nothing leaves the machine.
const TOOL_NAME = 'crew_compact_checkpoint'
const TOOL_MATCH = /^mcp__.+__crew_compact_checkpoint$/
// Stands in for ck.askTimer while the quiet time is being read.
const PENDING_TIMER = { cancel() {} }
const COMPACT_DELAY_MS = 1200
const RETRY_MS = 3000
const MAX_RETRIES = 3
const SUMMARIES_KEPT = 5
const TRANSCRIPTS_KEPT = 3
const MAX_UPDATE_RETRIES = 2
// A handoff file written up to this long before the approval counts as already updated (Claude had just done it).
const FRESH_BEFORE_MS = 10 * 60_000
const AGENT_WAIT_MS = 5000
const MAX_AGENT_WAITS = 36
// A /compact handed to the engine that never reached the session.compact hook: after this long the
// "already being arranged" guard is let go so the flow is not stuck for the rest of the session.
const PROMPT_WAIT_MS = 10 * 60_000
// After a yes, the request to update the handoff files goes in as a prompt of its own. If no turn has started
// this long after it (the submission was lost: seen live on 2.1.329), the compaction goes on without it.
const UPDATE_WAIT_MS = 2 * 60_000
// `waiting` is a subagent held on background work it owns (a server it started), on a plan's approval or
// on another agent: none of these is work that a compaction would cut in half, and a subagent that left a
// dev server running stays `waiting` for as long as the server lives, so it must never hold a compaction back.
const RUNNING_STATES = ['pending', 'running']

const TOOL_DESCRIPTION =
  'Propose compacting the conversation. Call it once, and only when a note from crew-chief says the context is large AND you have just finished a phase (a task done, tests passing, before an unrelated area). Never call it in the middle of work. It returns at once; the user is asked after your turn ends. Do not wait for an answer and do not call it again. When the user themselves asked for a compaction, call it with user_requested: true, whatever the context size. Never tell the user to run /compact because this tool said "not needed": /crew-compact does the same.'

const UPDATE_TEXT =
  'Update the handoff files of this project now, for those that exist: STATUS.md (Now, Next, Constraints = every rule the user gave, copied verbatim; keep the lines already there and only add new ones, Decisions, Failed attempts), tasks.json (only status and evidence change), PROGRESS.md (one dated line). If STATUS.md has no Constraints section, do not invent one; say so in your reply. If a Constraint already there looks stale, was contradicted by a later message or has an exception the user gave, do not delete it: name it in your one short line so the user can decide. Do not start any new work. Finish with one short line; the conversation is compacted right after your turn ends.'

// A project with no handoff files has nowhere to pin the user's rules. Nobody is asked here (a dialog would
// hold the compaction up while the person may be away): the answer only mentions /crew-chief:crew-handoff.
const SETUP_TEXT =
  'This project has no handoff files (STATUS.md, tasks.json, PROGRESS.md). Do not ask the user about them (no AskUserQuestion, no dialog) and do not create anything; carry on with the compaction exactly as if they had declined. Do not start any new work. Finish with one short line that also mentions, once, that handoff files were not set up and that /crew-chief:crew-handoff sets them up; the conversation is compacted right after your turn ends.'

async function updateText($) {
  return (await findHandoff($)) ? UPDATE_TEXT : SETUP_TEXT
}

const RESULTS = {
  noted: 'Noted. The user will be asked about compaction after this turn finishes. Do not wait for an answer; carry on and finish the turn normally. Do not call this tool again.',
  notNeeded: 'Not needed yet. Keep working; crew-chief will say when to propose a compaction. If the user themselves asked for a compaction, call this tool again with user_requested: true.',
  busy: 'A compaction is already being arranged. Nothing more to do about it.',
}

function freshCompact(toolReady = false, directRefused = false) {
  return {
    armed: false,
    nudged: false,
    never: false,
    asking: false,
    askedFallback: false,
    rearmAt: 0,
    plan: null,
    compacting: false,
    toolReady,
    bgTasks: [],
    wantAsk: null, // { phase } once the question is due at a quiet turn end
    askTimer: null, // the one pending grace timer
    activity: 0, // counts main-loop prompts and model requests
    steps: 0, // counts main-loop model requests only (a turn really ran)
    promptPending: false, // a /compact was handed to the engine and has not reached session.compact yet
    directRefused, // $.session.compact was refused in this session: later compactions go straight to /compact
  }
}

let ck = freshCompact()

// The context size the engine reported just before the last compaction, while it still reports that same size
// afterwards. The Desktop app (an SDK session) keeps the old figure until the next model request, the terminal
// counts the new transcript at once; until the figure changes, the band and the flow treat it as unknown.
let ctxStale

// Whether `tokens` is the size from before the last compaction (the engine has not measured again yet). The
// first different figure ends that for good.
function compactCtxStale(tokens) {
  if (ctxStale === undefined || typeof tokens !== 'number') return false
  if (tokens === ctxStale) return true
  ctxStale = undefined
  return false
}

async function ctxTokensNow($) {
  try {
    const tokens = (await $.session.usage())?.context?.tokens
    return typeof tokens === 'number' ? tokens : undefined
  } catch (err) {
    return undefined
  }
}

// session.start does not fire after /clear, so the tool registered at the start is still there: keep
// toolReady across a reset, and let compactSessionStart (a real start) decide it afresh.
function resetCompact() {
  cancelAskTimer()
  ck = freshCompact(ck.toolReady, ck.directRefused)
  ctxStale = undefined
  open.compact = false
}

// Each compaction starts a freshCompact cycle: arm again at the arm size, note again, ask again, and no plan
// left over from before it.
function cycleDone() {
  ck.armed = false
  ck.nudged = false
  ck.askedFallback = false
  ck.rearmAt = 0
  ck.plan = null
  ck.wantAsk = null
  cancelAskTimer()
  statsNoteBoundary()
}

function cancelAskTimer() {
  const timer = ck.askTimer
  ck.askTimer = null
  try {
    if (timer) timer.cancel()
  } catch (err) {
    // Already fired.
  }
}

// Called from the mod's main-loop prompt.submit and turn.step hooks: something started after the turn
// ended, so the question waits for the next clean turn end.
// True while a compaction question, plan or compaction is under way (the flow updates the handoff files itself).
function compactBusy() {
  return Boolean(ck.plan || ck.compacting || ck.asking)
}

// True when a compaction question is due but waits for a turn to end: Claude called the checkpoint tool, or the
// context passed the ask size. At night the Stop hook blocks every turn end, so the night mod puts up the hold file
// on this, the turn ends, and the usual flow (question auto-answered, handoff update, compaction) can run.
function compactWanted() {
  if (ck.never || ck.plan || ck.compacting || ck.asking) return false
  if (ck.wantAsk) return true
  return ck.armed && !ck.askedFallback && typeof ck.lastTokens === 'number' && typeof ck.askAt === 'number' && ck.lastTokens >= ck.askAt
}

// Counts prompts and model requests; unchanged between two moments means the session stayed quiet.
function compactActivity() {
  return ck.activity
}

// `kind` 'step': a main-loop model request, proof that a turn is running.
function compactNoteActivity(kind) {
  ck.activity += 1
  if (kind === 'step') ck.steps += 1
}

// compact.enabled (/crew-config, or CREW_CHIEF_COMPACT=off in the environment).
async function disabled($) {
  return (await safe(() => cfgGet($, 'compact.enabled'), 'on')) === 'off'
}

async function focusOff($) {
  return (await disabled($)) || (await safe(() => $.env.get('CREW_CHIEF_COMPACT_FOCUS'), undefined)) === 'off'
}

// ---- the project's handoff files ------------------------------------------------------------

async function mtimeOf($, path) {
  if (!path) return undefined
  const stat = await safe(() => $.fs.stat(path), undefined)
  return stat ? stat.mtimeMs : undefined
}

// The gate: a handoff file (STATUS.md, tasks.json or PROGRESS.md) has been written since the person approved, or
// just before it (Claude had already updated them). A project without handoff files has nothing to wait for.
async function gateSatisfied($, plan) {
  const h = await findHandoff($)
  if (!h) return true
  for (const file of [h.status, h.tasks, h.progress]) {
    const changed = await mtimeOf($, file)
    if (changed !== undefined && changed > plan.approvedAt - FRESH_BEFORE_MS) return true
  }
  return false
}

// ---- thresholds and the one-time note -------------------------------------------------------

async function limits($, usage) {
  // The sizes come from /crew-config or the environment. Only a size the person set is passed on, so it wins on a
  // small window too; the defaults scale down there, and compact.armpct / askpct set how far.
  const sized = async (key) => {
    const st = await safe(() => cfgState($, key), undefined)
    return st && st.source !== 'default' ? st.value : undefined
  }
  const arm = await sized('compact.arm')
  const ask = await sized('compact.ask')
  const armPct = await safe(() => cfgGet($, 'compact.armpct'), undefined)
  const askPct = await safe(() => cfgGet($, 'compact.askpct'), undefined)
  return compactThresholds(usage?.context?.window, { arm, ask, armFraction: armPct ? armPct / 100 : undefined, askFraction: askPct ? askPct / 100 : undefined })
}

// Called after every measurement and finished turn. Arms the flow at the arm size; after a "not now"
// it arms again only once the context has grown by another 100k.
async function compactUpdate($, usage) {
  if (await disabled($)) return
  const tokens = usage?.context?.tokens
  if (typeof tokens !== 'number' || compactCtxStale(tokens) || ck.never || ck.plan || ck.compacting) return
  const lim = await limits($, usage)
  ck.lastTokens = tokens
  ck.askAt = lim.ask
  if (!ck.armed && tokens >= Math.max(lim.arm, ck.rearmAt)) {
    ck.armed = true
    ck.nudged = false
    ck.askedFallback = false
  }
}

// The text added (once per arming) to the next prompt, or undefined.
async function compactNudge($) {
  if (!ck.armed || ck.nudged || ck.never || ck.plan || ck.compacting || !ck.toolReady) return undefined
  if (await disabled($)) return undefined
  ck.nudged = true
  const usage = await safe(() => $.session.usage(), undefined)
  const tokens = usage?.context?.tokens
  const name = `mcp__${$.plugin.name}__${TOOL_NAME}`
  return `[crew-chief] The context is about ${tokensLabel(tokens)} tokens; quality and cost both get worse from here. At the next natural phase boundary (a task finished, tests passing, before starting an unrelated area; never in the middle of work) call the tool ${name} once with a one-line phase summary. It returns at once and the user is asked after your turn ends; do not wait for an answer and do not call it again.`
}

// ---- asking and planning --------------------------------------------------------------------

// ---- what is running right now ---------------------------------------------------------------
// Subagents always end and bring a result back, so a compaction waits for them. A dev server or watcher
// left open in the background never ends and compaction does not touch it, so those only get shown (and
// named to the summarizer), never waited for. The processes come from the Stop event's background_tasks.

async function agentCounts($) {
  const list = await safe(() => $.agent.list(), [])
  return {
    running: list.filter((a) => RUNNING_STATES.includes(a.status)).length,
    waiting: list.filter((a) => a.status === 'waiting').length,
  }
}

async function runningAgents($) {
  return (await agentCounts($)).running
}

async function dirtyFiles($) {
  const r = await safe(() => $.process.run(['git', 'status', '--porcelain']), undefined)
  if (!r || r.exitCode !== 0) return undefined
  return r.stdout.split('\n').filter((line) => line.trim() !== '').length
}

function processNames() {
  return ck.bgTasks.map((task) => task.command || task.description || task.id).filter(Boolean)
}

// With the task id: after a compaction Claude no longer remembers the handles of background tasks it started
// (anthropics/claude-code#29193), so the summary should keep them.
function processHandles() {
  return ck.bgTasks.map((task) => (task.id ? task.id + ': ' : '') + (task.command || task.description || '')).filter(Boolean)
}

// The state in one sentence (the question's plain text: the terminal, the dialog) and as short facts (the
// Desktop card's chips), from one read of the agents, the background processes and git.
async function stateLine($, lang, agents, waiting) {
  const parts = [t(lang, 'ck_state_agents', { n: agents })]
  const facts = []
  if (waiting > 0) {
    parts.push(t(lang, 'ck_state_waiting', { n: waiting }))
    facts.push(t(lang, 'ck_fact_waiting', { n: waiting }))
  }
  const names = processNames()
  if (names.length > 0) {
    parts.push(t(lang, 'ck_state_shells', { n: names.length, list: names.slice(0, 3).map((n) => n.slice(0, 40)).join(', ') }))
    facts.push(t(lang, 'ck_fact_shells', { n: names.length }))
  }
  const dirty = await dirtyFiles($)
  if (dirty !== undefined) {
    parts.push(t(lang, 'ck_state_dirty', { n: dirty }))
    facts.push(t(lang, 'ck_fact_dirty', { n: dirty }))
  }
  facts.push(t(lang, 'ck_fact_agents', { n: agents }))
  return { line: t(lang, 'ck_state', { parts: parts.join(', ') }), facts }
}

async function askAndPlan($, why) {
  if (ck.asking || open.saver || open.reset) return 'busy'
  const { running: agents, waiting } = await agentCounts($)
  if (agents > 0) return 'subagents'
  ck.asking = true
  open.compact = true
  try {
    const lang = await resolveLang($)
    const usage = await safe(() => $.session.usage(), undefined)
    const tokens = usage?.context?.tokens
    const answers = [t(lang, 'ck_yes'), t(lang, 'ck_later'), t(lang, 'ck_never')]
    const phase = why.phase ? t(lang, 'ck_phase', { phase: why.phase }) : ''
    const state = await stateLine($, lang, agents, waiting)
    // On Desktop the question is a card: a topic, one short line, the facts as chips, what happens in one line.
    const card = {
      kind: 'card',
      topic: t(lang, 'ck_topic'),
      question: t(lang, 'ck_question'),
      facts: cardFacts([t(lang, 'ck_fact_ctx', { tokens: tokensLabel(tokens) }), why.phase ? t(lang, 'ck_fact_phase', { phase: why.phase }) : '', ...state.facts]),
      note: t(lang, 'ck_note'),
      quiet: 2, // "don't ask again": a quiet text button at the end
      // Where the Desktop status line is drawn the question is not a card but a small lit chip at the line's end
      // (pressed: answers[0]; its ✕: answers[1]); "don't ask again" is /crew-compact never there.
      chip: { text: typeof tokens === 'number' ? `⇣ compact ${tokensLabel(tokens)}` : '⇣ compact', yes: 0, no: 1, toast: t(lang, 'ck_chip_toast') },
    }
    let answer
    try {
      // Unanswered: "not now", the same as clicking it. At night: yes, nobody is there to ask (hooks/src/night.js).
      answer = await askWithDeadline($, t(lang, 'ck_ask', { tokens: tokensLabel(tokens), phase, state: state.line }), answers, answers[1], card, { answer: answers[0], hold: true })
    } catch (err) {
      return 'unavailable'
    }
    if (answer === answers[0]) {
      ck.plan = { approvedAt: await $.clock.now(), retries: 0 }
      return 'approved'
    }
    if (answer === answers[2]) {
      ck.never = true
      return 'never'
    }
    ck.armed = false
    ck.rearmAt = (typeof tokens === 'number' ? tokens : 0) + (await safe(() => cfgGet($, 'compact.reask'), 100_000))
    return 'declined'
  } finally {
    ck.asking = false
    open.compact = false
  }
}

// Asks Claude, in a new turn, to update the handoff files (the path with no tool call to answer). The yes is
// never left hanging on that prompt: if the submission is refused, or no turn has started UPDATE_WAIT_MS later,
// the compaction goes on without the update.
async function requestStateUpdate($) {
  const plan = ck.plan
  const text = 'crew-chief: the user approved compacting this conversation. ' + (await updateText($))
  if (plan) plan.requestedSteps = ck.steps
  $.prompt.submit({ text }).catch(() => updateLost($, plan))
  if (!plan) return
  $.clock.after(UPDATE_WAIT_MS, () => {
    if (ck.plan === plan && ck.steps === plan.requestedSteps) return updateLost($, plan)
  })
}

async function updateLost($, plan) {
  if (!plan || ck.plan !== plan || ck.asking || ck.compacting) return
  $.ui.toast(t(await resolveLang($), 'toast_compact_update_lost'), { timeoutMs: 12000 })
  scheduleCompaction($)
}

// Right after a yes. Handoff files Claude wrote in the last few minutes already pass the gate (advancePlan
// would let the compaction through after the update turn anyway), so the compaction goes on without one more
// turn. Otherwise Claude is asked to update them first. A project with no handoff files still gets that turn:
// its answer names /crew-chief:crew-handoff.
async function afterApproval($) {
  const plan = ck.plan
  if (!plan) return
  if ((await findHandoff($)) && (await gateSatisfied($, plan))) {
    if (ck.plan === plan) scheduleCompaction($)
    return
  }
  requestStateUpdate($)
}

// After a clean turn end: wait compact.quiet seconds, then ask if nothing started meanwhile. At most one timer.
async function scheduleAsk($) {
  if (ck.askTimer) return
  ck.askTimer = PENDING_TIMER // a second call during the read below must not start a second timer
  const cycle = ck
  const seen = ck.activity
  const graceMs = (await safe(() => cfgGet($, 'compact.quiet'), 10)) * 1000
  if (cycle !== ck || ck.askTimer !== PENDING_TIMER) return // /clear, /resume, a new session or a cancel since
  ck.askTimer = $.clock.after(graceMs, () => {
    if (cycle !== ck) return // /clear, /resume or a new session since
    ck.askTimer = null
    return askAfterGrace($, seen)
  })
}

async function askAfterGrace($, seen) {
  const why = ck.wantAsk
  if (!why) return
  if (!ck.armed || ck.never || ck.plan || ck.compacting || (await disabled($))) {
    ck.wantAsk = null
    return
  }
  if (ck.activity !== seen) return // a new turn started: ask at its end instead
  const outcome = await askAndPlan($, why)
  // 'busy' (another question is open) and 'subagents' keep the request for the next clean turn end.
  if (outcome === 'busy' || outcome === 'subagents') return
  ck.wantAsk = null
  if (outcome === 'approved') await afterApproval($)
  // Dismissed, or nobody can be asked: the 400k fallback does not ask again in this cycle either.
  else if (outcome === 'unavailable') ck.askedFallback = true
}

async function advancePlan($) {
  const plan = ck.plan
  if (!plan || ck.asking || open.saver || open.reset) return
  if (await gateSatisfied($, plan)) {
    scheduleCompaction($)
    return
  }
  // Claude was already asked to update and its turn is over with the files untouched: it found them current.
  // Asking the same question again only loops, so the compaction goes on.
  if (plan.retries > 0) {
    scheduleCompaction($)
    return
  }
  const lang = await resolveLang($)
  const answers = [t(lang, 'ck_gate_anyway'), t(lang, 'ck_gate_retry'), t(lang, 'ck_gate_cancel')]
  ck.asking = true
  open.compact = true
  let answer
  try {
    // Unanswered: "cancel", the same as clicking it. At night: compact anyway (the update turn already ran).
    answer = await askWithDeadline($, t(lang, 'ck_gate_ask'), answers, answers[2], undefined, { answer: answers[0], hold: true })
  } catch (err) {
    answer = answers[2]
  } finally {
    ck.asking = false
    open.compact = false
  }
  if (answer === answers[0]) {
    scheduleCompaction($)
  } else if (answer === answers[1] && plan.retries < MAX_UPDATE_RETRIES) {
    plan.retries += 1
    requestStateUpdate($)
  } else {
    const usage = await safe(() => $.session.usage(), undefined)
    const tokens = usage?.context?.tokens
    ck.plan = null
    ck.armed = false
    ck.rearmAt = (typeof tokens === 'number' ? tokens : 0) + (await safe(() => cfgGet($, 'compact.reask'), 100_000))
  }
}

// The question the person asked for (/crew-compact, or the band's compact key): clears "never", asks when the
// loop is free (a command or a key must not hold the turn while the person answers).
function compactAskLater($) {
  ck.never = false
  $.clock.after(300, async () => {
    const outcome = await askAndPlan($, {})
    if (outcome === 'approved') await afterApproval($)
    else if (outcome === 'subagents') $.ui.toast(t(await resolveLang($), 'ck_wait_agents'), { timeoutMs: 10000 })
  })
}

// For the band: the token count at which compaction is advised (the "ask" size), or undefined.
async function compactAskAt($, usage) {
  try {
    if (await disabled($)) return undefined
    return (await limits($, usage)).ask
  } catch (err) {
    return undefined
  }
}

// For the band: whether the compact key should show. Not while a question, a plan or a compaction is under way,
// not after "don't ask again", and not after "not now" until the context has grown by another 100k (the flow
// re-arms then), so a "not now" is not answered by a button that stays.
function compactKeyDue(tokens) {
  if (typeof tokens !== 'number') return false
  return !ck.never && !ck.plan && !ck.compacting && !ck.asking && tokens >= ck.rearmAt
}

// The band's compact key. Does nothing while a question or compaction is already under way.
function compactBandPress($) {
  if (ck.plan || ck.compacting || ck.asking) return
  compactAskLater($)
}

// Called after each finished main turn.
// `reason` is how the turn ended. Only a turn that ended with an answer counts as a phase boundary: after an
// interrupt (Esc) the update may be half done, and after an error or a refusal nothing was finished.
async function compactTurnComplete($, usage, reason) {
  ck.steps += 1 // a turn ran (the update request's watchdog only waits for one)
  if (await disabled($)) return
  await compactUpdate($, usage)
  const clean = reason === undefined || reason === 'answer'
  if (ck.plan) {
    if (clean) await advancePlan($)
    return
  }
  if (!clean) return
  const tokens = usage?.context?.tokens
  if (compactCtxStale(tokens)) return
  if (!ck.armed || ck.never || ck.compacting || ck.asking) return
  if (!ck.wantAsk && !ck.askedFallback && typeof tokens === 'number' && tokens >= (await limits($, usage)).ask && (await safe(() => cfgGet($, 'compact.fallback'), 'on')) === 'on') {
    // Claude never called the tool: ask anyway, once per cycle.
    ck.askedFallback = true
    ck.wantAsk = {}
  }
  if (ck.wantAsk) scheduleAsk($) // the hook never waits for the person
}

// ---- running the compaction -----------------------------------------------------------------

function scheduleCompaction($) {
  ck.plan = null
  ck.compacting = true
  $.clock.after(COMPACT_DELAY_MS, () => runCompaction($, 0))
}

async function runCompaction($, attempt, waited = 0) {
  let retry = false
  let args = {}
  // Subagents started since the approval would lose their place in a summary: wait until they are done.
  if ((await runningAgents($)) > 0) {
    if (waited < MAX_AGENT_WAITS) {
      $.clock.after(AGENT_WAIT_MS, () => runCompaction($, attempt, waited + 1))
    } else {
      ck.compacting = false
      await failed($, t(await resolveLang($), 'ck_agents_still'))
    }
    return
  }
  try {
    const before = await transcriptLines($)
    await copyTranscriptIfNeeded($)
    args = (await focusOff($)) ? {} : { instructions: withFocus('', backgroundNote(processHandles())) }
    if (ck.directRefused) {
      await compactViaCommand($, args)
      return
    }
    const tokensBefore = await ctxTokensNow($)
    const result = await $.session.compact(args)
    if (result && result.skip && directCompactRefused(String(result.skip))) {
      ck.directRefused = true
      await compactViaCommand($, args)
    } else if (result && result.skip) {
      await failed($, String(result.skip))
    } else if (result && result.messages) {
      ctxStale = tokensBefore
      cycleDone()
      await afterCompaction($, result, before)
    }
  } catch (err) {
    const message = String(err && err.message ? err.message : err)
    // Mostly "a turn is running" (compaction waits for a gap between turns). A headless session (-p, the SDK,
    // the Desktop app) never takes the direct call: there the same compaction runs as the /compact command.
    if (directCompactRefused(message)) {
      ck.directRefused = true
      await compactViaCommand($, args)
    } else if (attempt < MAX_RETRIES) {
      retry = true
      $.clock.after(RETRY_MS, () => runCompaction($, attempt + 1))
    } else {
      await failed($, message)
    }
  } finally {
    if (!retry && !ck.promptPending) ck.compacting = false
  }
}

// The compaction as the /compact command with the same brief as its arguments, as if the person typed it. The
// engine queues it until the session is idle, so it never cuts into a turn. ($.prompt.submit refuses a text that
// starts with "/" and points at $.command.run.) ck.compacting stays set ("already being arranged") until the
// session.compact hook sees the compaction, the command is refused, or PROMPT_WAIT_MS passes.
async function compactViaCommand($, args) {
  const cycle = ck
  ck.compacting = true
  ck.promptPending = true
  let refused
  try {
    await $.command.run({ command: 'compact', args: args.instructions || '' })
  } catch (err) {
    refused = String(err && err.message ? err.message : err) || 'refused'
  }
  const lang = await resolveLang($)
  if (refused !== undefined) {
    if (cycle === ck) {
      ck.promptPending = false
      ck.compacting = false
    }
    $.ui.toast(t(lang, 'toast_compact_prompt_failed', { reason: refused.slice(0, 160) }), { timeoutMs: 12000 })
    return
  }
  // Already cleared when the compaction ran before the submission resolved: its own toast says so.
  if (cycle !== ck || !ck.promptPending) return
  $.ui.toast(t(lang, 'toast_compact_started'), { timeoutMs: 8000 })
  $.clock.after(PROMPT_WAIT_MS, () => {
    if (cycle !== ck || !ck.promptPending) return
    ck.promptPending = false
    ck.compacting = false
  })
}

async function failed($, reason) {
  const lang = await resolveLang($)
  $.ui.toast(t(lang, 'toast_compact_failed', { reason: reason.slice(0, 160) }), { timeoutMs: 12000 })
}

// ---- after a compaction ---------------------------------------------------------------------

async function dataDir($) {
  const fromEnv = await safe(() => $.env.get('CLAUDE_PLUGIN_DATA'), undefined)
  if (fromEnv) return fromEnv
  const home = await safe(() => $.env.get('HOME'), undefined)
  const derived = pluginDataDir($.plugin.root, home)
  if (derived) return derived
  const tmp = (await safe(() => $.env.get('TMPDIR'), undefined)) || '/tmp'
  return `${tmp.replace(/\/+$/, '')}/crew-chief-compact`
}

async function prune($, dir, prefix, keep) {
  const entries = await safe(() => $.fs.list(dir), [])
  for (const name of backupsToPrune(entries.map((e) => e.name), prefix, keep)) {
    await safe(() => $.process.run(['rm', '-f', `${dir}/${name}`]), undefined)
  }
}

async function backupSummary($, summary) {
  const dir = `${await dataDir($)}/compact-summaries`
  const path = `${dir}/${backupName('compact', await $.clock.now())}`
  await $.fs.write(path, summary + '\n')
  await safe(() => $.process.run(['chmod', '600', path]), undefined)
  await prune($, dir, 'compact', SUMMARIES_KEPT)
  return path
}

async function transcriptPath($) {
  const home = await safe(() => $.env.get('HOME'), undefined)
  const cwd = await safe(() => $.session.cwd(), undefined)
  const id = await safe(() => $.session.id(), undefined)
  if (!home || !cwd || !id) return undefined
  const path = `${home}/.claude/projects/${projectDirName(cwd)}/${id}.jsonl`
  return (await safe(() => $.fs.exists(path), false)) ? path : undefined
}

async function transcriptLines($) {
  const path = await transcriptPath($)
  if (!path) return undefined
  const r = await safe(() => $.process.run(['wc', '-l', path]), undefined)
  const n = r && r.exitCode === 0 ? Number(r.stdout.trim().split(/\s+/)[0]) : NaN
  return Number.isFinite(n) ? n : undefined
}

// Claude Code appends to the transcript across a compaction, so the lines from before it stay
// searchable (checked live on 2.1.300). If that ever stops being true the first compaction shows it,
// and every later one copies the file first.
async function copyTranscriptIfNeeded($) {
  const kept = await safe(() => $.store.get('transcript_kept'), undefined)
  if (kept !== 'false') return
  const path = await transcriptPath($)
  if (!path) return
  const dir = `${await dataDir($)}/transcripts`
  const copy = `${dir}/${backupName('session', await $.clock.now(), 'jsonl')}`
  await safe(async () => {
    await $.process.run(['mkdir', '-p', dir])
    await $.process.run(['cp', '-p', path, copy])
    await $.process.run(['chmod', '600', copy])
    await prune($, dir, 'session', TRANSCRIPTS_KEPT)
  }, undefined)
}

async function verifyTranscript($, before) {
  if (before === undefined) return
  const after = await transcriptLines($)
  if (after === undefined) return
  const lost = after < before
  await safe(() => $.store.set('transcript_kept', lost ? 'false' : 'true'), undefined)
  if (lost) {
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'toast_transcript_lost'), { timeoutMs: 12000 })
  }
}

// What the person's files say should survive, checked against the summary Claude Code wrote.
async function pinnedItems($) {
  const h = await findHandoff($)
  if (!h) return { constraints: [], tasks: [] }
  const status = h.status ? await safe(() => $.fs.read(h.status), '') : ''
  const tasks = h.tasks ? await safe(() => $.fs.read(h.tasks), '') : ''
  return { constraints: parseStatus(typeof status === 'string' ? status : '').constraints, tasks: openTasks(typeof tasks === 'string' ? tasks : '') }
}

async function afterCompaction($, result, linesBefore) {
  try {
    const lang = await resolveLang($)
    const summary = result.messages.map((m) => m.text).join('\n')
    const path = await safe(() => backupSummary($, summary), undefined)
    const found = checkSummary(summary, await pinnedItems($))
    const missing = found.missingConstraints.length + found.missingTasks.length
    if (missing > 0) $.ui.toast(t(lang, 'toast_compact_missing', { n: missing }), { timeoutMs: 15000 })
    else $.ui.toast(path ? t(lang, 'toast_compact_done', { path }) : t(lang, 'toast_compact_done_plain'), { timeoutMs: 10000 })
    await verifyTranscript($, linesBefore)
  } catch (err) {
    // The compaction itself succeeded; the extras are best effort.
  }
  await safe(() => nightAfterCompaction($), undefined)
}

// ---- registration ---------------------------------------------------------------------------

// Called from the mod's session.start hook (a module may register each event only once).
async function compactSessionStart($) {
  resetCompact()
  ck.toolReady = false
  ck.directRefused = false
  if (await disabled($)) return
  try {
    await $.tool.register({
      name: TOOL_NAME,
      description: TOOL_DESCRIPTION,
      inputSchema: {
        type: 'object',
        properties: {
          phase: { type: 'string', description: 'One line: the phase that was just finished.' },
          next: { type: 'string', description: 'One line: what comes next.' },
          user_requested: { type: 'boolean', description: 'true only when the user asked for a compaction in this conversation (for example "compact now"); it then works even after an earlier "not now".' },
        },
      },
      isDeferred: false,
    })
    ck.toolReady = true
  } catch (err) {
    // An older Claude Code, or the name is taken: the fallback question still works.
  }
  try {
    await $.command.register({
      name: 'crew-compact',
      description: t(await resolveLang($), 'cmd_compact_description'),
      argumentHint: '[never]',
    })
  } catch (err) {
    // The name is taken: the tool and the fallback question still work.
  }
}

const clip = (s) => (typeof s === 'string' ? s.replace(/\s+/g, ' ').trim().slice(0, 200) : '')

function registerCompact(on) {
  // The Stop event carries the session's background tasks; the processes among them are remembered for the
  // question and for the summarizer. (Settings-hook events do not reach a mod where an organization manages
  // Claude Code; the list then stays empty and only subagents are waited for.)
  on('classic.Stop', async ($, e, next) => {
    const tasks = Array.isArray(e.background_tasks) ? e.background_tasks : []
    ck.bgTasks = tasks.filter((task) => task && typeof task.command === 'string' && task.command !== '' && !task.agent_type)
    return next(e)
  })

  on('tool.call', { tool: TOOL_MATCH }, async ($, e) => {
    if (e.agentId !== undefined) return { deny: 'Only the main conversation can propose a compaction.' }
    // The user asked for it in their own words ("compact now"): that beats an earlier "not now" or "never",
    // the same as the /crew-compact command (which also clears `never`).
    const requested = e.user_requested === true
    if (!requested && (!ck.armed || ck.never)) return { result: RESULTS.notNeeded }
    if (ck.plan || ck.compacting || ck.asking) return { result: RESULTS.busy }
    if (requested) {
      ck.never = false
      ck.armed = true
    }
    // The question waits for the end of this turn (compactTurnComplete): a tool that waited for the
    // person would hold the turn open.
    ck.wantAsk = { phase: clip(e.phase) }
    return { result: RESULTS.noted }
  })

  // Every compaction a person, the engine or another plugin starts passes here. (One this plugin starts
  // does not: the call "runs through every hook but the calling one", so runCompaction passes the brief
  // itself.)
  on('session.compact', async ($, e, next) => {
    // The /compact compactViaCommand ran has arrived: the guard is let go whatever the outcome.
    if (e.agentId === undefined && e.trigger !== 'precompute' && ck.promptPending) {
      ck.promptPending = false
      ck.compacting = false
    }
    const main = e.agentId === undefined && e.trigger !== 'precompute'
    const tokensBefore = main ? await ctxTokensNow($) : undefined
    if (e.agentId !== undefined || (await focusOff($))) {
      const plain = await next(e)
      if (main && plain && plain.messages) ctxStale = tokensBefore
      return plain
    }
    const before = e.trigger === 'precompute' ? undefined : await transcriptLines($)
    if (e.trigger !== 'precompute') await copyTranscriptIfNeeded($)
    // The engine always sends the transcript with the event; a call without it is passed on without one.
    const input = e.messages === undefined ? (({ messages, ...rest }) => rest)(e) : e
    const result = await next({ ...input, instructions: withFocus(e.instructions, backgroundNote(processHandles())) })
    if (e.trigger !== 'precompute' && result && result.messages) {
      ctxStale = tokensBefore
      cycleDone()
      await afterCompaction($, result, before)
    }
    return result
  })

  on('command.run', { command: 'crew-compact' }, async ($, e) => {
    const lang = await resolveLang($)
    if (await disabled($)) return { text: t(lang, 'cmd_compact_off') }
    // `never`: the question's third answer, also where it is a chip with no room for it. An open question is
    // answered with it, so the chip leaves at once.
    if (String(e?.args || '').trim().toLowerCase() === 'never') {
      ck.never = true
      cancelAskTimer()
      ck.wantAsk = null
      uiAnswerOpen($, t(lang, 'ck_never'))
      return { text: t(lang, 'cmd_compact_never') }
    }
    // A yes is waiting on the update turn and no turn has started since it was asked for: the person asking
    // again means now.
    if (ck.plan && !ck.compacting && !ck.asking && ck.plan.requestedSteps !== undefined && ck.steps === ck.plan.requestedSteps) {
      scheduleCompaction($)
      return { text: t(lang, 'cmd_compact_now') }
    }
    if (ck.plan || ck.compacting || ck.asking) return { text: t(lang, 'cmd_compact_busy') }
    compactAskLater($)
    return { text: t(lang, 'cmd_compact_ok') }
  })
}

// ===== night =================================================================
// Night mode, the mod's side. Part of the mod in hooks/register.js (rules in hooks/night-logic.mjs).
//
// A night is opened by the crew-night skill and run by the shell: scripts/night-state.sh alone writes
// <git root>/night/<sid8>/state.json, and the pointer ${CLAUDE_PLUGIN_DATA}/night/<session id> names that folder.
// No pointer: no night, and this file does nothing beyond one fs.exists. With a night open (status opening, armed
// or wrapup) the mod:
//   - answers crew-chief's own questions by itself (askWithDeadline -> nightQuietAnswer): compaction yes, plain
//     saver (never ultra), everything else its safe "no"; the advisor and handoff offers are not made at all;
//   - in the opening phase only, closes Claude's own AskUserQuestion after night.ask minutes (default 20) with a
//     NO_ANSWER label (nightOpeningDeadline, used by hooks/src/ask.js);
//   - keeps night/<sid8>/hold fresh while a compaction is under way, so the Stop hook lets that turn end;
//   - wakes the session once it sits idle (and after a compaction) with one resume prompt, at most 6 an hour;
//   - starts the wrap-up when the 5-hour or the weekly limit reaches limitPct (95) percent;
//   - runs report-fallback once when the deadline is 2 minutes past and no report came;
//   - /night status|off.
// Every decision it takes by itself is one line in night/<sid8>/events.log ("<ISO time> mod <text>").
const NIGHT_TICK_MS = 60_000
const NIGHT_WAKE_DELAY_MS = 5_000

let nightGen = 0
let nightTimer = null
let nightDataDir // resolved once per module life
let nightCache = null // { dir, mtime, state }
let nightDefaultsCache = null
let nightInFlight = false
let nightLastActivity = 0
let nightNudges = []
let nightCapLogged = false
let nightHoldOn = false
let nightLimitFired = new Set() // night folders whose limit wrap-up the mod already started
let nightFallbackFired = new Set()
let nightOverToasted = new Set()
let nightSeenActive = new Set()
let nightCmdRegistered = false

async function nightTry(fn, fallback) {
  try {
    return await fn()
  } catch (err) {
    return fallback
  }
}

// session.start, session.end, /clear, /resume: timers of the old session stop, the memory goes.
function nightReset() {
  nightGen += 1
  const timer = nightTimer
  nightTimer = null
  try {
    if (timer) timer.cancel()
  } catch (err) {
    // Already fired.
  }
  nightDataDir = undefined
  nightCache = null
  nightInFlight = false
  nightLastActivity = 0
  nightNudges = []
  nightCapLogged = false
  nightHoldOn = false
  nightLimitFired = new Set()
  nightFallbackFired = new Set()
  nightOverToasted = new Set()
  nightSeenActive = new Set()
}

async function nightDataDirOf($) {
  if (nightDataDir !== undefined) return nightDataDir
  const env = await nightTry(() => $.env.get('CLAUDE_PLUGIN_DATA'), undefined)
  const home = await nightTry(() => $.env.get('HOME'), undefined)
  const configDir = await nightTry(() => $.env.get('CLAUDE_CONFIG_DIR'), undefined)
  const found = resolveDataDir({ env, pluginRoot: $.plugin.root, pluginName: $.plugin.name, home, configDir })
  nightDataDir = found === undefined ? '' : found.dir
  return nightDataDir
}

// This session's night: { sid, dir, state } or undefined. One fs.exists when there is none. state.json is read
// again only when its mtime moved.
async function nightRead($) {
  try {
    const sid = await $.session.id()
    if (typeof sid !== 'string' || sid === '') return undefined
    const data = await nightDataDirOf($)
    if (data === '') return undefined
    const pointer = `${data}/night/${sid}`
    if (!(await $.fs.exists(pointer))) return undefined
    const dir = String(await $.fs.read(pointer))
      .trim()
      .replace(/\/+$/, '')
    if (dir === '') return undefined
    const file = `${dir}/state.json`
    const stat = await nightTry(() => $.fs.stat(file), undefined)
    if (!stat) return undefined
    if (nightCache && nightCache.dir === dir && nightCache.mtime === stat.mtimeMs) return { sid, dir, data, state: nightCache.state }
    const state = parseNightState(await $.fs.read(file))
    if (state === undefined) return undefined
    nightCache = { dir, mtime: stat.mtimeMs, state }
    return { sid, dir, data, state }
  } catch (err) {
    return undefined
  }
}

async function nightDefaultsOf($) {
  if (nightDefaultsCache) return nightDefaultsCache
  const text = await nightTry(() => $.fs.read(`${$.plugin.root}/data/night-defaults.json`), undefined)
  nightDefaultsCache = text === undefined ? { ...NIGHT_DEFAULTS } : nightDefaults(text)
  return nightDefaultsCache
}

// One line into events.log. An append through the shell: the hooks append to the same file at the same time.
async function nightEvent($, night, text) {
  try {
    const line = nightEventLine(await $.clock.now(), text)
    await $.process.run(['sh', '-c', 'printf "%s\\n" "$1" >> "$2"', 'sh', line, `${night.dir}/events.log`], { timeoutMs: 5000 })
  } catch (err) {
    // The log is for the report; the night goes on without the line.
  }
}

// scripts/night-state.sh <args>. The night is named three ways so the script can pick it up however it looks:
// cwd = the night's git root, CREW_CHIEF_NIGHT_DIR = the night folder, the session id and the plugin data folder.
async function nightScript($, night, args) {
  const env = { CREW_CHIEF_NIGHT_DIR: night.dir, CREW_CHIEF_SESSION_ID: night.sid, CLAUDE_SESSION_ID: night.sid }
  if (night.data) env.CLAUDE_PLUGIN_DATA = night.data
  const init = { env, timeoutMs: 20_000 }
  if (typeof night.state.root === 'string' && night.state.root !== '') init.cwd = night.state.root
  try {
    return await $.process.run(['sh', `${$.plugin.root}/scripts/night-state.sh`, ...args], init)
  } catch (err) {
    return { exitCode: 1, stdout: '', stderr: String(err && err.message ? err.message : err) }
  }
}

// The open night (opening|armed|wrapup), or undefined. For the offers that are not made at night.
async function nightQuietNow($) {
  const night = await nightRead($)
  return night && nightQuietState(night.state, await $.clock.now()) ? night : undefined
}

// Called first by askWithDeadline. While a night is open the question is never shown: returns the caller's night
// answer (`night.answer`), or its safe fallback, and logs it. undefined: no night, ask as usual.
// `night.hold`: the answer starts a compaction; the hold file goes up before the yes returns.
async function nightQuietAnswer($, question, answers, fallback, night) {
  const open = await nightQuietNow($)
  if (!open) return undefined
  const label = night && typeof night.answer === 'string' ? night.answer : fallback
  if (night && night.hold) await nightHoldWrite($, open)
  await nightEvent($, open, `auto-answered a crew-chief question (nobody asked at night): "${String(question).slice(0, 120)}" -> ${String(label)}`)
  return label
}

// Logs an offer that is not made because the night is open.
async function nightSkipped($, night, what) {
  await nightEvent($, night, `skipped ${what} (night)`)
}

async function nightHoldWrite($, night) {
  try {
    await $.fs.write(`${night.dir}/hold`, nightHoldText(await $.clock.now()))
    nightHoldOn = true
  } catch (err) {
    // Without the hold the Stop hook may block the update turn; the compaction then retries.
  }
}

async function nightHoldClear($, night) {
  nightHoldOn = false
  await nightTry(() => $.process.run(['rm', '-f', `${night.dir}/hold`]), undefined)
}

// While a compaction is under way or due (compactWanted: the turn must be allowed to end first): the hold stays
// fresh. Otherwise: removed.
async function nightHoldRefresh($, night) {
  if (compactBusy() || compactWanted()) await nightHoldWrite($, night)
  else if (nightHoldOn) await nightHoldClear($, night)
}

// ---- the opening interview's deadline (hooks/src/ask.js) --------------------------------------------------------

// night.ask: a value the person set (/crew-config or CREW_CHIEF_NIGHT_ASK_MIN) wins; otherwise askMin from the
// defaults file (20).
async function nightAskMinutes($) {
  const st = await nightTry(() => cfgState($, 'night.ask'), undefined)
  if (st && st.source !== 'default' && typeof st.value === 'number' && st.value > 0) return st.value
  return (await nightDefaultsOf($)).askMin
}

// For Claude's own AskUserQuestion: a deadline entry while this session's night is in its opening phase, else
// undefined (outside a night and after arming, Claude's questions get no deadline from the mod).
async function nightOpeningDeadline($) {
  const night = await nightRead($)
  if (!night || night.state.status !== 'opening') return undefined
  const min = await nightAskMinutes($)
  return { night, min, ms: min * 60_000, fallback: nightNoAnswerLabel(min), lang: await nightTry(() => resolveLang($), 'en'), announced: false }
}

async function nightAnnounceExpiry($, d, count) {
  await nightEvent($, d.night, `opening question${count === 1 ? '' : 's'} unanswered for ${d.min} min (${count}): answered NO_ANSWER, to be parked in QUESTIONS.md`)
  await nightTry(() => $.ui.toast(nightText(d.lang, 'ask_expired', { min: d.min }), { timeoutMs: 15000 }), undefined)
}

// ---- activity, the watchdog, the limit stop -----------------------------------------------------------------------

// From the main loop: a prompt or a model request (inFlight), or a finished turn.
function nightNoteActivity(nowMs, inFlight) {
  nightLastActivity = nowMs
  nightInFlight = inFlight
}

function nightArm($) {
  if (nightTimer) return
  const gen = nightGen
  nightTimer = $.clock.after(NIGHT_TICK_MS, () => nightTick($, gen))
}

async function nightTick($, gen) {
  if (gen !== nightGen) return
  nightTimer = null
  const night = await nightRead($)
  const keep = night ? await nightCheck($, night, undefined, true) : false
  if (keep && gen === nightGen) nightArm($)
}

// One look at the night: hold, end notice, limit, and (`watch`, from the timer) the watchdog; a turn that just ended
// is not idle. Returns whether the watchdog should keep ticking.
async function nightCheck($, night, rateLimits, watch) {
  const st = night.state
  await nightHoldRefresh($, night)
  if (nightOverStatus(st.status)) {
    if (nightSeenActive.has(night.dir)) await nightOver($, night)
    return false
  }
  if (!nightQuietStatus(st.status)) return false
  nightSeenActive.add(night.dir)
  if (!nightArmedStatus(st.status)) return true // opening: keep watching for the arming
  const usage = rateLimits === undefined ? await nightTry(() => $.session.usage(), undefined) : { rateLimits }
  await nightLimit($, night, usage ? usage.rateLimits : undefined)
  if (watch) await nightWatchdog($, night)
  return true
}

async function nightOver($, night) {
  if (nightOverToasted.has(night.dir)) return
  nightOverToasted.add(night.dir)
  const lang = await nightTry(() => resolveLang($), 'en')
  await nightTry(() => $.ui.toast(nightText(lang, 'over', { path: `${night.dir}/REPORT.md` }), { timeoutMs: 20000 }), undefined)
}

// The 5-hour window or the weekly limit at limitPct: the wrap-up starts, once per night.
async function nightLimit($, night, rateLimits) {
  if (night.state.status !== 'armed' || nightLimitFired.has(night.dir)) return
  const d = await nightDefaultsOf($)
  const hit = nightLimitHit(rateLimits, d.limitPct)
  if (!hit) return
  nightLimitFired.add(night.dir)
  const r = await nightScript($, night, ['phase', 'wrapup', '--reason', 'limit'])
  await nightEvent($, night, `limit: ${hit.kind} at ${hit.percent}% (stop at ${d.limitPct}%): wrap-up started` + (r.exitCode === 0 ? '' : ` (night-state.sh failed: ${String(r.stderr || '').trim().slice(0, 120)})`))
  const lang = await nightTry(() => resolveLang($), 'en')
  await nightTry(() => $.ui.toast(nightText(lang, 'limit', { window: hit.kind, percent: hit.percent }), { timeoutMs: 12000 }), undefined)
}

async function nightNudge($, night, reason) {
  const now = await $.clock.now()
  nightNudges = nightRecentNudges(nightNudges, now)
  if (!nightNudgeAllowed(nightNudges, now)) {
    if (!nightCapLogged) {
      nightCapLogged = true
      await nightEvent($, night, `watchdog: ${nightNudges.length} resume prompts in the last hour, no more until the hour has passed`)
    }
    return
  }
  nightCapLogged = false
  nightNudges.push(now)
  nightLastActivity = now // the next nudge waits a full idle period, whether this one started a turn or not
  const idleMin = Math.round(NIGHT_IDLE_MS / 60_000)
  await nightEvent($, night, reason === 'compaction' ? 'compaction finished: resume prompt sent' : `watchdog: idle ${idleMin}+ min, resume prompt sent`)
  try {
    $.prompt.submit({ text: nightNudgeText(night.state, now, reason, night.dir) }).catch(() => {})
  } catch (err) {
    // A session that cannot take a prompt now: the next tick tries again.
  }
}

async function nightWatchdog($, night) {
  const st = night.state
  const action = nightWatchdogAction({
    status: st.status,
    deadline: st.deadline,
    reportDone: Boolean(st.reportDone),
    fallbackDone: nightFallbackFired.has(night.dir),
    nowMs: await $.clock.now(),
    lastActivityMs: nightLastActivity,
    inFlight: nightInFlight,
    compactBusy: compactBusy(),
    agentsRunning: await nightTry(() => runningAgents($), 0),
  })
  if (action === 'nudge') return nightNudge($, night, 'idle')
  if (action !== 'fallback') return
  nightFallbackFired.add(night.dir)
  // `done` past the deadline: status done (reason deadline), the fallback report if Claude wrote none, caffeinate off.
  const r = await nightScript($, night, ['done'])
  await nightEvent($, night, 'deadline + 2 min and the night still open: closed it (done)' + (r.exitCode === 0 ? '' : ` (failed: ${String(r.stderr || '').trim().slice(0, 120)})`))
  await nightOver($, night)
}

// ---- hooks the entry (hooks/src/register.js) calls ----------------------------------------------------------------

async function nightSessionStart($) {
  nightReset()
  try {
    await $.command.register({ name: 'night', description: 'crew-chief night mode: status, or off (start one with /crew-chief:crew-night)', immediate: true, argumentHint: '[status|off]' })
    nightCmdRegistered = true
  } catch (err) {
    nightCmdRegistered = await nightOwnsCommand($)
  }
  const night = await nightRead($)
  if (night && nightQuietStatus(night.state.status)) {
    nightSeenActive.add(night.dir)
    nightLastActivity = await $.clock.now()
    nightArm($)
  }
}

// A finished main turn and a measurement: the hold, the limit, and the watchdog's timer when a night just armed.
async function nightTurnComplete($, usage) {
  const night = await nightRead($)
  if (!night) return
  const keep = await nightCheck($, night, usage && Array.isArray(usage.rateLimits) ? usage.rateLimits : [], false)
  if (keep) nightArm($)
}

async function nightMeasure($, e) {
  const night = await nightRead($)
  if (!night || night.state.status !== 'armed') return
  await nightLimit($, night, e && Array.isArray(e.rateLimits) ? e.rateLimits : undefined)
}

// From compact-flow's afterCompaction (both the direct and the /compact path): the hold comes down and, a few
// seconds later, the session that now sits idle is told to go on.
async function nightAfterCompaction($) {
  const night = await nightRead($)
  if (!night || !nightArmedStatus(night.state.status)) return
  await nightHoldClear($, night)
  const gen = nightGen
  const at = await $.clock.now()
  $.clock.after(NIGHT_WAKE_DELAY_MS, async () => {
    if (gen !== nightGen) return
    if (nightInFlight && nightLastActivity > at) return // a turn already started
    const now = await nightRead($)
    if (!now || !nightArmedStatus(now.state.status)) return
    await nightNudge($, now, 'compaction')
  })
}

async function nightOwnsCommand($) {
  try {
    const commands = await $.command.list()
    return commands.some((c) => c.name === 'night' && c.source === 'plugin' && /^crew-chief(@|$)/.test(String(c.plugin ?? '')))
  } catch (err) {
    return false
  }
}

function registerNight(on) {
  on('command.run', { command: 'night' }, async ($, e, next) => {
    if (!nightCmdRegistered) nightCmdRegistered = await nightOwnsCommand($)
    if (!nightCmdRegistered) return next(e)
    const word = String(e.args || '').trim().toLowerCase()
    const night = await nightRead($)
    if (!night) return { text: 'crew-chief night: no night in this session. Start one with /crew-chief:crew-night.' }
    if (word === '' || word === 'status') return { text: nightStatusText(night.state, await $.clock.now(), await nightDefaultsOf($), night.dir) }
    if (word === 'off') {
      if (!nightQuietStatus(night.state.status)) return { text: `crew-chief night: the night is already ${night.state.status}; nothing to turn off.` }
      const r = await nightScript($, night, ['stop', '--reason', 'off'])
      if (r.exitCode !== 0) return { text: `crew-chief night: could not turn it off (night-state.sh exit ${r.exitCode}): ${String(r.stderr || r.stdout || '').trim().slice(0, 200)}` }
      nightCache = null
      if (nightHoldOn) await nightHoldClear($, night)
      const lang = await nightTry(() => resolveLang($), 'en')
      nightOverToasted.add(night.dir) // the toast below says it; no "night over" toast after it
      await nightTry(() => $.ui.toast(nightText(lang, 'off'), { timeoutMs: 8000 }), undefined)
      return { text: `crew-chief night: off. Claude Code is back to normal; the night's files stay in ${night.dir}.` }
    }
    return { text: 'crew-chief night: /night status or /night off. Start a night with /crew-chief:crew-night.' }
  })
}

// ===== handoff-nudge =========================================================
// Keeps the handoff files (STATUS.md, tasks.json, PROGRESS.md) from going stale. Part of the mod in hooks/register.js.
// The rules are in hooks/handoff-nudge-logic.mjs. This part watches the session:
//   - every Edit/Write call counts the project file it touched (main session and subagents);
//   - a reminder rides with the result of a main-session Edit/Write call once enough has piled up, so a long
//     unattended run is reached too; the next prompt carries one as well when the pile is big but no call did;
//   - a prompt that may state a rule, a question the person answered, a commit and a nearly used limit each get
//     a one-time reminder;
//   - mode `turn`: after unanswered reminders, one extra turn at the end of an answer asks for the update.
// It never writes the files, never asks a question and never stops a call. Any failure says nothing.
let hs = newState()
let known // { at, paths: string[] } or { at, paths: [] } when the project has no handoff files

function handoffReset() {
  hs = newState()
  known = undefined
}

async function config($) {
  return {
    mode: await cfgGet($, 'handoff.mode'),
    files: await cfgGet($, 'handoff.files'),
    minutes: await cfgGet($, 'handoff.minutes'),
    max: await cfgGet($, 'handoff.max'),
  }
}

// The handoff files this project has, looked up at most every two minutes (crew-handoff may create them mid-session).
async function handoffPaths($) {
  const now = await $.clock.now()
  if (known !== undefined && now - known.at < 120_000) return known.paths
  const h = await findHandoff($)
  known = { at: now, paths: h ? [h.status, h.tasks, h.progress].filter(Boolean) : [] }
  return known.paths
}

async function newestMtime($, paths) {
  let best
  for (const p of paths) {
    try {
      const st = await $.fs.stat(p)
      if (st && typeof st.mtimeMs === 'number' && (best === undefined || st.mtimeMs > best)) best = st.mtimeMs
    } catch (err) {
      // A file that cannot be read has no time.
    }
  }
  return best
}

// Whether the files were written since counting began (a Bash edit, another tool, the person): then the stretch restarts.
async function writtenMeanwhile($, paths) {
  const mt = await newestMtime($, paths)
  if (mt === undefined) return false
  if (hs.baseline === undefined) {
    hs.baseline = mt
    return false
  }
  if (mt > hs.baseline) {
    wrote(hs, mt)
    return true
  }
  return false
}

async function root($) {
  try {
    return (await $.session.root()) || (await $.session.cwd())
  } catch (err) {
    return undefined
  }
}

// Called from the mod's tool.call hook after the call ran. `result` is what the call returned. Returns the note to
// add to that result, or undefined.
async function handoffAfter($, e, result) {
  try {
    if (result && result.deny !== undefined) return undefined
    const watched = WRITE_TOOLS.has(e.tool) || e.tool === 'AskUserQuestion' || (e.tool === 'Bash' && isCommit(e.command))
    if (!watched) return undefined
    const cfg = await config($)
    if (cfg.mode === 'off') return undefined
    const paths = await handoffPaths($)
    if (paths.length === 0) return undefined
    const main = typeof e.agentId !== 'string' || e.agentId === ''
    const now = await $.clock.now()
    if (WRITE_TOOLS.has(e.tool)) {
      const kind = noteCall(hs, e, await root($), now)
      if (kind === 'wrote') {
        hs.baseline = await newestMtime($, paths)
        return undefined
      }
      if (kind === 'counted' && hs.baseline === undefined) hs.baseline = await newestMtime($, paths) // counting begins: remember how the files stand
      if (kind !== 'counted' || !main || compactBusy() || !ordinaryDue(hs, cfg, now)) return undefined
      if (await writtenMeanwhile($, paths)) return undefined
      if (!ordinaryDue(hs, cfg, now)) return undefined
      const text = ordinaryText(hs, now)
      sentOrdinary(hs, now)
      return text
    }
    if (!main || hs.events >= EVENT_CAP || compactBusy()) return undefined
    if (e.tool === 'Bash') {
      hs.events += 1
      return eventText('commit')
    }
    // AskUserQuestion: Claude asked, the person answered.
    if (result && result.result !== undefined) {
      hs.events += 1
      return eventText('decision')
    }
    return undefined
  } catch (err) {
    return undefined
  }
}

// Called from the prompt.submit hook with what the person typed. Returns notes to add to the prompt's context.
async function handoffOnPrompt($, e) {
  const notes = []
  try {
    const kind = e.origin ? e.origin.kind : undefined
    const typed = kind === undefined || kind === 'composer' || kind === 'bridge'
    const cfg = await config($)
    if (cfg.mode === 'off') return notes
    const paths = await handoffPaths($)
    if (paths.length === 0) return notes
    const now = await $.clock.now()
    if (!compactBusy()) {
      if (typed && hs.events < EVENT_CAP && looksLikeRule(e.text)) {
        hs.events += 1
        notes.push(eventText('rule'))
      }
      if (!hs.limitDone) {
        const usage = await $.session.usage().catch(() => undefined)
        if (limitNear(usage?.rateLimits)) {
          hs.limitDone = true
          if (hs.events < EVENT_CAP) {
            hs.events += 1
            notes.push(eventText('limit'))
          }
        }
      }
      if (typed && ordinaryDue(hs, cfg, now) && !(await writtenMeanwhile($, paths)) && ordinaryDue(hs, cfg, now)) {
        notes.push(ordinaryText(hs, now))
        sentOrdinary(hs, now)
      }
    }
  } catch (err) {
    // A missing reminder is better than a broken prompt.
  }
  return notes
}

// Called after each finished main turn. Mode `turn`: if reminders went unanswered and the pile is large, ask for the
// update in a turn of its own, once per stretch, after the session has stayed quiet for a few seconds.
async function handoffTurnComplete($, e) {
  try {
    if (e.agentId !== undefined || (e.reason !== undefined && e.reason !== 'answer')) return
    const cfg = await config($)
    if (cfg.mode !== 'turn' || compactBusy()) return
    const paths = await handoffPaths($)
    if (paths.length === 0) return
    const now = await $.clock.now()
    if (!enforceDue(hs, cfg, now)) return
    const seen = compactActivity()
    $.clock.after(8000, async () => {
      try {
        if (compactActivity() !== seen || compactBusy()) return // a new turn started, or a compaction did
        const agents = await $.agent.list().catch(() => [])
        if (Array.isArray(agents) && agents.some((a) => a.status === 'pending' || a.status === 'running')) return
        if (await writtenMeanwhile($, paths)) return
        const at = await $.clock.now()
        if (!enforceDue(hs, cfg, at)) return
        hs.enforced = true
        $.ui.log('handoff: asking for an update after unanswered reminders', { to: 'debug' })
        await $.prompt.submit({ text: enforceText(hs, at) })
      } catch (err) {
        // Nothing is lost: the reminders and the compact flow still exist.
      }
    })
  } catch (err) {
    // Silent.
  }
}

// ===== tidy-flow =============================================================
// /crew-tidy: what in your context is oversized, repeated, or points at something that is gone.
// Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
//   /crew-tidy            a report (nothing is changed): the instruction and memory files Claude Code
//                         actually loaded (read from /context), measured against Anthropic's own limits;
//                         paths they mention that no longer exist; lines repeated across files; the
//                         handoff files' size and age; MCP servers and skills by token cost.
//   /crew-tidy archive    moves PROGRESS.md entries older than 60 days to PROGRESS-archive.md. It shows
//                         the count and asks first; the archive is written and read back before the
//                         source is rewritten; nothing is deleted; an entry whose date is unclear stays.
// Files under ~/.claude (your global ones) are only ever reported. Memory files are never rewritten.
const NAMES_SHOWN = 5

function dirOf(path) {
  const at = path.lastIndexOf('/')
  return at > 0 ? path.slice(0, at) : '/'
}

function baseOf(path) {
  return path.slice(path.lastIndexOf('/') + 1)
}

function shown(list) {
  return list.slice(0, NAMES_SHOWN).join(', ') + (list.length > NAMES_SHOWN ? ', …' : '')
}

// The instruction and memory files this session loaded, with their text. The context breakdown names
// exactly those; without it (an older build) the usual project files are looked at instead.
async function loadedFiles($, breakdown, root, cwd) {
  let paths = (breakdown?.memoryFiles ?? []).map((f) => f.path)
  if (paths.length === 0) {
    paths = [`${root}/CLAUDE.md`, `${root}/CLAUDE.local.md`, `${cwd}/CLAUDE.md`]
    const rules = await safe(() => $.fs.list(`${root}/.claude/rules`), [])
    for (const r of rules) if (r.kind === 'file' && r.name.endsWith('.md')) paths.push(`${root}/.claude/rules/${r.name}`)
  }
  const files = []
  for (const path of [...new Set(paths)]) {
    if (!(await safe(() => $.fs.exists(path), false))) continue
    const text = await safe(() => $.fs.read(path), undefined)
    if (typeof text === 'string') files.push({ path, text })
  }
  return files
}

async function pathExists($, ref, root, cwd) {
  const candidates = ref.startsWith('/') ? [ref] : [`${root}/${ref}`, `${cwd}/${ref}`]
  for (const c of candidates) {
    if (await safe(() => $.fs.exists(c.replace(/\/+$/, '')), false)) return true
  }
  return false
}

async function buildTidyReport($) {
  const lang = await resolveLang($)
  const home = await safe(() => $.env.get('HOME'), '')
  const cwd = (await safe(() => $.session.cwd(), '')) || ''
  const root = (await safe(() => $.session.root(), cwd)) || cwd
  const now = await $.clock.now()
  const usage = await safe(() => $.session.usage({ breakdown: 'summary' }), undefined)
  const breakdown = usage?.context?.breakdown
  const findings = []
  const globals = []

  const files = await loadedFiles($, breakdown, root, cwd)
  for (const file of files) {
    const global = isGlobalPath(file.path, home)
    if (global) globals.push(file.path)
    const size = measure(file.text)
    const memoryIndex = baseOf(file.path) === 'MEMORY.md'
    if (memoryIndex) {
      if (size.lines > MEMORY_LINES || size.bytes > MEMORY_BYTES) {
        findings.push(t(lang, 'tidy_memory_long', { path: file.path, lines: size.lines, kb: kb(size.bytes) }))
      }
      const gone = []
      for (const link of memoryIndexLinks(file.text)) {
        if (!(await safe(() => $.fs.exists(`${dirOf(file.path)}/${link}`), false))) gone.push(link)
      }
      if (gone.length > 0) findings.push(t(lang, 'tidy_memory_missing', { path: file.path, n: gone.length, list: shown(gone) }))
      continue
    }
    if (size.lines > INSTRUCTION_LINES) {
      findings.push(t(lang, 'tidy_file_long', { path: file.path, lines: size.lines }))
    }
    const shouting = findShoutingLines(file.text)
    if (shouting.length > 0) findings.push(t(lang, 'tidy_shouting', { path: file.path, n: shouting.length, sample: shouting[0].slice(0, 70) }))
    const temporary = findTemporaryLines(file.text)
    if (temporary.length > 0) findings.push(t(lang, 'tidy_temporary', { path: file.path, n: temporary.length, sample: temporary[0].slice(0, 70) }))
    const imports = countImports(file.text)
    if (imports > 0) findings.push(t(lang, 'tidy_imports', { path: file.path, n: imports }))
    const missing = []
    for (const ref of extractPathRefs(file.text)) {
      if (!(await pathExists($, ref, root, cwd))) missing.push(ref)
    }
    if (missing.length > 0) findings.push(t(lang, 'tidy_paths_missing', { path: file.path, n: missing.length, list: shown(missing) }))
  }

  const dupes = findDuplicateLines(files.filter((f) => baseOf(f.path) !== 'MEMORY.md'))
  if (dupes.length > 0) findings.push(t(lang, 'tidy_dupes', { n: dupes.length, sample: dupes[0].line.slice(0, 80) }))

  const handoff = await findHandoff($)
  if (handoff?.status) {
    const text = await safe(() => $.fs.read(handoff.status), '')
    const size = measure(text)
    if (size.bytes > STATUS_BYTES) findings.push(t(lang, 'tidy_status_big', { path: handoff.status, kb: kb(size.bytes) }))
  }
  if (handoff?.progress) {
    const text = await safe(() => $.fs.read(handoff.progress), '')
    const old = splitProgress(text, now, PROGRESS_ARCHIVE_DAYS).count
    if (old > 0) findings.push(t(lang, 'tidy_progress_old', { path: handoff.progress, n: old, days: PROGRESS_ARCHIVE_DAYS }))
  }

  const mcp = summarizeMcp(breakdown?.mcpTools).filter((r) => r.tokens >= MCP_NOTABLE_TOKENS)
  for (const row of mcp) findings.push(t(lang, 'tidy_mcp', { server: row.server, count: row.count, tokens: row.tokens, loaded: row.loaded }))

  const out = [t(lang, 'tidy_head')]
  out.push(...(findings.length > 0 ? findings.map((f) => '- ' + f) : [t(lang, 'tidy_none')]))
  if (breakdown) {
    const top = (breakdown.categories ?? [])
      .filter((c) => c.tokens > 0 && !/free|buffer/i.test(c.name))
      .sort((a, b) => b.tokens - a.tokens)
      .slice(0, NAMES_SHOWN)
      .map((c) => `${c.name} ${c.tokens}`)
    if (top.length > 0) out.push(t(lang, 'tidy_categories', { list: top.join(' · ') }))
    if (breakdown.skills) out.push(t(lang, 'tidy_skills', { n: breakdown.skills.totalSkills, tokens: breakdown.skills.tokens }))
  }
  if (globals.length > 0) out.push(t(lang, 'tidy_global', { list: shown(globals) }))
  return out.join('\n')
}

async function archiveProgress($) {
  const lang = await resolveLang($)
  const handoff = await findHandoff($)
  if (!handoff?.progress) return t(lang, 'tidy_archive_nofile')
  const source = handoff.progress
  const original = await safe(() => $.fs.read(source), undefined)
  if (typeof original !== 'string') return t(lang, 'tidy_archive_failed', { reason: source })
  const now = await $.clock.now()
  const split = splitProgress(original, now, PROGRESS_ARCHIVE_DAYS)
  if (split.count === 0) return t(lang, 'tidy_archive_none', { days: PROGRESS_ARCHIVE_DAYS })
  const archive = source.replace(/\.md$/i, '') + '-archive.md'
  const yes = t(lang, 'tidy_archive_yes')
  const answers = [yes, t(lang, 'tidy_archive_no')]
  let answer
  try {
    answer = await askWithDeadline($, t(lang, 'tidy_archive_ask', { n: split.count, days: PROGRESS_ARCHIVE_DAYS, path: baseOf(source), archive: baseOf(archive) }), answers, answers[1])
  } catch (err) {
    return t(lang, 'tidy_archive_cancelled')
  }
  if (answer !== yes) return t(lang, 'tidy_archive_cancelled')

  try {
    // The file may have changed while the question was open (another session, an editor): look again.
    const current = await $.fs.read(source)
    if (current !== original) return t(lang, 'tidy_archive_changed')
    const existing = (await $.fs.exists(archive)) ? await $.fs.read(archive) : ''
    const header = `# Archived from ${baseOf(source)}\n\nMoved by crew-chief when older than ${PROGRESS_ARCHIVE_DAYS} days. Nothing was deleted.\n\n`
    const next = (existing === '' ? header : existing.replace(/\n*$/, '\n\n')) + split.archived
    await $.fs.write(archive, next)
    const back = await $.fs.read(archive)
    if (!back.includes(split.archived.trim())) throw new Error('the archive did not read back as written')
    // Only now is the source rewritten. If that fails the entries are in both files: nothing is lost.
    await $.fs.write(source, split.keep)
    const kept = await $.fs.read(source)
    if (kept.trim() !== split.keep.trim()) {
      await $.fs.write(source, original)
      throw new Error('the source did not read back as written; it was restored')
    }
  } catch (err) {
    return t(lang, 'tidy_archive_failed', { reason: String(err && err.message ? err.message : err).slice(0, 160) })
  }
  return t(lang, 'tidy_archive_done', { n: split.count, archive })
}

async function tidySessionStart($) {
  try {
    await $.command.register({
      name: 'crew-tidy',
      description: t(await resolveLang($), 'tidy_description'),
      argumentHint: '[archive]',
    })
  } catch (err) {
    // The name is taken: everything else still works.
  }
}

function registerTidy(on) {
  on('command.run', { command: 'crew-tidy' }, async ($, e) => {
    const word = String(e.args || '').trim().toLowerCase()
    if (word === 'archive' || word === 'arşiv' || word === 'arsiv') return { text: await archiveProgress($) }
    return { text: await buildTidyReport($) }
  })
}

// ===== progress ==============================================================
// crew-chief subagent progress, kept by the mod (Claude Code 2.1.287+). Part of the mod in hooks/register.js.
//
// The shell hook (scripts/progress-hook.sh) needs jq and writes the files the shell panel row reads. Where it
// cannot run (Windows, no jq) nothing would count the subagent's calls, so the mod does it in memory:
//   - every subagent tool.call is counted; a `: 'crew-progress NN | step | delay'` Bash call is a report;
//   - the percentage of a fresh report goes into the status line (hooks/src/agent-row.js);
//   - after 10 calls without a report the call's result carries the same reminder the shell hook would send,
//     but only when jq is missing, so an agent never gets it twice.
// Any failure leaves the call alone.
let progressAgents = new Map()
let progressMissed = new Map() // agentId -> reminders sent since its last report

function progressReset() {
  progressAgents = new Map()
  progressMissed = new Map()
}

// Called from the mod's tool.call hook with the call as it goes out. Returns the note to add to the call's result,
// or undefined: the rule at the agent's second call when it has not reported, then a reminder every 10 calls
// without a report, louder each time one goes unanswered. It never stops a call.
async function progressObserve($, e) {
  try {
    if (typeof e.agentId !== 'string' || e.agentId === '') return undefined
    const now = await $.clock.now()
    const report = e.tool === 'Bash' && parseReport(e.command) !== null
    const due = observe(progressAgents, e.agentId, e.tool, e.command, now)
    if (report) {
      progressMissed.delete(e.agentId)
      return undefined
    }
    const entry = progressAgents.get(e.agentId)
    if (due > 0) {
      const missed = progressMissed.get(e.agentId) ?? 0
      if (missed >= 3) return undefined // Sonnet 5.5 and Haiku 5.5 may read frequent harness text as an injection: stop after three
      progressMissed.set(e.agentId, missed + 1)
      return nudgeText(due, missed)
    }
    if (entry && entry.tools === INTRO_AT_CALL && entry.reported !== true) return introText()
    return undefined
  } catch (err) {
    return undefined
  }
}

// The percentage to show for an agent, or undefined.
async function progressPct($, agentId) {
  try {
    const entry = progressAgents.get(agentId)
    if (!entry) return undefined
    return freshPct(entry, await $.clock.now())
  } catch (err) {
    return undefined
  }
}

// How many tool calls an agent has made (counted by this module), or undefined.
function progressStats(agentId) {
  const entry = progressAgents.get(agentId)
  return entry ? { calls: entry.tools } : undefined
}

// The fresh report of an agent as { pct, step }, or undefined (same freshness as progressPct).
async function progressInfo($, agentId) {
  try {
    const entry = progressAgents.get(agentId)
    if (!entry) return undefined
    const pct = freshPct(entry, await $.clock.now())
    if (pct === undefined) return undefined
    return { pct, step: typeof entry.step === 'string' && entry.step !== '' ? entry.step : undefined }
  } catch (err) {
    return undefined
  }
}

// After the call ran: the reminder rides with the result, next to what the guard may have added.
// The agent's own estimate for the drawings of the band, stale or not: { pct, stale } (stale: more than the
// fresh window of calls or minutes has passed since it was sent), or undefined when it never sent one.
async function progressEstimate($, agentId) {
  try {
    const entry = progressAgents.get(agentId)
    if (!entry || typeof entry.pct !== 'number') return undefined
    return { pct: entry.pct, stale: freshPct(entry, await $.clock.now()) === undefined }
  } catch (err) {
    return undefined
  }
}

function progressAfter(r, text) {
  try {
    if (!r || r.deny !== undefined || text === undefined) return r
    return { ...r, context: [...(r.context ?? []), text] }
  } catch (err) {
    return r
  }
}

// ===== agent-row =============================================================
// crew-chief agent row: one status line with every running subagent's model, effort and tokens. Part of the
// mod in hooks/register.js (Claude Code 2.1.287+).
//
//   scanner haiku-5.5·low 12.4k | implementer opus-5.5·medium 48.1k
//
// The shell panel row (scripts/subagent-row.sh) only reaches a terminal with jq. This line, drawn with
// $.ui.status, also reaches the Desktop app, VS Code and terminals without jq (Windows). The host puts its
// own mark and the plugin's name before it.
//   - model and effort: from each subagent request (turn.step), as the host reported them (not the saver's cap: the host may ignore it);
//   - tokens: the latest request's input + cache + output (its context size), not a running sum;
//   - names and who still runs: $.agent.list() (pending, running, waiting), minus the agents whose turn
//     ended; the line is cleared when none is left.
// CREW_CHIEF_ROW_MOD=auto (default) draws it when a surface is not the terminal, or when the terminal's
// panel row cannot draw (Windows, or no jq: `jq --version` is run once a session to find out);
// `on` always (with a surface), `off` never. Any failure leaves the line alone and the turn untouched.
const ROW_LIVE = ['pending', 'running', 'waiting']
const ROW_RECHECK_MS = 60_000
const ROW_DRAW_DELAY_MS = 50

function freshRow() {
  return {
    agents: new Map(), // agentId -> { model, effort, tokens }
    types: new Set(), // agent types the band has already seen run in this session
    fresh: new Set(), // agents that are the first of their type in this session (the band marks their first run)
    done: new Set(), // agents whose turn ended (the list can still say running for a moment)
    wanted: undefined,
    seen: new Map(), // agentId -> when the band first saw it running (for agents whose first request we missed)
    surfaces: undefined, // as last read, for the band
    checkedAt: undefined,
    hasJq: undefined, // probed once a session (rowJq)
    jqAnswer: undefined, // the promise of that one probe
    shown: false, // this module pinned a line
    lastText: undefined,
    drawPending: false,
  }
}

let rowState = freshRow()

async function rowProbeJq($) {
  try {
    const r = await $.process.run(['jq', '--version'], { timeoutMs: 3000 })
    return r.exitCode === 0
  } catch (err) {
    return false // cannot start: not installed
  }
}

// `jq --version` runs once a session however many places ask (the draw decision, the progress reminder,
// the install hint): they all share this one answer.
function rowJq($) {
  if (!rowState.jqAnswer) {
    rowState.jqAnswer = rowProbeJq($).then((has) => {
      rowState.hasJq = has
      return has
    })
  }
  return rowState.jqAnswer
}

// Without jq the agent panel below the prompt (scripts/subagent-row.sh) stays the host's own: no model, no
// effort. Said once, as a toast, never as a question: the person decides whether they want it.
async function rowJqHint($) {
  try {
    const surfaces = await $.session.surfaces()
    rowState.surfaces = surfaces
    if (!Array.isArray(surfaces) || surfaces.length === 0) return
    if ((await $.env.get('CREW_CHIEF_ROW')) === 'off') return
    if (await $.store.get('jq_hint')) return
    if (await rowJq($)) return
    await $.store.set('jq_hint', 'shown')
    const lang = await resolveLang($)
    const windows = platformFromOs(await $.env.get('OS')) === 'win32'
    const install = windows ? 'winget install jqlang.jq (then open a new terminal)' : 'brew install jq (macOS) or your package manager'
    $.ui.toast(t(lang, 'row_jq_hint', { install }), { timeoutMs: 20000 })
  } catch (err) {
    // A missing hint is no problem.
  }
}

// Decided at session start and again at most every ROW_RECHECK_MS (a Desktop or VS Code client can attach).
async function rowCheckWanted($, force) {
  let now
  try {
    now = await $.clock.now()
  } catch (err) {
    return false
  }
  if (!force && rowState.checkedAt !== undefined && now - rowState.checkedAt < ROW_RECHECK_MS) return rowState.wanted === true
  let wanted = false
  try {
    const mode = await $.env.get('CREW_CHIEF_ROW_MOD')
    const surfaces = await $.session.surfaces()
    // The band's questions read these too; keep them as fresh as the row's own check (a client may connect later).
    if (Array.isArray(surfaces) && surfaces.length > 0) rowState.surfaces = surfaces
    const platform = platformFromOs(await $.env.get('OS'))
    let hasJq = rowState.hasJq
    if (hasJq === undefined && jqMatters({ mode, surfaces, platform })) hasJq = await rowJq($)
    wanted = rowWanted({ mode, surfaces, platform, hasJq })
  } catch (err) {
    wanted = false
  }
  rowState.wanted = wanted
  rowState.checkedAt = now
  return wanted
}

function rowClear($) {
  if (!rowState.shown) return
  rowState.shown = false
  rowState.lastText = undefined
  try {
    $.ui.status(undefined)
  } catch (err) {
    // Nothing to clear then.
  }
}

// An agent whose turn has ended (turn.complete with its agentId) while the list still says `waiting` is waiting
// on background work it owns (a Bash run_in_background, a Monitor, ...): AgentStatus in the host types says
// `waiting` is "on background work it owns", and it resumes under the same id when that work is done. It is not
// finished, so the band keeps its card (calm) and the pane keeps it under running. A turn ended while the list
// says `running` is the list lagging behind the end (hidden as before); `completed`/`failed`/`killed` ended.
// Assumption: in a background subagent `waiting` may also mean an Agent call it waits on; that is work it owns
// too, so it is shown the same way.
function rowBgWaiting(a) {
  return a.status === 'waiting' && rowState.done.has(a.id)
}

function rowAgentName(a) {
  if (typeof a.teammateId === 'string' && a.teammateId !== '') return a.teammateId.replace(/@.*$/, '')
  return a.type || a.description || 'agent'
}

async function rowDraw($) {
  try {
    if (!(await rowCheckWanted($, false))) {
      rowClear($)
      return
    }
    // The band (hooks/src/crew-ui.js) says the same where it is drawn: no second line then.
    if (uiCovers(rowState.surfaces)) {
      rowClear($)
      return
    }
    let list
    try {
      list = await $.agent.list()
    } catch (err) {
      list = []
    }
    const rows = []
    for (const a of Array.isArray(list) ? list : []) {
      if (!a || !ROW_LIVE.includes(a.status) || rowState.done.has(a.id)) continue
      const info = rowState.agents.get(a.id) ?? {}
      rows.push({ name: rowAgentName(a), model: info.model, effort: info.effort, tokens: info.tokens, pct: await progressPct($, a.id) })
    }
    const text = formatRow(rows)
    if (text === undefined) {
      rowClear($)
      return
    }
    if (text === rowState.lastText && rowState.shown) return
    $.ui.status(text)
    rowState.shown = true
    rowState.lastText = text
    $.ui.log('crew-chief: agent row = ' + text, { to: 'debug' })
  } catch (err) {
    // A missing line is better than a broken turn.
  }
}

// The surfaces as last read (for the band's questions).
function rowSurfaces() {
  return rowState.surfaces
}

// Reads the surfaces again when the start-up read gave none (it ran before the host knew them, or failed):
// without it, the band never takes a question and every one opens the old dialog for the whole session.
async function rowRefreshSurfaces($) {
  if (Array.isArray(rowState.surfaces) && rowState.surfaces.length > 0) return
  try {
    const surfaces = await $.session.surfaces()
    if (Array.isArray(surfaces) && surfaces.length > 0) rowState.surfaces = surfaces
  } catch (err) {
    // The dialog is the fallback.
  }
}

// The live subagents for the band: name, model, effort, tokens and the fresh progress report.
async function rowBandRows($) {
  let list
  try {
    list = await $.agent.list()
  } catch (err) {
    list = []
  }
  const rows = []
  const now = await $.clock.now()
  let lang // read once, only when an agent waits on its background work
  for (const a of Array.isArray(list) ? list : []) {
    if (!a || !ROW_LIVE.includes(a.status)) continue
    const bgWait = rowBgWaiting(a)
    if (rowState.done.has(a.id) && !bgWait) continue
    const info = rowState.agents.get(a.id) ?? {}
    const prog = await progressInfo($, a.id)
    if (!rowState.seen.has(a.id)) {
      rowState.seen.set(a.id, now)
      // The first run of a type in this session is a probation run: watch it before trusting it unattended.
      if (typeof a.type === 'string' && a.type !== '' && !rowState.types.has(a.type)) rowState.fresh.add(a.id)
      if (typeof a.type === 'string') rowState.types.add(a.type)
    }
    const since = info.startMs ?? rowState.seen.get(a.id)
    const est = await progressEstimate($, a.id)
    rows.push({
      id: a.id,
      name: rowAgentName(a),
      model: info.model,
      effort: info.effort,
      tokens: info.tokens,
      pct: prog?.pct,
      // The drawings outside the terminal also show a stale estimate, faded and marked old.
      artPct: est?.pct,
      artStale: est?.stale === true,
      step: bgWait ? t(lang ?? (lang = await resolveLang($)), 'row_bg_waiting') : prog?.step,
      bgWait: bgWait || undefined,
      bgTag: bgWait ? t(lang ?? (lang = await resolveLang($)), 'row_bg_tag') : undefined,
      calls: progressStats(a.id)?.calls,
      fresh: rowState.fresh.has(a.id),
      elapsedMs: now - since,
      // No request of this agent ever reached the mod and it has run a while (it started before the mod loaded).
      unknown: info.model === undefined && now - since >= 15_000,
    })
  }
  return rows
}

// Every subagent of this session for the timeline pane: when it started, when it ended, its model, effort and
// tokens, and whether it still runs or waits. Newest last, at most `max`.
async function rowTimeline($, max = 10) {
  let list
  try {
    list = await $.agent.list()
  } catch (err) {
    list = []
  }
  const live = new Map((Array.isArray(list) ? list : []).filter((a) => a && typeof a.id === 'string').map((a) => [a.id, a]))
  const rows = []
  for (const [id, info] of rowState.agents) {
    if (typeof info.startMs !== 'number') continue
    const a = live.get(id)
    if (a) info.name = rowAgentName(a)
    const bgWait = a !== undefined && rowBgWaiting(a)
    const done = !bgWait && (info.endMs !== undefined || rowState.done.has(id))
    const prog = done ? undefined : await progressInfo($, id)
    rows.push({
      id,
      name: info.name ?? 'agent',
      model: info.model,
      effort: info.effort,
      tokens: info.tokens,
      status: done ? 'done' : bgWait ? 'background' : a && a.status === 'waiting' ? 'waiting' : 'running',
      failed: (a && (a.status === 'failed' || a.status === 'killed')) || undefined,
      startMs: info.startMs,
      endMs: done ? info.endMs ?? info.startMs : undefined,
      pct: prog?.pct,
      step: prog?.step,
    })
  }
  rows.sort((x, y) => x.startMs - y.startMs)
  return rows.slice(-max)
}

// What the mod knows of one subagent, for the notice when it ends (hooks/src/agent-view.js): its name as
// $.agent.list gave it (undefined for an id no list named, such as the engine's own forks), whether it is a
// teammate, its latest request's tokens and when its first request went out.
function rowAgentFacts(agentId) {
  const info = rowState.agents.get(agentId)
  if (!info) return undefined
  return { name: info.name, teammate: info.teammate === true, tokens: info.tokens, startMs: info.startMs }
}

// At most one redraw waits at a time; several requests in a burst draw once.
function rowSchedule($) {
  if (rowState.drawPending) return
  rowState.drawPending = true
  try {
    $.clock.after(ROW_DRAW_DELAY_MS, () => {
      rowState.drawPending = false
      rowDraw($)
    })
  } catch (err) {
    rowState.drawPending = false
  }
}

// Skip the timer while the line is known to be unwanted (rechecked every ROW_RECHECK_MS).
async function rowMaybeSchedule($) {
  if (rowState.wanted === false && !rowState.shown && rowState.checkedAt !== undefined) {
    const now = await $.clock.now()
    if (now - rowState.checkedAt < ROW_RECHECK_MS) return
  }
  rowSchedule($)
}

// Called by the turn.step hook in register.js with the request as the host handed it over (before the saver's cap).
async function rowStepStart($, request) {
  try {
    if (request.agentId === undefined) return
    const prev = rowState.agents.get(request.agentId) ?? {}
    // The name is learned while the agent is in the list (once, at its first request), so the timeline can still
    // name it after it has ended and left the list.
    let name = prev.name
    let teammate = prev.teammate
    if (name === undefined && prev.startMs === undefined) {
      try {
        const list = await $.agent.list()
        const found = (Array.isArray(list) ? list : []).find((a) => a && a.id === request.agentId)
        if (found) {
          name = rowAgentName(found)
          teammate = typeof found.teammateId === 'string' && found.teammateId !== ''
        }
      } catch (err) {
        // The name stays unknown; the timeline says "agent".
      }
    }
    // endMs cleared: an agent that resumes (after its background work, or a message) runs again.
    rowState.agents.set(request.agentId, { ...prev, name, teammate, model: request.model, effort: request.effort, startMs: prev.startMs ?? (await $.clock.now()), endMs: undefined })
    rowState.done.delete(request.agentId)
    uiTouch($)
    await rowMaybeSchedule($)
  } catch (err) {
    // Never in the way of a request.
  }
}

// ...and with its result: the tokens of the agent's latest request.
async function rowStepEnd($, request, result) {
  try {
    if (request.agentId === undefined) return
    const tokens = usageTokens(result?.usage)
    if (tokens === undefined) return
    const prev = rowState.agents.get(request.agentId) ?? {}
    rowState.agents.set(request.agentId, { ...prev, tokens })
    uiTouch($)
    await rowMaybeSchedule($)
  } catch (err) {
    // Never in the way of a request.
  }
}

// The host takes one hook per event from a module (no second unmatched session.start, session.end or
// turn.complete), so register.js calls these from its own hooks.
function rowSessionStart($) {
  rowClear($) // a line left from before /clear or /resume
  rowState = freshRow()
  // Not awaited: `jq --version` must not hold the session's start.
  rowCheckWanted($, true).catch(() => {})
  rowJqHint($).catch(() => {})
}

function rowSessionEnd($) {
  rowClear($)
  rowState = freshRow()
}

// A subagent's turn ended: off the line now, even if the list still says running. The main turn's end
// is a second chance to clear a line that nothing else redraws.
async function rowTurnComplete($, e) {
  try {
    if (e.agentId !== undefined) {
      rowState.done.add(e.agentId)
      const info = rowState.agents.get(e.agentId)
      if (info && info.endMs === undefined) rowState.agents.set(e.agentId, { ...info, endMs: await $.clock.now() })
    }
    uiTouch($)
    if (rowState.shown || e.agentId !== undefined) await rowMaybeSchedule($)
  } catch (err) {
    // The turn ends either way.
  }
}

// ===== guard =================================================================
// crew-chief command guard (on by default after the first interactive run). Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
// On when CREW_CHIEF_GUARD=on, or ~/.claude/crew-chief-guard.json exists with "enabled": true (the first run writes it)
// (CREW_CHIEF_GUARD=off always wins). The rules and the ssh parser live in hooks/guard-logic.mjs.
//   - deny: catastrophic rm -rf, the guard's own config, and personal deny rules. Never runs.
//   - confirm: the first attempt is stopped with a checklist the model answers by itself; the identical
//     command again within confirmTtlMinutes (default 360) passes silently. A changed command is new.
//   - warn: the call runs, then a notice and a line of context for the model.
//   - ssh gate (ssh.mode "gate"): first contact with a production host, and remote commands off the
//     read-only list, are handled like confirm (same map, same checklist). Read-only agents get a plain deny.
//   - crew_guard_suggest: a tool Claude calls to flag something the config does not cover. It returns at
//     once, keeps the note in memory (at most 50) and never asks anything; /crew-guard shows them.
//   - first run: in an interactive session with no config file and no SETUP_KEY in the plugin store, the
//     default config is written once (CREW_CHIEF_GUARD_AUTOSETUP=off or CREW_CHIEF_GUARD=off prevent it);
//     the marker keeps a deleted file from coming back. A write that fails leaves the guard on the
//     defaults for that session and is tried again next session. /crew-guard on|off is the only other write.
// The config is read once per session. Gate state lives in memory, with a copy in the plugin store (one key
// per session) so a plugin reload or worker respawn mid-session keeps approved retries; it ends with the session.
// A speed bump, not a security boundary. Any failure lets the call through (fail open).
const GUARD_TOOLS = ['Bash', 'Read', 'Write', 'Edit', 'MultiEdit', 'NotebookEdit']
const GUARD_TTL = DEFAULT_TTL_MIN * 60_000
const GUARD_NO_FILE = { enabled: false, rules: [], disabled: new Set(), confirmTtlMs: GUARD_TTL, ssh: { mode: 'off', prodHosts: [], safeRemote: [], ttlMs: GUARD_TTL } }
const GUARD_TOOL_NAME = 'crew_guard_suggest'
const GUARD_TOOL_MATCH = /^mcp__.+__crew_guard_suggest$/
const GUARD_TOOL_DESCRIPTION =
  "Flag something the command guard should know about: a production host, a critical path, a secret (its name only, never its value), or a dangerous command it does not cover. Returns at once; never stop or wait for an answer. The user reviews these with /crew-guard. Never edit the guard's config yourself."

function guardFresh() {
  return {
    loaded: false,
    loading: undefined,
    on: false,
    why: 'not loaded yet',
    config: undefined,
    gate: newGateState(),
    sid: undefined, // the session id the gate copy is stored under (undefined: memory only)
    agentTypes: new Map(), // agentId -> read-only (true/false), once the agent list named it
    suggestions: [],
    suggestToasted: false,
    held: 0, // first attempts stopped this session (for the band)
    log: [], // { at, kind: 'held' | 'deny' | 'warn', text }, for the guard pane
    noted: false,
    defaults: false, // the loaded file is the first-run default
    toolRegistered: false,
  }
}

let guardState = guardFresh()

async function guardHome($) {
  const home = await $.env.get('HOME')
  if (typeof home === 'string' && home) return home
  const profile = await $.env.get('USERPROFILE')
  return typeof profile === 'string' && profile ? profile : undefined
}

async function guardToast($, key, vars) {
  try {
    $.ui.toast(t(await resolveLang($), key, vars), { timeoutMs: 10000 })
  } catch (err) {
    // The deny or the warning stands without the toast.
  }
}

async function setMarker($, value) {
  try {
    await $.store.set(SETUP_KEY, value)
  } catch (err) {
    // No store: the file check still keeps an existing file untouched.
  }
}

// First run: writes the default config once and returns its text, else undefined. Every step that cannot be
// answered (no surface, no store, fs.exists failing) does nothing, so a -p, SDK or cloud run never writes.
// `fileText`: what was read at `path` (a string when the file is there).
async function guardAutoSetup($, path, fileText) {
  if (String((await $.env.get('CREW_CHIEF_GUARD_AUTOSETUP')) ?? '').trim().toLowerCase() === 'off') return undefined
  let surfaces
  try {
    surfaces = await $.session.surfaces()
  } catch (err) {
    return undefined
  }
  if (!Array.isArray(surfaces) || surfaces.length === 0) return undefined
  let marker
  try {
    marker = await $.store.get(SETUP_KEY)
  } catch (err) {
    return undefined
  }
  // 'failed' (an earlier write that did not land) is tried again; any other marker means set up already.
  if (marker !== undefined && marker !== null && marker !== 'failed') return undefined
  if (typeof fileText === 'string') {
    await setMarker($, 'done') // the owner's own file: never touched
    return undefined
  }
  let exists
  try {
    exists = await $.fs.exists(path)
  } catch (err) {
    return undefined
  }
  if (exists) {
    await setMarker($, 'done')
    return undefined
  }
  const text = defaultConfigText()
  try {
    await $.fs.write(path, text) // creates ~/.claude when missing; the API has no rename, so a plain write
  } catch (err) {
    try {
      $.ui.log('crew-chief guard: could not write the default config to ' + path + ': ' + String(err && err.message ? err.message : err).slice(0, 200), { to: 'debug' })
    } catch (e2) {
      // nothing else to do
    }
    await setMarker($, 'failed')
    // The guard still runs on the defaults in this session (it is not left off silently); the next
    // interactive session tries the write again.
    return text
  }
  await setMarker($, 'done')
  try {
    $.ui.log('crew-chief guard: first run, wrote the default config to ' + path, { to: 'debug' })
  } catch (err) {
    // the toast below still says it
  }
  await guardToast($, 'guard_toast_autosetup', {})
  return text
}

async function guardLoad($) {
  const st = guardState
  st.on = false
  st.config = undefined
  st.defaults = false
  const env = await $.env.get('CREW_CHIEF_GUARD')
  if (String(env ?? '').trim().toLowerCase() === 'off') {
    st.why = 'CREW_CHIEF_GUARD=off'
    return
  }
  const path = configPath(await guardHome($))
  let loaded
  if (path !== undefined) {
    let text
    try {
      text = await $.fs.read(path)
    } catch (err) {
      text = undefined // no file: the guard stays off unless CREW_CHIEF_GUARD=on (or the first run writes it)
    }
    let written
    try {
      written = await guardAutoSetup($, path, text)
    } catch (err) {
      written = undefined // never into the session
    }
    if (typeof written === 'string') text = written // live in this session, not only the next
    if (typeof text === 'string') {
      loaded = compileConfig(text)
      st.defaults = isDefaultConfig(text)
    }
  }
  if (loaded !== undefined && !loaded.ok) {
    st.why = 'the config file is ' + loaded.error
    $.ui.log('crew-chief guard: ' + path + ' is ' + loaded.error + '; the guard is off this session', { to: 'debug' })
    await guardToast($, 'guard_toast_invalid', { path: clipText(path, 60) })
    return
  }
  if (loaded !== undefined) loaded.problems.slice(0, 20).forEach((p) => $.ui.log('crew-chief guard: config: ' + p, { to: 'debug' }))
  st.on = guardOn(env, loaded)
  st.config = loaded !== undefined ? loaded.config : GUARD_NO_FILE
  if (String(env ?? '').trim().toLowerCase() === 'on') st.why = 'CREW_CHIEF_GUARD=on' + (loaded ? '' : ', no config file: built-in rules only')
  else if (loaded === undefined) st.why = 'no config file at ' + (path ?? '~/.claude/crew-chief-guard.json')
  else st.why = loaded.config.enabled ? 'the config file says enabled: true' : 'the config file says enabled: false'
  if (st.on) $.ui.log('crew-chief guard: on, ' + st.config.rules.length + ' personal rules, ssh ' + st.config.ssh.mode, { to: 'debug' })
  if (st.on) await guardGateLoad($)
}

// Brings back this session's gate copy (after a reload) and drops other sessions' stale copies. Any failure
// leaves the gate in memory only.
async function guardGateLoad($) {
  const st = guardState
  try {
    const sid = await $.session.id()
    if (typeof sid !== 'string' || !sid) return
    st.sid = sid
    const now = await $.clock.now()
    const ttl = Math.max(st.config.confirmTtlMs, st.config.ssh.ttlMs)
    gateRestore(st.gate, await $.store.get(GATE_STORE_PREFIX + sid), now, ttl)
    for (const k of await $.store.keys()) {
      if (k.startsWith(GATE_STORE_PREFIX) && k !== GATE_STORE_PREFIX + sid && gateSnapshotStale(await $.store.get(k), now)) await $.store.delete(k)
    }
  } catch (err) {
    // No session id or no store: the gate still works for this module's lifetime.
  }
}

async function guardGateSave($, now) {
  const st = guardState
  if (st.sid === undefined) return
  try {
    await $.store.set(GATE_STORE_PREFIX + st.sid, gateSnapshot(st.gate, now))
  } catch (err) {
    // The deny or the warning stands; only a reload before the retry would forget it.
  }
}

async function guardEnsure($) {
  if (guardState.loaded) return
  const st = guardState
  st.loading ??= guardLoad($).finally(() => {
    st.loaded = true
  })
  await st.loading
}

// For the band: whether the guard is on and how many first attempts it has stopped this session.
// The events of this session for the guard pane, oldest first.
function guardLogList() {
  return guardState.log
}

async function guardLogPush($, kind, text) {
  try {
    const log = guardState.log
    log.push({ at: await $.clock.now(), kind, text: clipText(text, 160) })
    if (log.length > 50) log.splice(0, log.length - 50)
  } catch (err) {
    // The log is cosmetic.
  }
}

function guardSummary() {
  return { loaded: guardState.loaded, on: guardState.on, held: guardState.held }
}

async function guardSessionStart($) {
  guardState = guardFresh()
  try {
    await guardEnsure($)
  } catch (err) {
    guardState.on = false // fail open
  }
  await guardRegisterTool($)
  try {
    await $.command.register({ name: 'crew-guard', description: t(await resolveLang($), 'cmd_guard_description'), argumentHint: '[status|suggestions|on|off]' })
  } catch (err) {
    // The name is taken (another plugin, or this one at an earlier start): the guard works without it.
  }
}

async function guardRegisterTool($) {
  try {
    if (guardState.on && !guardState.toolRegistered) {
      await $.tool.register({
        name: GUARD_TOOL_NAME,
        description: GUARD_TOOL_DESCRIPTION,
        inputSchema: {
          type: 'object',
          properties: {
            kind: { type: 'string', enum: ['host', 'path', 'command', 'secret', 'other'], description: 'What is flagged.' },
            value: { type: 'string', description: 'The host, path or command; for a secret only its name or location, never the value.' },
            reason: { type: 'string', description: 'One line: why it is critical.' },
          },
          required: ['kind', 'value', 'reason'],
        },
        isDeferred: false,
      })
      guardState.toolRegistered = true
    }
  } catch (err) {
    // An older Claude Code, or the name is taken (registered at an earlier start): nothing else depends on it.
  }
}

async function guardSessionEnd($) {
  const sid = guardState.sid
  guardState = guardFresh()
  if (sid === undefined) return
  try {
    await $.store.delete(GATE_STORE_PREFIX + sid)
  } catch (err) {
    // A stale copy is dropped by a later session's load.
  }
}

// Synchronous, so a call the guard never looks at (and every call while it is off) passes untouched.
function guardWants(e) {
  return GUARD_TOOLS.includes(e.tool) && (!guardState.loaded || guardState.on)
}

// Once per session while the guard is on: the note for the next prompt (prompt.submit), else undefined.
function guardNudge() {
  if (!guardState.on || guardState.noted) return undefined
  guardState.noted = true
  return guardState.defaults ? GUARD_NOTE + ' ' + DEFAULTS_NOTE : GUARD_NOTE
}

async function guardReadOnlyAgent($, agentId) {
  const known = guardState.agentTypes.get(agentId)
  if (known !== undefined) return known
  try {
    const list = await $.agent.list()
    const agent = list.find((a) => a.id === agentId)
    if (agent === undefined) return false
    const type = String(agent.type || '').replace(/^crew-chief:/, '')
    const readOnly = READONLY_AGENTS.includes(type)
    guardState.agentTypes.set(agentId, readOnly)
    return readOnly
  } catch (err) {
    return false // unknown: treated as an ordinary agent
  }
}

// undefined = let the call run untouched; { deny } = refuse it; { contexts, notes } = run it, then warn.
async function guardCheck($, e) {
  await guardEnsure($)
  const st = guardState
  if (!st.on || st.config === undefined) return undefined
  const v = classify(e.tool, e, st.config)
  if (v !== null && v.level === 'deny') {
    $.ui.log('crew-chief guard: denied by rule ' + v.rule, { to: 'debug' })
    await guardToast($, 'guard_toast_deny', { text: clipText(v.text) })
    await guardLogPush($, 'deny', v.text + ' [' + v.rule + ']')
    return { deny: ruleDenyMessage(v) }
  }
  const ssh = st.config.ssh
  const touches = e.tool === 'Bash' && ssh.mode !== 'off' && typeof e.command === 'string' ? sshAssess(e.command, ssh) : []
  const confirm = v !== null && v.level === 'confirm'
  if (!confirm && touches.length === 0) {
    return v !== null ? { contexts: [ruleWarnContext(v)], notes: [v.text] } : undefined
  }
  const readOnly = e.agentId !== undefined ? await guardReadOnlyAgent($, e.agentId) : false
  if (confirm && readOnly) {
    await guardToast($, 'guard_toast_deny', { text: clipText(v.text) })
    await guardLogPush($, 'deny', v.text + ' (read-only agent)')
    return { deny: readOnlyDenyMessage(v) }
  }
  const now = await $.clock.now()
  const key = callKey(e.agentId, e.tool, e)
  const d = touches.length > 0 ? gateDecide(st.gate, touches, { mode: ssh.mode, loop: e.agentId, readOnly, now, ttlMs: ssh.ttlMs, command: e.command }) : { action: 'pass' }
  if (d.action === 'deny' && d.kind === 'readonly') {
    await guardToast($, 'guard_toast_readonly', { host: clipText(d.hosts.join(', '), 40), cmd: clipText(e.command) })
    await guardLogPush($, 'deny', 'ssh ' + d.hosts.join(', ') + ' (read-only agent)')
    return { deny: sshDenyMessage(d) }
  }
  const confirmDue = confirm && !isFresh(st.gate, key, now, st.config.confirmTtlMs)
  if (confirmDue || d.action === 'deny') {
    const reasons = []
    if (confirmDue) reasons.push(`${v.text} [${v.rule}]`)
    if (d.action === 'deny') {
      reasons.push(gateReason(d))
      gateRecord(st.gate, d, now)
    }
    markCommand(st.gate, key, now)
    await guardGateSave($, now)
    st.held += 1
    $.ui.log('crew-chief guard: first attempt held' + (confirmDue ? ' (' + v.rule + ')' : '') + (d.action === 'deny' ? ' (ssh ' + d.kind + ')' : ''), { to: 'debug' })
    const what = d.action === 'deny' ? 'ssh ' + d.hosts.join(', ') : v.text
    await guardLogPush($, 'held', what)
    await guardToast($, 'guard_toast_confirm', { text: clipText(what, 50), cmd: clipText(e.command ?? e.file_path ?? '') })
    return { deny: checklistMessage(reasons, { loop: e.agentId, unknown: d.unknown }) }
  }
  // An approved retry passes silently.
  if (confirm) return undefined
  if (d.action === 'warn') {
    gateRecord(st.gate, d, now)
    await guardGateSave($, now)
    return { contexts: [sshWarnContext(d)], notes: ['ssh ' + d.hosts.join(', ') + (d.kind === 'first' ? ': first contact' : ': ' + d.why)] }
  }
  return v !== null ? { contexts: [ruleWarnContext(v)], notes: [v.text] } : undefined
}

// After the call ran: a notice for the person and context for the model. Any failure returns the result as is.
async function guardAfter($, e, g, r) {
  try {
    if (!r || r.deny !== undefined) return r
    try {
      const lang = await resolveLang($)
      $.ui.notice(e.tool_use_id, t(lang, 'guard_notice', { text: clipText(g.notes.join(' · ')) }))
    } catch (err) {
      // The context below still reaches the model.
    }
    await guardLogPush($, 'warn', g.notes.join(' · '))
    const context = [...(r.context ?? []), ...g.contexts]
    // Keep every field the host sent: rebuilding the result by hand could change its shape.
    return { ...r, context }
  } catch (err) {
    return r
  }
}

// /crew-guard on|off: the only write to the config after the first run. Sets `enabled`, keeps every other
// key, and applies the result to this session at once. Returns the reply (English).
async function guardToggle($, enabled) {
  const st = guardState
  const path = configPath(await guardHome($))
  if (path === undefined) return 'crew-chief guard: no HOME (or USERPROFILE), so the config file cannot be found; nothing was changed.'
  let exists
  try {
    exists = await $.fs.exists(path)
  } catch (err) {
    return 'crew-chief guard: could not check ' + path + '; nothing was changed.'
  }
  let text
  let did
  if (exists) {
    let current
    try {
      current = await $.fs.read(path)
    } catch (err) {
      return 'crew-chief guard: could not read ' + path + '; nothing was changed.'
    }
    const next = toggleConfigText(String(current), enabled)
    if (!next.ok) return 'crew-chief guard: ' + path + ' is ' + next.error + ', so it was not changed. Fix the file by hand, then run /crew-guard ' + (enabled ? 'on' : 'off') + ' again.'
    text = next.text
    did = 'set "enabled": ' + enabled + ' in ' + path + ' (other settings kept)'
  } else {
    text = enabled ? defaultConfigText() : offConfigText()
    did = 'created ' + path + (enabled ? ' with the default rules' : ' with "enabled": false')
  }
  try {
    await $.fs.write(path, text)
  } catch (err) {
    return 'crew-chief guard: could not write ' + path + ' (' + String(err && err.message ? err.message : err).slice(0, 120) + '); nothing was changed.'
  }
  const loaded = compileConfig(text)
  const env = await $.env.get('CREW_CHIEF_GUARD')
  const envWord = String(env ?? '').trim().toLowerCase()
  st.config = loaded.ok ? loaded.config : st.config
  st.defaults = isDefaultConfig(text)
  st.on = envWord === 'off' ? false : guardOn(env, loaded)
  st.loaded = true
  if (envWord === 'off') st.why = 'CREW_CHIEF_GUARD=off'
  else if (envWord === 'on') st.why = 'CREW_CHIEF_GUARD=on'
  else st.why = enabled ? 'the config file says enabled: true' : 'the config file says enabled: false'
  await guardRegisterTool($)
  const lines = ['crew-chief guard: ' + did + '. The guard is now ' + (st.on ? 'on' : 'off') + ' in this session.']
  if (envWord === 'off' && enabled) lines.push('CREW_CHIEF_GUARD=off is set, so the guard stays off until you unset it.')
  if (envWord === 'on' && !enabled) lines.push('CREW_CHIEF_GUARD=on is set, so the guard stays on until you unset it.')
  return lines.join('\n')
}

function registerGuard(on) {
  // Returns at once and never asks: the person reads the notes with /crew-guard suggestions.
  on('tool.call', { tool: GUARD_TOOL_MATCH }, async ($, e) => {
    let outcome
    try {
      outcome = guardState.on ? addSuggestion(guardState.suggestions, e) : 'off'
    } catch (err) {
      outcome = 'invalid'
    }
    if (outcome === 'added' && !guardState.suggestToasted) {
      guardState.suggestToasted = true
      await guardToast($, 'guard_toast_suggest', {})
    }
    if (outcome === 'off') return { result: 'The command guard is off; nothing was noted. Carry on.' }
    if (outcome === 'invalid') return { result: 'Not noted: kind must be host, path, command, secret or other, with a value. Carry on; do not stop to wait.' }
    return { result: 'Noted; the user will see it with /crew-guard. Do not stop to wait; carry on with your work.' }
  })

  on('command.run', { command: 'crew-guard' }, async ($, e) => {
    try {
      await guardEnsure($)
    } catch (err) {
      // Status shows what is known.
    }
    const word = String(e.args || '').trim().toLowerCase()
    if (word === 'suggestions') return { text: suggestionsText(guardState.suggestions) }
    if (word === 'on' || word === 'off') {
      // Only the person's own gesture (Enter at the prompt, or the Remote Control bridge) changes the config:
      // a run started by the model, a plugin, the SDK or another session is refused, like an agent's Write.
      const kind = e.origin && typeof e.origin === 'object' ? e.origin.kind : undefined
      if (kind !== 'composer' && kind !== 'bridge') {
        return { text: 'crew-chief guard: /crew-guard ' + word + ' changes the config, so only you can run it by typing it at the prompt (this run came from ' + String(kind ?? 'an unknown source') + '). Nothing was changed.' }
      }
      return { text: await guardToggle($, word === 'on') }
    }
    return {
      text: guardStatusText({ on: guardState.on, why: guardState.why, config: guardState.config, contacted: guardState.gate.contacted.size, suggestions: guardState.suggestions.length }),
    }
  })
}

// ===== crew-ui ===============================================================
// crew-chief crew-ui: a band above the prompt with what a long session needs at a glance. Part of the mod in
// hooks/register.js (Claude Code 2.1.287+). On by default and quiet (it draws nothing while there is nothing to say);
// /crew-ui off turns it off. It never writes to settings.json (the person's own status line is left alone).
//
// In the terminal, with a status line of the person's own set, the quiet band leaves out the context and the
// limits (that line has them); on the Desktop app, or with `/crew-ui full`, they are shown.
// Quiet mode (the default) shows only what is worth a look (the context is not drawn: a toast says once when it
// passes the compaction size or 70 %); `/crew-ui full` shows everything all the time (on Desktop without the graph):
//   ctx 52% 520k/1M   5h 4% ~4h20m   7d 96% ~5d13h   guard on · 1 held   saver on   [ 1 compact ]
//   deep-reader        sonnet-5.5 ●●○○○ medium ▓▓░░░░ 40%  12k  reading auth
//
// The band is raised on the terminal and the Desktop app only (not VS Code, which keeps the status line of
// hooks/src/agent-row.js). One hook draws the band, so another plugin's band and this one compete; a survey
// always wins (hasSurvey). The layout is pure (hooks/ui-logic.mjs); this file reads the data and draws.
//   - data: $.session.usage (context, windows), the subagents of agent-row.js and progress.js, the guard and
//     the saver, and the compaction threshold of compact-flow.js;
//   - redraw: uiTouch() asks for one after a turn, a measurement or an agent change ($.ui.invalidate folds
//     bursts, ten a second at most);
//   - the compact key shows only when compaction is advised (past the "ask" size). Its hotkey is a digit, the
//     one key a band answers from an empty composer without being focused; so it must not exist all the time,
//     or the first digit someone types would press it. Pressing it asks the usual question (/crew-compact).
// The extras (on by default with the band, `/crew-ui extras off`): plain text added to the engine's own lines,
// which take no colour: the model and effort after the spinner word and before the turn line, a note in the
// footer's mode labels, a limit note after the prompt hint. Nothing is replaced, only added.
// CREW_CHIEF_UI=on|off beats the saved choice. Any failure draws nothing (the engine's own band).
const UI_STORE_KEY = 'crew_ui'
const UI_MODE_KEY = 'crew_ui_mode' // 'quiet' (default) or 'full'
const UI_STYLE_KEY = 'crew_ui_style' // boxed (default), plain (theme colours), color (hex), pills
const UI_STYLES = ['plain', 'color', 'pills', 'boxed']
const UI_WORDS_KEY = 'crew_ui_words' // 'on' or 'off' (default): calm spinner words by model
const UI_NOTICE_KEY = 'crew_ui_notice' // set once the first-run notice was shown
const UI_EXTRAS_KEY = 'crew_ui_extras' // 'on' (default) or 'off': the small touches outside the band
const UI_MAX_LINES = 8 // lines of the band at most; the engine's room (maxRows, half the terminal) is the other limit
const UI_DEFAULT_ROWS = 6 // when the engine does not say
const UI_SURFACES = ['terminal', 'desktop']

// Tones are meanings; these are the theme keys the surfaces know (any other colour string is the surface's
// own business, so only theme keys are used).
const UI_TONES = {
  ok: { color: 'success' },
  warn: { color: 'warning' },
  hot: { color: 'claude' },
  crit: { color: 'error' },
  info: { color: 'suggestion' },
  dim: { dimColor: true },
  opus: { color: 'planMode' },
  sonnet: { color: 'permission' },
  haiku: { color: 'success' },
  fable: { color: 'merged' },
  max: { color: 'planMode' },
  rb0: { color: 'error' },
  rb1: { color: 'claude' },
  rb2: { color: 'warning' },
  rb3: { color: 'success' },
  rb4: { color: 'suggestion' },
  other: {},
}

let uiOn = false
let uiFull = false
let uiExtras = true
let uiStyle = 'boxed'
let uiStatusLine = { at: -Infinity, has: false } // is the person's own status line set (read at most once a minute)
let uiDemo = false // sample content, not saved
let uiWords = false
let uiCtxHistory = [] // the context percent after each main turn, for the graph
let uiCtxState = { past: false, high: false } // which context thresholds the last turn was past (for the one toast)
let uiQuestion // { text, answers, resolve }: the one question the band is asking
const UI_ASK_MAX = 4 // answers that fit digit hotkeys
const UI_CARD_FACTS = 4 // facts a question card shows at most (compact-logic.mjs cardFacts cuts them to this too)
let uiMain = { model: undefined, effort: undefined } // the main loop's last request
const UI_CARDS_MAX = 6 // agent cards at most (cardBudget); the agents past them are a '+N more' chip in the status row
const UI_CARD_ROW_ROWS = 3 // rows one row of agent cards takes (two lines and its frame), for the band's budget
let uiArtMemo = new Map() // agent id -> what its drawing showed last and when it changed (for the rolling digits)
// The status line at the foot of the band on the Desktop app (ui.statusline): the folder, the git branch and the
// session's model, read on events (session start, a main turn's start and end), never while drawing.
let uiPlace = { folder: '', branch: '', model: undefined }

// The seconds on the cards: one redraw a second while a drawing of the band (per surface) showed the card of an
// agent that runs, and none otherwise (collapsed, no card, an agent only waiting on its background work, the band
// off). A tick changes nothing but the time Text: no picture's source or key follows the clock, so no picture is
// loaded again. The ticker stops itself once no drawing has asked for it for a few seconds (a band the engine no
// longer draws), and is armed again by the next drawing when the host dropped it.
const UI_TICK_MS = 1000
const UI_TICK_LOST_MS = 3 * UI_TICK_MS // no tick for this long: the timer is armed again
const UI_TICK_IDLE_MS = 5 * UI_TICK_MS // no drawing asked for this long: the timer stops
let uiTicker // { timer, beat }: the running timer and when it last fired (or started)
let uiTickSeen = -Infinity // when a drawing last asked for the ticks
const uiTickWants = new Map() // surface -> whether its last drawing showed a running agent's card

function uiTickStop() {
  try {
    if (uiTicker && uiTicker.timer) uiTicker.timer.cancel()
  } catch (err) {
    // Already stopped.
  }
  uiTicker = undefined
}

function uiTickReset() {
  uiTickStop()
  uiTickWants.clear()
  uiTickSeen = -Infinity
}

const uiTickWanted = () => [...uiTickWants.values()].some(Boolean)

// Called at the end of every drawing of the band with whether it showed a running agent's card.
async function uiTickWant($, surface, want) {
  uiTickWants.set(String(surface), want === true)
  if (!uiTickWanted()) return uiTickStop()
  let now
  try {
    now = await $.clock.now()
  } catch (err) {
    return
  }
  uiTickSeen = now
  if (uiTicker && now - uiTicker.beat < UI_TICK_LOST_MS) return
  uiTickStop()
  const ticker = { timer: undefined, beat: now }
  try {
    ticker.timer = $.clock.every(UI_TICK_MS, async () => {
      if (uiTicker !== ticker) return
      try {
        ticker.beat = await $.clock.now()
      } catch (err) {
        // The beat stays; the tick still redraws.
      }
      if (!uiOn || !uiTickWanted() || ticker.beat - uiTickSeen > UI_TICK_IDLE_MS) return uiTickStop()
      uiTouchNow($)
    })
    uiTicker = ticker
  } catch (err) {
    // No timer: the seconds move on the agents' own events.
  }
}

// Whether the band replaces the status line of agent-row.js: only where the band is drawn.
function uiCovers(surfaces) {
  return uiOn && Array.isArray(surfaces) && surfaces.length > 0 && surfaces.every((s) => UI_SURFACES.includes(s))
}

async function safeStoreGet($, key) {
  try {
    return await $.store.get(key)
  } catch (err) {
    return undefined
  }
}

async function uiReadChoice($) {
  const env = String((await $.env.get('CREW_CHIEF_UI')) ?? '').trim().toLowerCase()
  if (env === 'on' || env === 'off') return { on: env === 'on', source: 'CREW_CHIEF_UI' }
  let saved
  try {
    saved = await $.store.get(UI_STORE_KEY)
  } catch (err) {
    saved = undefined
  }
  // On unless the person turned it off: the quiet band draws nothing while there is nothing to say.
  return { on: saved !== 'off', source: saved === undefined ? 'default' : 'saved choice' }
}

// Called after each finished main turn with the usage: one more point for the context graph, and one toast
// the first time the context passes the compaction size or 70 % (again only after it has dropped below, e.g.
// after a compaction). Never from a render. Also reads the status line's folder, branch and model again (a
// checkout or a move between turns); the mod has one turn.complete hook, which calls this.
async function uiNoteContext($, usage) {
  await uiRefreshPlace($)
  const c = usage?.context
  if (!c || typeof c.tokens !== 'number' || typeof c.window !== 'number' || c.window <= 0) return
  if (compactCtxStale(c.tokens)) return // the size from before a compaction: no point for the graph, no toast
  uiCtxHistory = [...uiCtxHistory, Math.round((c.tokens / c.window) * 100)].slice(-24)
  try {
    if (!uiOn) return
    const chip = ctxChip(c, await compactAskAt($, usage), uiCtxHistory)
    const { state, fire } = ctxAlert(chip, uiCtxState)
    uiCtxState = state
    if (fire) $.ui.toast(t(await resolveLang($), 'ctx_toast', { tokens: chip.tokens, percent: chip.percent }), { timeoutMs: 12000 })
  } catch (err) {
    // The toast is a courtesy.
  }
}

// Called from the mod's turn.step hook with the main loop's request: the model and effort the turn runs on.
function uiNoteMainStep(e) {
  if (typeof e.model === 'string' && e.model !== '') uiMain = { model: e.model, effort: e.effort }
}

// Reads the folder, branch and model for the status line. Skipped while the band or the line is off, and in a
// session that draws in the terminal only (the line is drawn on the Desktop app).
async function uiRefreshPlace($) {
  try {
    if (!uiOn || (await cfgGet($, 'ui.statusline')) !== 'on') return
    const surfaces = await $.session.surfaces()
    if (Array.isArray(surfaces) && surfaces.length > 0 && !surfaces.includes('desktop')) return
    const folder = placeFolder(await $.session.cwd())
    let model
    try {
      model = await $.session.model()
    } catch (err) {
      model = undefined
    }
    let branch = ''
    try {
      const r = await $.process.run(['git', 'symbolic-ref', '--short', 'HEAD'], { timeoutMs: 3000 })
      branch = r.exitCode === 0 ? String(r.stdout ?? '').trim() : ''
    } catch (err) {
      branch = '' // not a repository, a detached head, or no git
    }
    uiPlace = { folder, branch, model: typeof model === 'string' && model !== '' ? model : undefined }
    uiTouch($)
  } catch (err) {
    // The line keeps what it had.
  }
}

async function uiMainChip($) {
  let model = uiMain.model
  if (!model) {
    try {
      model = await $.session.model()
    } catch (err) {
      model = undefined
    }
  }
  return modelChip(model, uiMain.effort)
}

// Rewrites one prop of the engine's own drawing; the engine keeps drawing everything else.
function uiRewrite(next, e, props) {
  return next({ ...e, props: { ...e.props, ...props } })
}

// The plugin's questions go to the band, as buttons, when it can show them: no dialog opens and nothing holds
// the turn (the deadline of ask.js still applies). `undefined` -> the caller opens the usual dialog. Only the
// plugin's own questions come here; Claude's AskUserQuestion is never touched.
// `look` (optional) dresses a question outside the terminal: { kind: 'card', topic, question, facts: [], note,
// labels, quiet, accent } the question card's parts (a topic, a short line, up to four facts, a note, short
// labels for the answers' buttons, the index of the quiet answer and of the accented one). Without it the card
// shows `text`. The terminal and the dialog always show `text`. The answers, their order, keys and what they
// do never change with it.
function uiAskStart($, text, answers, look) {
  try {
    if (!uiCovers(rowSurfaces()) || uiQuestion !== undefined) return undefined
    if (!Array.isArray(answers) || answers.length < 1 || answers.length > UI_ASK_MAX) return undefined
    let resolve
    const promise = new Promise((r) => {
      resolve = r
    })
    const question = { text: String(text), answers: [...answers], resolve, look }
    uiQuestion = question
    try {
      $.ui.invalidate('ui.render')
    } catch (err) {
      // The band draws on the next event.
    }
    // A question that becomes a chip on the Desktop status line (look.chip) says so in its own toast (where to
    // click), once per question, here and never from a drawing; the digits' toast is for the strip and the card.
    uiChipOnly($, look)
      .then(async (chipOnly) => {
        if (chipOnly) {
          if (typeof look.chip.toast === 'string' && look.chip.toast !== '') $.ui.toast(look.chip.toast, { timeoutMs: 12000 })
          return
        }
        $.ui.toast(t(await resolveLang($), 'band_ask_toast', { keys: answers.map((a, i) => i + 1).join(', ') }), { timeoutMs: 15000 })
      })
      .catch(() => {})
    return {
      promise,
      close() {
        if (uiQuestion === question) {
          uiQuestion = undefined
          uiTouchNow($)
        }
      },
    }
  } catch (err) {
    return undefined
  }
}

// Whether a question with a chip form is shown only as that chip: every surface of the session is the Desktop app
// and its status line (ui.statusline) is drawn there.
async function uiChipOnly($, look) {
  if (!look || !look.chip) return false
  const surfaces = rowSurfaces()
  if (!Array.isArray(surfaces) || !surfaces.includes('desktop') || surfaces.includes('terminal')) return false
  return (await cfgGet($, 'ui.statusline')) === 'on'
}

// Answers the band's open question with `answer`, when it is one of its answers (/crew-compact never). True when
// it did.
function uiAnswerOpen($, answer) {
  const q = uiQuestion
  if (q === undefined || !q.answers.includes(answer)) return false
  uiQuestion = undefined
  q.resolve(answer)
  uiTouchNow($)
  return true
}

function uiTouchNow($) {
  try {
    $.ui.invalidate('ui.render')
  } catch (err) {
    // Nothing to redraw.
  }
}

// A redraw soon; $.ui.invalidate folds bursts. Free while the band is off.
function uiTouch($) {
  if (!uiOn) return
  try {
    $.ui.invalidate('ui.render')
  } catch (err) {
    // The band is cosmetic.
  }
}

// The band is on by default, which changes what an updated install shows: say so once, in a toast (never a
// question), and only where the band can be drawn.
async function uiFirstNotice($, choice) {
  try {
    if (!choice.on || choice.source !== 'default') return
    if ((await safeStoreGet($, UI_NOTICE_KEY)) !== undefined) return
    const surfaces = await $.session.surfaces()
    if (!Array.isArray(surfaces) || surfaces.length === 0 || !surfaces.every((s) => UI_SURFACES.includes(s))) return
    await $.store.set(UI_NOTICE_KEY, 'shown')
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'ui_default_toast'), { timeoutMs: 20000 })
  } catch (err) {
    // The notice is a courtesy.
  }
}

async function uiSessionStart($) {
  try {
    const choice = await uiReadChoice($)
    uiOn = choice.on
    uiFull = (await safeStoreGet($, UI_MODE_KEY)) === 'full'
    uiExtras = (await safeStoreGet($, UI_EXTRAS_KEY)) !== 'off'
    uiWords = (await safeStoreGet($, UI_WORDS_KEY)) === 'on'
    uiCtxHistory = []
    uiCtxState = { past: false, high: false }
    uiArtMemo = new Map()
    uiTickReset()
    const savedStyle = await safeStoreGet($, UI_STYLE_KEY)
    uiStyle = UI_STYLES.includes(savedStyle) ? savedStyle : 'boxed'
    uiStatusLine = { at: -Infinity, has: false }
    uiPlace = { folder: '', branch: '', model: undefined }
    // Not awaited: the git read must not hold up the session's start.
    uiRefreshPlace($).catch(() => {})
    // Not awaited either: other mods read the shared perf file, the session's start does not wait for it.
    perfFileWrite($, true).catch(() => {})
    perfReaderRefresh($)
      .then((changed) => changed && uiTouchNow($))
      .catch(() => {})
    await uiFirstNotice($, choice)
    await $.command.register({ name: 'crew-ui', description: 'Show or hide the crew-chief band above the prompt', immediate: true, argumentHint: '[on|off|quiet|full|style <name>|panel capsule|cat|text|demo on|demo off|words on|words off|extras on|extras off|status]' })
  } catch (err) {
    // The name is taken, or an older Claude Code: the band can still be switched with CREW_CHIEF_UI.
  }
  try {
    await $.command.register({ name: 'crew-perf', description: 'Choose what performance mode stills: the agent pictures, the theme, both, or nothing', immediate: true, argumentHint: '[all|agents|theme|off]' })
  } catch (err) {
    // The name is taken, or an older Claude Code: /crew-config set panel.perf and the status line toggle still work.
  }
}

// /crew-perf and the question of the status line toggle: panel.perf as /crew-config saves it, the band redrawn at
// once, one toast saying what is now still. { text, changed }: one short line in the person's language; the
// environment variable, when set, wins and nothing is changed.
async function uiPerfSet($, scope) {
  const lang = await resolveLang($)
  const st = await cfgState($, 'panel.perf')
  if (st.source === 'env') return { text: t(lang, 'perf_env', { value: st.value }), changed: false }
  const r = await cfgSet($, 'panel.perf', scope)
  if (!r.ok) return { text: t(lang, 'perf_store'), changed: false }
  await perfFileWrite($)
  uiTouchNow($)
  try {
    $.ui.toast(t(lang, 'perf_toast_' + r.value), { timeoutMs: 4000 })
  } catch (err) {
    // The toast is a courtesy; the drawing and the command's answer say it too.
  }
  return { text: t(lang, 'perf_set_' + r.value), changed: true }
}

// The performance question open now ({ close }), so a second press on the toggle closes it.
let uiPerfAsking

// Asks in the band what performance mode stills: all, agents only, theme only, and off while something is on;
// the choice in force carries a ✓. Never a dialog: when the band cannot ask, { opened: false, text } says how
// to set it by hand. The answer is handled after this returns (a press or a command does not wait on it); no
// answer before the deadline (ask.timeout, as the plugin's other questions) changes nothing.
async function uiPerfAsk($) {
  const lang = await resolveLang($)
  const st = await cfgState($, 'panel.perf')
  if (st.source === 'env') return { opened: false, text: t(lang, 'perf_env', { value: st.value }) }
  const { scopes, current } = perfChoices(st.value)
  const answers = scopes.map((sc, i) => t(lang, 'perf_answer_' + sc) + (i === current ? ' ✓' : ''))
  const state = t(lang, 'perf_state_' + st.value)
  const look = { kind: 'card', topic: t(lang, 'perf_topic'), question: t(lang, 'perf_question'), facts: [t(lang, 'perf_fact_now', { state })], note: t(lang, 'perf_note') }
  await rowRefreshSurfaces($)
  const band = uiAskStart($, t(lang, 'perf_ask', { state }), answers, look)
  if (band === undefined) return { opened: false, text: t(lang, 'perf_busy') }
  let ms = 0
  try {
    ms = (await cfgGet($, 'ask.timeout')) * 60_000
  } catch (err) {
    ms = 0 // no deadline then
  }
  let timer
  let ended = false
  const end = (toastKey) => {
    if (ended) return
    ended = true
    try {
      if (timer) timer.cancel()
    } catch (err) {
      // Already fired.
    }
    band.close()
    if (uiPerfAsking === asking) uiPerfAsking = undefined
    if (toastKey) {
      try {
        $.ui.toast(t(lang, toastKey), { timeoutMs: 6000 })
      } catch (err) {
        // Nothing changed either way.
      }
    }
  }
  const asking = { close: () => end('perf_ask_closed') }
  uiPerfAsking = asking
  if (ms > 0) timer = $.clock.after(ms, () => end('perf_ask_expired'))
  band.promise
    .then(async (answer) => {
      if (ended) return
      end()
      const at = answers.indexOf(answer)
      if (at < 0) return
      const r = await uiPerfSet($, scopes[at])
      if (!r.changed) $.ui.toast(r.text, { timeoutMs: 8000 })
    })
    .catch(() => {})
  return { opened: true, text: t(lang, 'perf_asking') }
}

// The shared performance-mode file other mods read (desktop-themes draws its light scenes while it is on):
// ~/.claude/perf-mode.json = {"on": <theme>, "agents": bool, "theme": bool, "at": <iso>}, the scope in force (the
// environment wins); "on" mirrors the theme part, so a reader that knows only "on" stills the theme as asked.
// Written whenever panel.perf changes; at session start (`onlyIfStale`) only when the file says otherwise, a
// missing file counting as off. A failed write never fails the toggle.
async function perfFileWrite($, onlyIfStale = false) {
  try {
    const home = (await $.env.get('HOME')) || (await $.env.get('USERPROFILE'))
    if (!home) return false
    const { agents, theme } = perfParts(await cfgGet($, 'panel.perf'))
    const path = `${home}/.claude/perf-mode.json`
    if (onlyIfStale) {
      const exists = await $.fs.exists(path).catch(() => false)
      if (!exists && !agents && !theme) return false
      if (exists) {
        const was = await $.fs.read(path).then((text) => JSON.parse(text), () => undefined)
        if (was && was.on === theme && was.agents === agents && was.theme === theme) return false
      }
    }
    const at = new Date(await $.clock.now()).toISOString()
    await $.fs.write(path, JSON.stringify({ on: theme, agents, theme, at }) + '\n')
    return true
  } catch (err) {
    return false
  }
}

// Whether a theme mod reads perf-mode.json (perfReaderLive over ~/.claude/perf-mode.readers/*.json), as last
// read: on session start, a toggle press, /crew-perf and /crew-config, never while drawing.
let uiPerfReader = false
function perfReaderKnown() {
  return uiPerfReader
}
// Reads the readers' files again; true when the answer changed. Unreadable or missing: no reader.
async function perfReaderRefresh($) {
  let live = false
  try {
    const home = (await $.env.get('HOME')) || (await $.env.get('USERPROFILE'))
    if (home) {
      const dir = `${home}/${PERF_READERS_DIR}`
      const entries = await $.fs.list(dir).catch(() => [])
      const names = (Array.isArray(entries) ? entries : []).filter((x) => x && x.kind !== 'dir' && /\.json$/.test(String(x.name))).slice(0, 32)
      const texts = []
      for (const x of names) {
        const text = await $.fs.read(`${dir}/${x.name}`).catch(() => undefined)
        if (typeof text === 'string') texts.push(text)
      }
      live = perfReaderLive(texts, await $.clock.now())
    }
  } catch (err) {
    live = false
  }
  const changed = live !== uiPerfReader
  uiPerfReader = live
  return changed
}

// With no theme reader there is nothing to ask: the agents part goes off <-> on directly. { text, changed }.
async function uiPerfFlip($) {
  return uiPerfSet($, perfToggle(await cfgGet($, 'panel.perf')))
}

// A press on the toggle asks what to still (uiPerfAsk); a press while that question is open closes it, nothing
// changed. A toast only when the question could not open (the environment wins, or the band is busy). With no
// theme mod reading perf-mode.json it does not ask: it switches the agents part (uiPerfFlip).
async function uiPerfPress($) {
  try {
    if (uiPerfAsking !== undefined) {
      uiPerfAsking.close()
      return
    }
    await perfReaderRefresh($)
    if (!uiPerfReader) {
      const f = await uiPerfFlip($)
      if (!f.changed) $.ui.toast(f.text, { timeoutMs: 8000 })
      return
    }
    const r = await uiPerfAsk($)
    if (!r.opened) $.ui.toast(r.text, { timeoutMs: 8000 })
  } catch (err) {
    // The toggle is a convenience; /crew-perf still works.
  }
}

// Hex colours for the styles other than `plain` (which keeps to theme keys, the one thing every surface knows).
const UI_HEX = {
  ok: '#4ade80',
  warn: '#facc15',
  hot: '#fb923c',
  crit: '#f87171',
  info: '#7dd3fc',
  dim: '#6b7280',
  opus: '#c084fc',
  sonnet: '#60a5fa',
  haiku: '#34d399',
  fable: '#f472b6',
  max: '#e879f9',
  rb0: '#f87171',
  rb1: '#fb923c',
  rb2: '#facc15',
  rb3: '#4ade80',
  rb4: '#e879f9',
  other: '#d1d5db',
}
const UI_PILL_TEXT = '#0b1020'
const UI_LILAC = '#e08ef0' // a question the band is asking: a band of this colour, and, in the boxed style, its frame
const UI_FAMILIES = ['sonnet', 'opus', 'haiku', 'fable', 'other']

// A status line is chips separated by a gap segment of three spaces; pills turns each chip into one coloured
// block (the tone of its value on a background), the other styles keep the segments as they are.
function uiChips(line) {
  const chips = []
  let cur = []
  for (const s of line) {
    if (s.t === '   ' && s.tone === 'dim') {
      if (cur.length > 0) chips.push(cur)
      cur = []
    } else cur.push(s)
  }
  if (cur.length > 0) chips.push(cur)
  return chips
}

// The rolling digits need what each agent's drawing showed before and when it changed; one entry per agent id,
// removed once the agent leaves the band.
function uiArtPrev(agents, now) {
  const seen = new Set()
  const out = new Map()
  for (const a of agents) {
    if (!a || typeof a.id !== 'string') continue
    seen.add(a.id)
    const tokens = artTokens(a.tokens)
    const time = artElapsed(a.elapsedMs)
    const m = uiArtMemo.get(a.id)
    if (!m) {
      uiArtMemo.set(a.id, { tokens, time, prevTokens: undefined, prevTime: undefined, tokensAt: -Infinity, timeAt: -Infinity })
    } else {
      if (m.tokens !== tokens) Object.assign(m, { prevTokens: m.tokens, tokens, tokensAt: now })
      if (m.time !== time) Object.assign(m, { prevTime: m.time, time, timeAt: now })
    }
    const m2 = uiArtMemo.get(a.id)
    out.set(a.id, { tokens: m2.prevTokens, tokensAt: m2.tokensAt, time: m2.prevTime, timeAt: m2.timeAt })
  }
  for (const id of [...uiArtMemo.keys()]) if (!seen.has(id)) uiArtMemo.delete(id)
  return out
}

// What a card shows (the drawn text and the width measured for the grid both come from here, so they agree):
// until the agent's first request names its model the card shows none (no 'starting', no hollow dots).
function uiCardAgent(agent) {
  return { ...agent, pct: typeof agent.artPct === 'number' ? agent.artPct : agent.pct, stale: agent.artStale === true }
}
function uiCardText(a) {
  const c = agentCardText(a)
  return typeof a.model === 'string' && a.model !== '' ? c : { ...c, model: '', dots: '', effort: '' }
}

// rows: bandRows (hooks/ui-logic.mjs). art: { Svg, style, now, prev } where pictures may be drawn (not the
// terminal, panel.style not text, the surface has Svg), else undefined: then everything is the line of text.
// band: { view, fits, lang, viewing, canInput } where an agent row opens on a click (panel.click, not the
// terminal), else undefined. An Svg takes no press, so a picture row gets a small ▸/▾ button at its end; a row
// of text is itself the button.
// perf: { scope } on the Desktop status line, where its end holds the performance mode toggle; else undefined.
function uiTree($, e, rows, onCompact, style, question, art, band, line, perf) {
  const { Box, Text, Button, Input } = $.ui.resolve(e)
  const hex = style !== 'plain'
  const look = (tone) => (hex ? { color: UI_HEX[tone] ?? UI_HEX.other } : UI_TONES[tone] ?? {})
  const text = (s) => {
    const props = { ...(typeof s.color === 'string' ? { color: s.color } : look(s.tone)), wrap: 'truncate-end', children: [s.t] }
    if (s.bold) props.weight = 'bold'
    return Text(props)
  }
  // No clock in the badge either: its source is the same on every drawing (a tick a second must not reload it).
  const badge = (s) => {
    const b = saverBadge(s.badge)
    return art.Svg({ source: b.source, alt: b.alt, width: b.width, height: b.height })
  }
  // '[1] compact' is a button with the shortcut '1'; without the hint (not the terminal) it is just 'compact'.
  const button = (s) => {
    const hint = s.t.startsWith('[1] ')
    return Button({ label: hint ? '1 compact' : 'compact', ...(hint ? { hotkey: '1' } : {}), variant: 'primary', onPress: onCompact })
  }
  const piece = (s) => (s.key === 'compact' ? button(s) : s.badge && art ? badge(s) : text(s))
  const pill = (chip) => {
    const key = chip.find((s) => s.key === 'compact')
    if (key) return button(key)
    const b = chip.find((s) => s.badge)
    if (b && art) return badge(b)
    const value = chip.find((s) => s.tone !== 'dim') ?? chip[0]
    const bg = UI_HEX[value.tone] ?? UI_HEX.other
    return Text({ backgroundColor: bg, color: UI_PILL_TEXT, weight: 'bold', wrap: 'truncate-end', children: [' ' + chip.map((s) => s.t).join('') + ' '] })
  }
  const rowId = (r) => (r.kind === 'agent' && typeof r.agent?.id === 'string' ? r.agent.id : r.kind === 'ended' ? r.id : undefined)
  const isOpen = (id) => band !== undefined && band.view.open.includes(id)
  const arrow = (id) => Text({ ...look('info'), weight: 'bold', children: [isOpen(id) ? '▾ ' : '▸ '] })
  // No hotkey: digits answer the band's questions and the compact key. Focus (ctrl+x tab, Tab) and Enter work.
  // A press opens the agent in the side pane (/crew-agents). The Desktop app draws a plain Button's label as its
  // text, so the label is the short hint itself; the agent's name is in the row beside it.
  const opener = (id, children) =>
    Button({ key: 'open-' + id, plain: true, label: t(band.lang, 'band_open_hint'), onPress: () => avBandOpenPane($, id), children })
  const detailButton = (id) => opener(id, [Text({ ...look('info'), weight: 'bold', children: [t(band.lang, 'band_open_hint')] })])
  // One agent as a card: the character, two lines of Text (name, model, effort and the 'first run' tag where it
  // fits; the bar, the estimate, the step), tokens and time in a fixed column, and the details button. Nothing
  // wraps: every Text but the step sits in a Box that does not shrink; the step alone is cut short. The cells of
  // a row are one width (cardGrid in hooks/ui-logic.mjs), so the figures and the button sit at one x in every
  // card. Only the two small pictures are Svg, and neither holds a clock, so the face's motion runs on (see
  // agentFace in hooks/panel-art-logic.mjs; panel.perf keeps it fully still).
  const cardText = uiCardText
  const cardAgent = uiCardAgent
  const openLabel = band !== undefined ? t(band.lang, 'band_open_hint') : ''
  const fixed = (key, text) => Box({ key, flexShrink: 0, children: [text] })
  const card = (agent, id, grid) => {
    const a = cardAgent(agent)
    const c = cardText(a)
    // An agent waiting on its own background work (rowBandRows: bgWait) stands fully still, as in
    // performance mode, for its card alone: it is not finished, only resting.
    // No clock: the face's source is the same on every drawing, so its frame is never loaded again (blank while
    // it loads); the phase is the agent's own (agentFace).
    const face = agentFace(a, { style: art.style, perf: art.perf || a.bgWait === true })
    const bar = agentBar(a)
    const k = id ?? agent.id
    const dim = (t) => Text({ color: CARD_LOOK.mute, children: [t] })
    const line1 = [fixed('name', Text({ color: c.color, weight: 'bold', children: [c.name] }))]
    if (c.model) line1.push(fixed('model', dim(c.model)))
    if (c.dots) line1.push(fixed('dots', Text({ color: c.color, children: [c.dots.replace(/ /g, '')] })))
    if (c.effort) line1.push(fixed('effort', dim(c.effort)))
    // The 'first run' tag: after the effort where the cell has room for it, else left out (the estimate already
    // says 'no estimate').
    // A small calm tag for an agent waiting on its background work, in the same room ('first run' gives way to it).
    const tagFits = cardLine1Cells(c, true) <= cardTextRoom(grid.cell, id !== undefined ? openLabel : '')
    if (a.bgWait === true && a.bgTag && tagFits) line1.push(fixed('bgwait', Text({ color: CARD_LOOK.mute, children: [a.bgTag] })))
    else if (c.fresh && tagFits) line1.push(fixed('fresh', Text({ color: CARD_LOOK.warn, weight: 'bold', children: ['first run'] })))
    // Each picture sits in a Box keyed by the agent (an Svg takes no key): a redraw finds the same element at the
    // same place and the Desktop app keeps the image, so its animation runs on instead of starting over.
    // A moving face is drawn in a frame (isInteractive), not as an image: measured live on 2026-11-15, the app
    // loaded the image again about every 2 s from the band's last drawing, so the motion jumped back. A frame is
    // loaded again only when its markup changes (blank while it loads), so the face's source never changes
    // between drawings of the same agent; a still face stays a plain image.
    const svg = (p, frame = false) => art.Svg({ source: p.source, alt: p.alt, width: p.width, height: p.height, ...(frame ? { isInteractive: true } : {}) })
    const pic = (name, p, frame = false) => Box({ key: name + '-' + k, flexShrink: 0, children: [svg(p, frame)] })
    // The bar is still (nothing in it moves), so a new 5% step may load it again without a visible jump.
    const line2 = [pic('agentbar', bar)]
    line2.push(fixed('pct', Text({ color: c.hasPct ? CARD_LOOK.ink : CARD_LOOK.mute, ...(c.hasPct ? { weight: 'bold' } : {}), children: [c.pct] })))
    // The step: the one piece that gives way, cut short at the card's edge.
    if (c.step) line2.push(Box({ key: 'step', flexShrink: 1, flexGrow: 1, minWidth: 0, children: [Text({ color: CARD_LOOK.mute, wrap: 'truncate-end', children: [c.step] })] }))
    // A fixed width, right-aligned: tokens and time end at the same x in every card, the button after them.
    const figures = Box({ key: 'figs', flexDirection: 'column', alignItems: 'flex-end', justifyContent: 'center', width: CARD_CELLS.figs, flexShrink: 0, children: [fixed('tokens', Text({ color: CARD_LOOK.ink, weight: 'bold', children: [c.tokens || ' '] })), fixed('time', dim(c.time || ' '))] })
    // minWidth 0: a long step is cut short instead of pushing the figures and the button out.
    const lineBox = (children) => Box({ flexDirection: 'row', alignItems: 'center', gap: 1, minWidth: 0, children })
    const children = [
      pic('agentface', face, !(art.perf || a.bgWait === true)),
      Box({ flexDirection: 'column', flexGrow: 1, flexShrink: 1, minWidth: 0, children: [lineBox(line1), lineBox(line2)] }),
      figures,
    ]
    if (id !== undefined) children.push(Box({ key: 'open', flexShrink: 0, children: [detailButton(id)] }))
    return Box({ key: 'agentrow-' + k, ...cardFrame(CARD_LOOK.border, grid), backgroundColor: CARD_LOOK.bg, children })
  }
  // The frame every cell of the grid shares (cards and the empty fillers): width 0 and an equal grow, so the
  // cells of a row split it evenly whatever they hold; the same border, padding and least width, so a filler is
  // exactly as wide as a card.
  const cardFrame = (borderColor, grid) => ({ flexDirection: 'row', alignItems: 'center', gap: 1, borderStyle: 'round', borderColor, paddingX: 1, width: 0, minWidth: grid.minWidth, flexGrow: 1, flexShrink: 1 })
  const row = (r) => {
    const id = band !== undefined ? rowId(r) : undefined
    if (r.kind === 'agent' && art) return card(r.agent, id, grid)
    if (id !== undefined) return opener(id, [arrow(id), ...r.line.map(text)])
    if (style === 'pills' && r.kind === 'status') return Box({ flexDirection: 'row', gap: 1, children: uiChips(r.line).map(pill) })
    return Box({ flexDirection: 'row', ...(art ? { alignItems: 'center' } : {}), children: r.line.map(piece) })
  }
  const answerPress = (q, answer) => () => {
    if (uiQuestion === q) {
      uiQuestion = undefined
      q.resolve(answer)
      uiTouchNow($)
    }
  }
  const askBlock = () => {
    const q = question
    const buttons = q.answers.map((answer, i) =>
      Button({
        key: 'ask-' + (i + 1),
        label: `${i + 1} ${answer}`,
        hotkey: String(i + 1),
        variant: i === 0 ? 'primary' : 'secondary',
        onPress: answerPress(q, answer),
      }),
    )
    return Box({
      flexDirection: 'column',
      children: [Text({ backgroundColor: UI_LILAC, color: UI_PILL_TEXT, weight: 'bold', wrap: 'wrap', children: [' crew-chief asks: ' + q.text + ' '] }), Box({ flexDirection: 'row', gap: 2, children: buttons })],
    })
  }
  // A plugin question outside the terminal: a quiet card in the agent cards' look (a faint frame, a see-through
  // fill), three rows at most so the status line under it stays in view. Row one: a lilac mark, 'crew-chief'
  // muted, the topic in bold, the short question. Row two: the facts as small chips, then what happens next in
  // one muted line, cut short at the edge. Row three: the answers as normal Buttons, the first (the recommended
  // one) primary, the others secondary, the `quiet` one (don't ask again) a dim plain button at the end; the
  // `accent` one's text in the saver's ultra colour. The labels are `labels[i]` or the answers themselves: a
  // desktop draws a Button's label as its text and its hotkey as a small badge. Same answers, keys, hotkeys and
  // order as the terminal's strip; a press answers with the answer, never the label. A question with no card
  // form (look.kind 'card': { topic, question, facts, note, labels, quiet, accent }) shows its plain text.
  const questionCard = () => {
    const q = question
    const c = q.look && q.look.kind === 'card' ? q.look : {}
    const topic = typeof c.topic === 'string' ? c.topic : ''
    const line = typeof c.question === 'string' && c.question !== '' ? c.question : q.text
    const facts = Array.isArray(c.facts) ? c.facts.filter((f) => typeof f === 'string' && f !== '').slice(0, UI_CARD_FACTS) : []
    const note = typeof c.note === 'string' ? c.note : ''
    const labels = Array.isArray(c.labels) ? c.labels : []
    const quiet = Number.isInteger(c.quiet) && c.quiet > 0 ? c.quiet : -1
    const accent = Number.isInteger(c.accent) && c.accent > 0 ? c.accent : -1
    const mute = (s) => Text({ color: CARD_LOOK.mute, children: [s] })
    const fixedText = (key, el) => Box({ key, flexShrink: 0, children: [el] })
    const head = Box({
      key: 'ask-head',
      flexDirection: 'row',
      alignItems: 'center',
      gap: 1,
      minWidth: 0,
      children: [
        fixedText('ask-mark', Text({ color: UI_LILAC, children: ['◆'] })),
        fixedText('ask-from', mute('crew-chief')),
        ...(topic !== '' ? [fixedText('ask-dot', mute('·')), fixedText('ask-topic', Text({ color: CARD_LOOK.ink, weight: 'bold', children: [topic] }))] : []),
        Box({ key: 'ask-line', flexShrink: 1, minWidth: 0, children: [Text({ color: CARD_LOOK.ink, wrap: topic !== '' ? 'truncate-end' : 'wrap', children: [line] })] }),
      ],
    })
    const chips = facts.map((f, i) => fixedText('ask-fact-' + i, Text({ color: CARD_LOOK.mute, backgroundColor: CARD_LOOK.border, children: [' ' + f + ' '] })))
    const info = [...chips, ...(note !== '' ? [Box({ key: 'ask-note', flexShrink: 1, minWidth: 0, children: [Text({ color: CARD_LOOK.mute, wrap: 'truncate-end', children: [note] })] })] : [])]
    const buttons = q.answers.map((answer, i) => {
      const label = typeof labels[i] === 'string' && labels[i] !== '' ? labels[i] : answer
      const base = { key: 'ask-' + (i + 1), label, hotkey: String(i + 1), onPress: answerPress(q, answer) }
      if (i === quiet) return Button({ ...base, plain: true, dimColor: true })
      const tint = i === accent ? { children: [Text({ color: SAVER_LOOK.ultra.text, children: [label] })] } : {}
      return Button({ ...base, variant: i === 0 ? 'primary' : 'secondary', ...tint })
    })
    return Box({
      key: 'ask-card',
      flexDirection: 'column',
      gap: 'xs',
      borderStyle: 'round',
      borderColor: CARD_LOOK.border,
      backgroundColor: CARD_LOOK.bg,
      paddingX: 1,
      children: [
        head,
        ...(info.length > 0 ? [Box({ key: 'ask-facts', flexDirection: 'row', alignItems: 'center', gap: 1, minWidth: 0, children: info })] : []),
        Box({ key: 'ask-answers', flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: 1, children: buttons }),
      ],
    })
  }
  const desk = e.surface !== 'terminal'
  const ask = () => (desk ? questionCard() : askBlock())
  // Under an open agent: its last steps (or its report), then Full view and the message button, and the field.
  const section = (id) => {
    const fit = band.fits.get(id)
    if (!fit || fit.hidden) return []
    const lang = band.lang
    const entry = band.view.cache.get(id)
    const plan = sendPlan(entry?.done === true, lang)
    const composing = band.view.composing.has(id)
    const out = fit.lines.map((line, i) => Box({ key: 'sec-' + id + '-' + i, flexDirection: 'row', paddingLeft: 2, children: line.map(text) }))
    const write = composing ? t(lang, 'band_cancel') : plan.label
    out.push(
      Box({
        key: 'ctl-' + id,
        flexDirection: 'row',
        alignItems: 'center',
        gap: 1,
        paddingLeft: 2,
        children: [
          Button({ key: 'full-' + id, label: t(lang, 'band_full'), variant: 'secondary', onPress: () => avBandFullView($, id) }),
          // Without a text field on this surface, writing goes through the full view: the prompt's next Enter goes to the agent.
          Button({ key: 'write-' + id, label: write, variant: 'secondary', onPress: () => (band.canInput ? avBandCompose($, id) : avBandFullView($, id)) }),
          Text({ dimColor: true, wrap: 'truncate-end', children: [fit.more > 0 ? t(lang, 'band_more', { n: fit.more }) : t(lang, 'band_view_hint')] }),
        ],
      }),
    )
    if (composing && band.canInput) {
      const draft = avBandDraftOf(id)
      out.push(
        Input({
          key: 'msg-' + id,
          placeholder: t(lang, plan.noteKey, { name: avBandName(id) }),
          submitLabel: plan.confirm ? plan.label : t(lang, 'band_send'),
          autoFocus: true,
          ...(typeof draft === 'string' ? { value: draft } : {}),
          onInput: (value) => avBandDraft(id, value),
          onSubmit: (value) => {
            avBandSend($, id, value)
          },
        }),
      )
    }
    return out
  }
  const back = () =>
    Box({
      key: 'view-back-row',
      flexDirection: 'row',
      alignItems: 'center',
      gap: 1,
      children: [
        Button({ key: 'view-back', label: t(band.lang, 'band_back'), variant: 'primary', onPress: () => avBandFullView($, undefined) }),
        Text({ dimColor: true, wrap: 'truncate-end', children: [t(band.lang, 'band_viewing', { name: avBandName(band.viewing) })] }),
      ],
    })
  const drawn = []
  // Cards that follow each other form a grid: rows of `per` cells, every cell the same width, the last row
  // filled out with empty cells so the columns line up. How many share a row comes from the width the widest
  // card needs (cardGrid), worked out once for every card in the band, so all of them are one width and the
  // buttons sit at one x. Keys are by the group's order among card groups and the row's index, never by what is
  // drawn before them (the status line comes and goes; a key that moved with it made every picture load again).
  const needOf = (r) => cardNeedCells(cardText(cardAgent(r.agent)), band !== undefined && rowId(r) !== undefined ? openLabel : '')
  const gridFor = (list) => cardGrid(art?.columns, list.map(needOf))
  const shown = art ? rows.filter((r) => r.kind === 'agent' && !(band !== undefined && rowId(r) !== undefined && isOpen(rowId(r)))) : []
  // The render lays the cards out once for the band's room (cardBudget) and hands the grid over: the same one
  // that decided how many cards fit, so the rows drawn are the rows budgeted.
  const grid = art?.grid ?? gridFor(shown)
  const per = grid.per
  let cards = []
  let groups = 0
  const flush = () => {
    if (cards.length > 0) {
      const g = groups++
      const lines = []
      for (let i = 0; i < cards.length; i += per) {
        const cells = cards.slice(i, i + per)
        for (let j = cells.length; j < per; j++) cells.push(Box({ key: `agentfill-${g}-${i / per}-${j}`, ...cardFrame('rgba(0,0,0,0)', grid) }))
        lines.push(Box({ key: `agentline-${g}-${i / per}`, flexDirection: 'row', gap: 'md', children: cells }))
      }
      drawn.push(Box({ key: 'agentcards-' + g, flexDirection: 'column', gap: 'md', children: lines }))
    }
    cards = []
  }
  for (const r of rows) {
    const id = band !== undefined ? rowId(r) : undefined
    if (r.kind === 'agent' && art && !(id !== undefined && isOpen(id))) {
      cards.push(card(r.agent, id, grid))
      continue
    }
    flush()
    drawn.push(row(r))
    if (id !== undefined && isOpen(id)) drawn.push(...section(id))
  }
  flush()
  const top = band !== undefined && band.viewing !== undefined ? [back()] : []
  // Pictures get room between them (the cards sat edge to edge); lines of text stay tight.
  const content = [...top, ...(question ? [ask()] : []), ...drawn]
  const frame = (key, children) => {
    const body = Box({ ...(style !== 'boxed' ? key : {}), flexDirection: 'column', ...(art ? { gap: 'sm' } : {}), children })
    if (style !== 'boxed') return body
    // The terminal's strip asks in lilac, frame and all; on Desktop the question is its own card, the frame stays quiet.
    return Box({ ...key, borderStyle: 'round', borderColor: question && !desk ? UI_LILAC : UI_HEX.dim, paddingX: 1, flexDirection: 'column', children: [body] })
  }
  if (!Array.isArray(line) || line.length === 0) return frame({}, content)
  // The status line is the band's last row, under the frame, right above the prompt; with nothing else to say
  // the band is that line alone (no empty frame). The wrapper and both parts keep their keys from one drawing
  // to the next, so the pictures in the frame stay where they were.
  // Its right end holds the performance mode toggle (Desktop only): the ⚡ dim when off, with a small a or t when
  // only the agents or only the theme stand still, lit and bold for both (perfIcon); the label is the same text. Before it, while compaction is advised and no agent is on the band, the compact key in the
  // same small style (no hotkey: the Desktop band is not focused; the terminal keeps its '1 compact').
  const compactKey = perf && perf.compact
    ? [
        Button({
          key: 'band-compact',
          plain: true,
          label: COMPACT_LABEL,
          hover: { color: '#ffffff' },
          onPress: onCompact,
          children: [Text({ color: UI_HEX.info, children: [COMPACT_ICON] })],
        }),
      ]
    : []
  // On: a filled dot, bright and bold; off: an empty dot, faint (the colour alone did not tell them apart).
  const saverLit = perf ? perf.saver !== 'off' && perf.saver !== undefined : false
  const saverText = perf ? `${saverLit ? '●' : '○'} ${perf.saver === 'ultra' ? 'ultra-saver' : 'saver'}` : ''
  const saverMark = perf && perf.saver
    ? [
        // A plain button: each press steps off -> saver -> ultra-saver -> off. Off it stays, dim, so it can be turned
        // on again from here (as the ⚡ stays dim when off).
        Box({
          key: 'band-saver',
          children: [
            Button({
              key: 'band-saver-btn',
              plain: true,
              label: saverText,
              ...(saverLit ? { color: SAVER_ON_HEX } : { dimColor: true }),
              hover: { color: '#ffffff' },
              onPress: () => {
                void uiSaverPress($).catch(() => {})
              },
              children: [Text({ color: saverLit ? SAVER_ON_HEX : SAVER_OFF_HEX, ...(saverLit ? { weight: 'bold' } : {}), children: [saverText] })],
            }),
          ],
        }),
      ]
    : []
  // A question with a chip form (look.chip), where the status line is drawn: instead of a card, a lit chip before
  // the saver word (a press answers chip.yes) and a small ✕ (answers chip.no). Plain buttons: the Desktop app
  // draws the label as the text, so the label is the visible text. Same answers and the same deadline as the card.
  const chipQ = perf ? perf.ask : undefined
  const chip = chipQ ? chipQ.look.chip : undefined
  const chipText = chip ? String(chip.text) : ''
  // Each in a keyed Box of its own (as the saver word): `hover` follows the nearest keyed Box, so the chip turns
  // white under the pointer, not whenever the pointer is anywhere on the line.
  const askChip = chip
    ? [
        Box({
          key: 'band-compact-ask-box',
          children: [
            Button({
              key: 'band-compact-ask',
              plain: true,
              label: chipText,
              hover: { color: '#ffffff' },
              onPress: answerPress(chipQ, chipQ.answers[chip.yes ?? 0]),
              children: [Text({ color: UI_HEX.warn, weight: 'bold', children: [chipText] })],
            }),
          ],
        }),
        Box({
          key: 'band-compact-no-box',
          children: [
            Button({
              key: 'band-compact-no',
              plain: true,
              label: '✕',
              dimColor: true,
              hover: { color: '#ffffff' },
              onPress: answerPress(chipQ, chipQ.answers[chip.no ?? 1]),
              children: [Text({ color: UI_HEX.dim, children: ['✕'] })],
            }),
          ],
        }),
      ]
    : []
  const mark = perf ? perfIcon(perf.scope) : undefined
  const toggle = perf
    ? [
        ...askChip,
        ...saverMark,
        ...compactKey,
        Button({
          key: 'band-perf',
          plain: true,
          label: mark.text,
          ...(mark.lit ? {} : { dimColor: true }),
          hover: { color: '#ffffff' },
          onPress: () => uiPerfPress($),
          children: [Text({ color: mark.lit ? UI_HEX.warn : UI_HEX.dim, ...(mark.bold ? { weight: 'bold' } : {}), children: [mark.text] })],
        }),
      ]
    : []
  const segs = Box({ key: 'band-statusline-text', flexDirection: 'row', alignItems: 'center', flexGrow: 1, flexShrink: 1, children: line.map(text) })
  const foot = Box({ key: 'band-statusline', flexDirection: 'row', alignItems: 'center', gap: 'sm', children: [segs, ...toggle] })
  return Box({ key: 'band-with-line', flexDirection: 'column', ...(art ? { gap: 'sm' } : {}), children: [...(content.length > 0 ? [frame({ key: 'band-body' }, content)] : []), foot] })
}

// Whether the band is asking one of the plugin's questions now (it asks one at a time).
function uiAsking() {
  return uiQuestion !== undefined
}

function uiLilac() {
  return UI_LILAC
}

// One segment (hooks/ui-logic.mjs) as a Text in the band's colours; for the panes.
function uiSegmentText($, e) {
  const { Text } = $.ui.resolve(e)
  const hex = uiStyle !== 'plain'
  const look = (tone) => (hex ? { color: UI_HEX[tone] ?? UI_HEX.other } : UI_TONES[tone] ?? {})
  return (s) => {
    const props = { ...look(s.tone), wrap: 'truncate-end', children: [s.t] }
    if (s.bold) props.weight = 'bold'
    return Text(props)
  }
}

// Lines of segments as one column of rows, in the band's colours; for the panes.
function uiLinesTree($, e, lines) {
  const { Box } = $.ui.resolve(e)
  const text = uiSegmentText($, e)
  return Box({ flexDirection: 'column', children: lines.map((line) => Box({ flexDirection: 'row', children: line.map(text) })) })
}

// Whether the person has a status line of their own (settings.json `statusLine`). It most likely shows the
// context and the limits already, so the band leaves those out of it in the terminal (the Desktop app has no
// such line, and `/crew-ui full` shows everything).
async function uiHasStatusLine($) {
  const now = await $.clock.now()
  if (now - uiStatusLine.at < 60_000) return uiStatusLine.has
  let has = false
  try {
    const value = await $.settings.read({ key: 'statusLine' })
    has = value !== undefined && value !== null && typeof value === 'object' && typeof value.command === 'string' && value.command !== ''
  } catch (err) {
    has = false
  }
  uiStatusLine = { at: now, has }
  return has
}

async function uiFacts($, saverOn) {
  const now = await $.clock.now()
  const usage = await $.session.usage()
  const askAt = await compactAskAt($, usage)
  const guard = guardSummary()
  const stale = compactCtxStale(usage?.context?.tokens)
  return {
    tokens: stale ? undefined : usage?.context?.tokens,
    ctx: stale ? ctxStaleChip(usage?.context) : ctxChip(usage?.context, askAt, uiCtxHistory),
    five: windowChip(usage?.rateLimits, 'five_hour', now),
    week: windowChip(usage?.rateLimits, 'seven_day', now),
    guard: guard.loaded ? { on: guard.on, held: guard.held } : undefined,
    saver: saverOn,
  }
}

// The saver word's press: register.js steps its state and names the message; the toast and redraw are ours.
async function uiSaverPress($) {
  if (typeof uiSaverCycle !== 'function') return
  const key = uiSaverCycle()
  $.ui.toast(t(await resolveLang($), key), { timeoutMs: 6000 })
  $.ui.invalidate('ui.render')
}

const SAVER_ON_HEX = '#7ee8ff'
const SAVER_OFF_HEX = '#4b5262'

let uiSaverCycle // set by registerUi: steps the saver off -> on -> ultra -> off and returns the message key

function registerUi(on, saverOn, saverCycle) {
  uiSaverCycle = saverCycle
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    let tick = false // whether this drawing shows a running agent's card (the seconds tick while one does)
    try {
      if (!uiOn || e.props?.hasSurvey === true) return next(e)
      const question = uiQuestion
      const demo = uiDemo ? demoContent(await $.clock.now()) : undefined
      const facts = demo ? demo.facts : await uiFacts($, saverOn())
      if (!demo) facts.compactKey = facts.ctx?.past === true && question === undefined && compactKeyDue(facts.tokens)
      const columns = typeof e.props?.bodyColumns === 'number' ? e.props.bodyColumns : 100
      // The room the engine gives the band, less the frame (boxed: two rows) and a question (the strip and its
      // buttons, or the Desktop card): the question's rows are taken first, measured from what it draws.
      const rows = typeof e.props?.maxRows === 'number' ? e.props.maxRows : UI_DEFAULT_ROWS
      if (!demo && !uiFull && e.surface === 'terminal' && (await uiHasStatusLine($))) {
        // The compact key was decided above from the context; only the figures the status line has are left out.
        facts.ctx = undefined
        facts.five = undefined
        facts.week = undefined
      }
      // On the Desktop app the band ends with the status line (ui.statusline): it takes the context and the
      // windows, so the status row leaves them out instead of showing them twice.
      let line
      let perf
      if (e.surface === 'desktop' && (await cfgGet($, 'ui.statusline')) === 'on') {
        perf = { scope: perfInForce(await cfgGet($, 'panel.perf'), uiPerfReader) }
        line = statusLineSegments({ folder: uiPlace.folder, branch: uiPlace.branch, five: facts.five, week: facts.week, ctx: facts.ctx, tokens: facts.tokens, model: uiMain.model ?? uiPlace.model, effort: uiMain.effort })
        facts.ctx = undefined
        facts.five = undefined
        facts.week = undefined
      }
      // The sparkline of blocks is large outside the terminal (Desktop): there the context is the figures only.
      if (e.surface !== 'terminal' && facts.ctx?.spark) facts.ctx = { ...facts.ctx, spark: '' }
      const agents = demo ? demo.agents : await rowBandRows($)
      // Past agents.warn running at once, say so: attention, not tokens, is what runs out first.
      const warnAt = await cfgGet($, 'agents.warn')
      facts.busy = Array.isArray(agents) && agents.length > warnAt ? agents.length : undefined
      // No compact key while a subagent is on the band or runs (pending, running, or waiting: the band draws all
      // three, the running count alone missed the last): pressing it could only say "wait"; it comes back after.
      if (!demo && facts.compactKey && ((Array.isArray(agents) && agents.length > 0) || (await runningAgents($)) > 0)) facts.compactKey = false
      // With the Desktop status line the key sits at its end, beside the performance toggle, not in the frame.
      // The saver too: a short word at the line's end instead of a row of its own above it (user, 2026-11-16).
      if (perf && line && line.length > 0) {
        perf.compact = facts.compactKey === true
        facts.compactKey = false
        perf.saver = facts.saver || 'off'
        facts.saver = undefined
      }
      // A question with a chip form is the chip at the status line's end there, not a card in the band; `shownQ`
      // is the question the band itself draws (as a strip or a card).
      let shownQ = question
      if (perf && line && line.length > 0 && question && question.look && question.look.chip) {
        perf.ask = question
        shownQ = undefined
      }
      const qRows = shownQ ? questionRows(shownQ, e.surface !== 'terminal', columns - (uiStyle === 'boxed' ? 4 : 0)) : 0
      const maxLines = Math.max(1, Math.min(UI_MAX_LINES, rows - (uiStyle === 'boxed' ? 2 : 0) - qRows))
      // Cards sit two or three to a row outside the terminal, so more agents fit than lines of text would.
      const panel = await cfgGet($, 'panel.style')
      const cardsDrawn = e.surface !== 'terminal' && panel !== 'text' && typeof $.ui.resolve(e).Svg === 'function'
      const lines = line && line.length > 0 ? Math.max(1, maxLines - 1) : maxLines
      const statusFacts = uiFull || demo ? facts : quietFacts(facts)
      let status = statusSegments(statusFacts, e.surface === 'terminal')
      // Outside the terminal the cards are laid out once per drawing for the room the engine gives (maxRows): the
      // frame, the status line, the status row and a question first, then whole rows of cards (UI_CARD_ROW_ROWS
      // each). Every cell holds a card; the agents past them are a small '+N more' chip at the start of the status
      // row (which it brings when there was none), never a card's cell. With a question shown the cards may get no
      // row at all: the question is never cut off. It depends on nothing but the agents, that room and what is
      // drawn around the cards, so the same agents get the same layout on every drawing, and the status line at
      // the band's foot is never pushed out of view by a half-cut row of cards.
      let cap = lines
      let cardLayout
      let cardAgents = agents
      if (cardsDrawn && Array.isArray(agents) && agents.length > 0) {
        const clickOn = !demo && (await cfgGet($, 'panel.click')) === 'on'
        const openLabel = clickOn ? t(avBandView().lang, 'band_open_hint') : ''
        const needs = agents.map((a) => cardNeedCells(uiCardText(uiCardAgent(a)), clickOn && typeof a?.id === 'string' ? openLabel : ''))
        const fit = (statusRows) =>
          cardRowsFit({ maxRows: rows, frame: uiStyle === 'boxed' ? 2 : 0, line: line && line.length > 0 ? 1 : 0, status: statusRows, question: qRows }, UI_CARD_ROW_ROWS, shownQ ? 0 : 1)
        cardLayout = cardBudget(columns, needs, fit(status.length > 0 ? 1 : 0), UI_CARDS_MAX)
        // The chip brings a status row where there was none: laid out again for the row it takes.
        if (cardLayout.more > 0 && status.length === 0) cardLayout = cardBudget(columns, needs, fit(1), UI_CARDS_MAX)
        if (cardLayout.more > 0) status = statusSegments({ ...statusFacts, more: t(await resolveLang($), 'band_more_agents', { n: cardLayout.more }) }, e.surface === 'terminal')
        cardAgents = agents.slice(0, cardLayout.shown)
        cap = (status.length > 0 ? 1 : 0) + cardLayout.rows
      }
      const bandList = bandRows({ status, agents: cardAgents, maxLines: cap, width: columns })
      // A click on an agent row opens what it does under it (not the terminal; panel.click). What is drawn was
      // read by hooks/src/agent-view.js on an event or a press; nothing is read here.
      let band
      if (!demo && e.surface !== 'terminal' && (await cfgGet($, 'panel.click')) === 'on') {
        const view = avBandView()
        const viewing = typeof e.props?.view?.agentId === 'string' && e.props.view.agentId !== '' ? e.props.view.agentId : undefined
        const live = new Set(bandList.filter((r) => r.kind === 'agent').map((r) => r.agent?.id))
        // An open agent that has finished leaves the live rows: it keeps a line of its own while it is open.
        const before = bandList.length
        for (const id of view.open) {
          const c = view.cache.get(id)
          if (!live.has(id) && c && Array.isArray(c.rowLine)) bandList.push({ kind: 'ended', id, line: c.rowLine })
        }
        const shown = new Set(bandList.map((r) => (r.kind === 'agent' ? r.agent?.id : r.kind === 'ended' ? r.id : undefined)))
        // A mobile app may get an empty Box for an Input it did not declare, and a hook cannot tell: the field is
        // drawn on the Desktop app only; elsewhere Write opens the full view.
        const canInput = e.surface === 'desktop' && typeof $.ui.resolve(e).Input === 'function'
        const specs = view.open
          .filter((id) => shown.has(id))
          .map((id) => {
            const sec = view.cache.get(id)?.section ?? { lines: [[{ t: t(view.lang, 'band_reading'), tone: 'dim' }]], keep: 'head' }
            return { id, lines: sec.lines, keep: sec.keep, fixed: 1 + (canInput && view.composing.has(id) ? 1 : 0) }
          })
        const used = bandList.length + (uiStyle === 'boxed' ? 2 : 0) + qRows + (viewing ? 1 : 0)
        // The finished agents' own lines count toward the 12 rows the open agents may add in all.
        const fits = new Map(fitSections(specs, bandExtraRows(rows, used, Math.max(0, BAND_EXTRA_MAX - (bandList.length - before)))).map((f) => [f.id, f]))
        band = { view, fits, lang: view.lang, viewing, canInput }
      }
      if (bandList.length === 0 && shownQ === undefined && band?.viewing === undefined && !(line && line.length > 0)) return next(e)
      // Pictures outside the terminal (panel.style capsule or cat), where the surface draws Svg.
      const { Svg } = $.ui.resolve(e)
      let art
      if (cardsDrawn) {
        const now = await $.clock.now()
        // panel.perf agents or all: the characters stand fully still.
        const perf = perfParts(perfInForce(await cfgGet($, 'panel.perf'), uiPerfReader)).agents
        art = { Svg, style: panel, perf, now, prev: uiArtPrev(Array.isArray(agents) ? agents : [], now), columns, grid: cardLayout?.grid }
      }
      const tree = uiTree($, e, bandList, () => compactBandPress($), uiStyle, shownQ, art, band, line, perf)
      // A running agent's card on screen (not collapsed, not the sample content): its seconds tick.
      tick = art !== undefined && !demo && e.props?.isCollapsed !== true && bandList.some((r) => r.kind === 'agent' && r.agent?.bgWait !== true)
      return tree
    } catch (err) {
      tick = false
      return next(e)
    } finally {
      await uiTickWant($, e.surface, tick)
    }
  })

  // The status line's folder, branch and model: read again at a main turn's start while the folder is not known
  // yet (the first read can fall in the Desktop app's spare folder); after every main turn see uiNoteContext.
  on('turn.start', async ($, e, next) => {
    if (e.agentId === undefined && uiPlace.folder === '') await uiRefreshPlace($)
    return next(e)
  })

  // The small touches: plain text added to the engine's own drawing (no colour there). Each leaves the
  // drawing alone when it has nothing to add, and any failure draws the engine's own.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    try {
      if (!uiOn || !uiExtras || typeof e.props?.suffix !== 'string') return next(e)
      const chip = await uiMainChip($)
      const word = uiWords && e.props.message === null ? spinnerWord(uiMain.model) : undefined
      if (chip === '' && word === undefined) return next(e)
      return uiRewrite(next, e, { ...(word !== undefined ? { word } : {}), suffix: chip === '' ? e.props.suffix : e.props.suffix + ' ' + chip })
    } catch (err) {
      return next(e)
    }
  })

  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    try {
      if (!uiOn || !uiExtras || e.props?.isExpanded === true || typeof e.props?.word !== 'string') return next(e)
      const chip = await uiMainChip($)
      return chip === '' ? next(e) : uiRewrite(next, e, { word: chip + ' · ' + e.props.word })
    } catch (err) {
      return next(e)
    }
  })

  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    try {
      if (!uiOn || !uiExtras || !Array.isArray(e.props?.modes)) return next(e)
      const labels = modeLabels(await uiFacts($, saverOn()))
      return labels.length === 0 ? next(e) : uiRewrite(next, e, { modes: [...e.props.modes, ...labels] })
    } catch (err) {
      return next(e)
    }
  })

  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    try {
      if (!uiOn || !uiExtras || e.props?.isDraft === true) return next(e)
      const tail = tailText(await uiFacts($, saverOn()))
      return tail === '' ? next(e) : uiRewrite(next, e, { tail })
    } catch (err) {
      return next(e)
    }
  })

  on('command.run', { command: 'crew-perf' }, async ($, e) => {
    let scope = perfArg(e.args)
    if (scope === undefined) return { text: t(await resolveLang($), 'perf_bad') }
    await perfReaderRefresh($)
    // No theme mod reads perf-mode.json: no question, on means the agents, the theme cannot be stilled.
    if (!uiPerfReader) {
      if (scope === PERF_ASK) return { text: (await uiPerfFlip($)).text }
      if (String(e.args ?? '').trim().toLowerCase() === 'on') scope = 'agents'
      else if (scope === 'theme' || scope === 'all') return { text: t(await resolveLang($), 'perf_no_reader') }
    }
    if (scope === PERF_ASK) return { text: (await uiPerfAsk($)).text }
    return { text: (await uiPerfSet($, scope)).text }
  })

  on('command.run', { command: 'crew-ui' }, async ($, e) => {
    const word = String(e.args || '').trim().toLowerCase()
    const choice = await uiReadChoice($)
    if (word === 'on' || word === 'off') {
      try {
        await $.store.set(UI_STORE_KEY, word)
      } catch (err) {
        // Kept for this session only.
      }
      const envWins = choice.source === 'CREW_CHIEF_UI'
      uiOn = envWins ? choice.on : word === 'on'
      try {
        $.ui.invalidate('ui.render')
      } catch (err) {
        // Nothing to redraw.
      }
      if (envWins && choice.on !== (word === 'on')) {
        return { text: `crew-ui: CREW_CHIEF_UI=${choice.on ? 'on' : 'off'} is set in the environment and wins; your choice (${word}) is saved for when it is unset.` }
      }
      return { text: word === 'on' ? 'crew-ui: the band is on (terminal and Desktop app; VS Code keeps its status line). Turn it off with /crew-ui off. Nothing in settings.json was changed.' : 'crew-ui: the band is off.' }
    }
    if (word === 'words on' || word === 'words off') {
      uiWords = word === 'words on'
      try {
        await $.store.set(UI_WORDS_KEY, uiWords ? 'on' : 'off')
      } catch (err) {
        // Kept for this session only.
      }
      return { text: uiWords ? 'crew-ui: words on: the spinner says Pondering (Opus), Working (Sonnet), Skimming (Haiku) instead of the engine\'s random word.' : 'crew-ui: words off: the engine picks the spinner word.' }
    }
    if (word.startsWith('style')) {
      const name = word.slice(5).trim()
      if (!UI_STYLES.includes(name)) return { text: `crew-ui: style is ${uiStyle}; choose one of ${UI_STYLES.join(', ')} (plain: theme colours; color: hex colours; pills: coloured blocks for the status line; boxed: a rounded frame). Try /crew-ui demo on first.` }
      uiStyle = name
      try {
        await $.store.set(UI_STYLE_KEY, name)
      } catch (err) {
        // Kept for this session only.
      }
      try {
        $.ui.invalidate('ui.render')
      } catch (err) {
        // Nothing to redraw.
      }
      return { text: `crew-ui: style ${name}.` }
    }
    if (word === 'panel' || word.startsWith('panel ')) {
      const name = word.slice(5).trim()
      const now = await cfgGet($, 'panel.style')
      if (!['capsule', 'cat', 'text'].includes(name)) return { text: `crew-ui: panel is ${now}; choose capsule (a yellow capsule buddy), cat (a blue point kitten) or text (the plain line). Outside the terminal each running subagent is drawn as a small picture; the terminal always gets the line. Same as /crew-config set panel.style <name>.` }
      const r = await cfgSet($, 'panel.style', name)
      if (!r.ok) return { text: 'crew-ui: the plugin store is not available here, so the panel style cannot be saved (set CREW_CHIEF_PANEL_STYLE instead).' }
      try {
        $.ui.invalidate('ui.render')
      } catch (err) {
        // Nothing to redraw.
      }
      if (r.source === 'env') return { text: `crew-ui: panel ${name} is saved, but CREW_CHIEF_PANEL_STYLE=${r.value} is set in the environment and wins.` }
      return { text: `crew-ui: panel ${name}${name === 'text' ? ': the plain line everywhere, no pictures.' : ': outside the terminal each running subagent is drawn as a ' + (name === 'cat' ? 'blue point kitten' : 'capsule buddy') + '. The terminal keeps the line.'}` }
    }
    if (word === 'demo on' || word === 'demo off') {
      uiDemo = word === 'demo on'
      try {
        $.ui.invalidate('ui.render')
      } catch (err) {
        // Nothing to redraw.
      }
      return { text: uiDemo ? 'crew-ui: demo on: the band shows sample content (three agents, limits, guard, the compact key) so styles can be judged. /crew-ui demo off to stop; /crew-ui style plain|color|pills|boxed to change the look.' : 'crew-ui: demo off.' }
    }
    if (word === 'extras on' || word === 'extras off') {
      uiExtras = word === 'extras on'
      try {
        await $.store.set(UI_EXTRAS_KEY, uiExtras ? 'on' : 'off')
      } catch (err) {
        // Kept for this session only.
      }
      try {
        $.ui.invalidate('ui.render')
      } catch (err) {
        // Nothing to redraw.
      }
      return { text: uiExtras ? 'crew-ui: extras on: the model and effort next to the spinner and the turn line, crew-chief notes in the mode line, a limit note after the prompt hint.' : 'crew-ui: extras off: only the band is drawn.' }
    }
    if (word === 'full' || word === 'quiet') {
      uiFull = word === 'full'
      try {
        await $.store.set(UI_MODE_KEY, word)
      } catch (err) {
        // Kept for this session only.
      }
      try {
        $.ui.invalidate('ui.render')
      } catch (err) {
        // Nothing to redraw.
      }
      return { text: uiFull ? 'crew-ui: full mode: the context, both limit windows and the guard are always shown.' : 'crew-ui: quiet mode: the band shows only what is worth a look (a running subagent, a limit or the context from 70 %, something the guard stopped, a compaction due).' }
    }
    const surfaces = await $.session.surfaces()
    return {
      text: `crew-ui: the band is ${uiOn ? 'on' : 'off'} (${choice.source}), ${uiFull ? 'full' : 'quiet'} mode. Surfaces here: ${Array.isArray(surfaces) && surfaces.length > 0 ? surfaces.join(', ') : 'none'}; the band is drawn on ${UI_SURFACES.join(' and ')}. /crew-ui on | off | quiet | full | style <name> | panel capsule|cat|text | demo on | words on | extras on | extras off.`,
    }
  })
}

// ===== agent-view ============================================================
// crew-chief agent view and agent-done notices. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
// On the Desktop app a subagent cannot be opened and watched the way the terminal allows, and its end is easy
// to miss. Two things help:
//   - a notice when a subagent finishes: a toast ("implementer finished: 3:35 · 58k · 14 calls") and the same
//     as a system notification through the person's own channel ($.ui.notify). Runs that end within
//     NOTIFY_BATCH_MS share one notice; a run shorter than notify.min, a run the person stopped, a teammate's
//     turn and the engine's own forks are not announced. /crew-config notify.agent, notify.native, notify.min.
//   - /crew-agents: a pane with this session's subagents (count chips; running ones first, then finished, each
//     row a button) and, for the one picked, a title (status, time, tokens), its report wrapped and folded, its
//     last steps from its transcript ($.session.messages({ agentId })) with each result summarised, and, on the
//     Desktop app, a message field with a send button.
// Reads happen in events (the command, a press, the agents' own turn.step / tool.call / turn.complete,
// throttled to one refresh per VIEW_REFRESH_MS, and a slow tick while the pane is open), never while
// drawing: the pane's hook only draws what the last refresh kept. The transcript is kept in memory for the
// open pane alone; it is never written, stored, logged or sent, and is dropped when the pane closes.
// Any failure leaves the turn, the call and the engine's own drawing alone.
const AV_PANE_ID = 'crew-agent-view'
const AV_TICK_MS = 5000 // while the pane is open: durations move, an agent that left the list is seen
const AV_ANSWER_MAX = 4000 // characters of an agent's report kept for the pane
const AV_ANSWERS_KEPT = 30
const AV_CONFIRM_MS = 60_000 // a send that restarts a finished agent waits this long for a yes, then is dropped

function avFresh() {
  return {
    open: false,
    selected: undefined,
    snapshot: undefined, // { chips, rows, detail } as the last refresh left it; what the pane draws
    finishedAll: false, // the pane lists every finished agent, not only the newest VIEW_FINISHED_MAX
    reportOpenFor: undefined, // the agent whose report is shown whole
    taskOpenFor: undefined, // the agent whose task is shown whole
    nowOpenFor: undefined, // the agent whose latest text ('Now') is shown whole
    stepsAllFor: undefined, // the agent whose every kept step row is shown, not only the last VIEW_STEPS_SHOWN
    stepsOpen: new Set(), // step rows opened (a Bash call's command, a group's calls), by their first call's id
    paths: undefined, // { root, home } for shortening paths, read once per open pane
    detailFor: undefined, // the agent the detail was read for
    detailStale: true,
    selectedLive: false, // the picked agent still runs (the slow tick reads its transcript again)
    paneDrafts: new Map(), // agentId -> what is typed in the pane's message field; never stored, gone with the pane
    paneNotes: new Map(), // agentId -> { kind: 'error', text }: the line under the field when a message is refused
    // agentId -> the bubbles sent from the pane (agent-view-logic msgTrack): in memory for the session alone, never
    // stored, logged or sent anywhere; kept when the pane closes, gone with the session.
    paneSent: new Map(),
    lastRefreshAt: undefined,
    refreshBooked: false,
    tick: undefined,
    ended: new Map(), // agentId -> { reason, answer }: in memory, for the pane's status and report
    announced: new Set(), // agentId|turnId of runs already counted for a notice
    batch: [],
    batchBooked: false,
    mainEndedAt: undefined,
    // Agents opened in the band (a click on their row, hooks/src/crew-ui.js); the same refresh and throttle as
    // the pane. In memory only, gone with the session or a reload of the module.
    band: {
      open: [], // agent ids, oldest first (toggleOpen)
      cache: new Map(), // agentId -> { section, done, name, rowLine, stale }: what the band draws for it
      composing: new Set(), // agents whose message field is shown
      drafts: new Map(), // agentId -> the text being typed, until it is sent or the field closes; never stored
    },
  }
}

let avState = avFresh()
let avLang = 'en' // the language of the last refresh, for the one line drawn without one

function avStopTick() {
  try {
    if (avState.tick) avState.tick.cancel()
  } catch (err) {
    // Already stopped.
  }
  avState.tick = undefined
}

// A new session, /clear, /resume or the session's end: nothing of the last one stays.
function avReset() {
  avStopTick()
  avState = avFresh()
}

// The pane was closed (its mark, ctrl+x x, Esc, /crew-agents again, /crew-panel close): the transcript goes too.
function avClosed() {
  avStopTick()
  avState.open = false
  avState.snapshot = undefined
  avState.detailFor = undefined
  avState.detailStale = true
  avState.finishedAll = false
  avState.reportOpenFor = undefined
  avState.taskOpenFor = undefined
  avState.nowOpenFor = undefined
  avState.stepsAllFor = undefined
  avState.stepsOpen.clear()
  avState.paths = undefined
  avState.paneDrafts.clear()
  avState.paneNotes.clear()
}

// ---- the notice ----------------------------------------------------------------------------------

async function avFlush($) {
  avState.batchBooked = false
  const items = avState.batch
  avState.batch = []
  if (items.length === 0) return
  try {
    const lang = await resolveLang($)
    const text = notifyText(lang, items)
    if (text === '') return
    // The open agents pane already shows who finished: a toast would only cover it (the user's ask, 2026-11-15).
    // The host tells a hook nothing of the app's own focus, so the system notification keeps its own rule.
    if ((await cfgGet($, 'notify.agent')) === 'on' && !avState.open) $.ui.toast(text, { timeoutMs: 10000 })
    const native = nativeWanted({ nativeOn: (await cfgGet($, 'notify.native')) === 'on', mainEndedAt: avState.mainEndedAt, firstEndAt: Math.min(...items.map((i) => i.endedAt)) })
    if (native) {
      try {
        await $.ui.notify(text, { title: 'crew-chief' })
      } catch (err) {
        // No channel, notifications off, or a hook refused it: the toast has said it.
      }
    }
  } catch (err) {
    // A missed notice is better than a broken turn.
  }
}

async function avAnnounce($, e, now) {
  const toast = (await cfgGet($, 'notify.agent')) === 'on'
  const native = (await cfgGet($, 'notify.native')) === 'on'
  if (!toast && !native) return
  const key = e.agentId + '|' + String(e.turnId)
  const facts = rowAgentFacts(e.agentId) ?? {}
  let known = facts.name !== undefined
  let teammate = facts.teammate === true
  let name = facts.name
  if (!known) {
    // An agent whose first request the mod missed is still named by the list (it may say completed now).
    try {
      const list = await $.agent.list()
      const found = (Array.isArray(list) ? list : []).find((a) => a && a.id === e.agentId)
      if (found) {
        known = true
        teammate = typeof found.teammateId === 'string' && found.teammateId !== ''
        name = found.name || found.type || found.description || 'agent'
      }
    } catch (err) {
      // Unknown: not announced.
    }
  }
  const durationMs = typeof e.durationMs === 'number' ? e.durationMs : typeof facts.startMs === 'number' ? now - facts.startMs : undefined
  const minSec = await cfgGet($, 'notify.min')
  if (!notifyWanted({ known, teammate, reason: e.reason, durationMs, minSec, already: avState.announced.has(key) })) return
  avState.announced.add(key)
  avState.batch.push({ name, durationMs, tokens: facts.tokens, calls: progressStats(e.agentId)?.calls, error: e.reason === 'error' || e.reason === 'refusal', endedAt: now })
  if (avState.batchBooked) return
  avState.batchBooked = true
  try {
    $.clock.after(NOTIFY_BATCH_MS, () => {
      avFlush($)
    })
  } catch (err) {
    avState.batchBooked = false
  }
}

// Called from the mod's turn.complete hook for every turn: the main loop's end is noted (the host raises its
// own notice then), a subagent's run is remembered for the pane and, maybe, announced.
async function avTurnComplete($, e) {
  try {
    const now = await $.clock.now()
    if (e.agentId === undefined) {
      avState.mainEndedAt = now
      return
    }
    const answer = typeof e.answer === 'string' ? e.answer.slice(0, AV_ANSWER_MAX) : undefined
    avState.ended.delete(e.agentId)
    avState.ended.set(e.agentId, { reason: e.reason, answer, durationMs: typeof e.durationMs === 'number' ? e.durationMs : undefined, at: now })
    while (avState.ended.size > AV_ANSWERS_KEPT) avState.ended.delete(avState.ended.keys().next().value)
    await avAnnounce($, e, now)
    avNote($, e.agentId)
  } catch (err) {
    // The turn ends either way.
  }
}

// ---- the pane ------------------------------------------------------------------------------------

// One refresh for both readers: the pane when it is open, the agents opened in the band. Only from events,
// presses and the pane's tick (throttled by avNote), never while drawing.
async function avRefresh($) {
  try {
    if (!avState.open && avState.band.open.length === 0) return
    const now = await $.clock.now()
    avState.lastRefreshAt = now
    const lang = await resolveLang($)
    avLang = lang
    if (avState.open) await avPaneRefresh($, now, lang)
    if (avState.band.open.length > 0) await avBandRefresh($, now, lang)
    $.ui.invalidate('ui.render')
  } catch (err) {
    // The pane and the band keep what they drew last.
  }
}

async function avPaneRefresh($, now, lang) {
  try {
    // Only agents the list named: the engine's own forks (compaction, memory) make requests too.
    const named = (await rowTimeline($, VIEW_LIST_MAX * 2)).filter((r) => rowAgentFacts(r.id)?.name !== undefined)
    const rows = named.slice(-VIEW_LIST_MAX).reverse().map((r) => {
      const ended = avState.ended.get(r.id)
      const error = r.failed === true || (ended !== undefined && (ended.reason === 'error' || ended.reason === 'refusal'))
      return { ...r, status: error ? 'error' : r.status }
    })
    if (avState.paths === undefined) avState.paths = await avPaths($)
    const selected = pickSelected(rows, avState.selected)
    avState.selected = selected
    let detail = avState.snapshot?.detail
    if (selected === undefined) {
      detail = undefined
    } else if (avState.detailStale || avState.detailFor !== selected || detail === undefined) {
      const row = rows.find((r) => r.id === selected)
      let found
      try {
        found = await $.session.messages({ agentId: selected })
      } catch (err) {
        found = { deny: String(err && err.message ? err.message : err) }
      }
      const ended = avState.ended.get(selected)
      avPaneTrack(selected, found, ended)
      detail = paneDetail(
        {
          name: row?.name ?? rowAgentFacts(selected)?.name,
          row,
          messages: Array.isArray(found) ? found : undefined,
          deny: Array.isArray(found) ? undefined : String(found?.deny ?? 'unknown'),
          answer: ended?.answer,
          done: row ? row.status === 'done' || row.status === 'error' : ended !== undefined,
          calls: progressStats(selected)?.calls,
        },
        { lang, now, ...avState.paths },
      )
      avState.detailFor = selected
      avState.detailStale = false
    } else {
      // Only the figures move between two reads of the transcript.
      const row = rows.find((r) => r.id === selected)
      if (row) {
        const fresh = paneRow(row, now)
        detail = { ...detail, title: { ...detail.title, time: fresh.time, tokens: fresh.tokens } }
      }
    }
    const picked = rows.find((r) => r.id === selected)
    avState.selectedLive = picked !== undefined && (picked.status === 'running' || picked.status === 'waiting' || picked.status === 'background')
    avState.snapshot = { chips: paneChips(rows, lang), rows: rows.map((r) => paneRow(r, now)), detail }
  } catch (err) {
    // The pane keeps what it drew last.
  }
}

// The project root and the home dir, for the pane's short paths (./, ~). Read in a refresh, never while drawing.
async function avPaths($) {
  const read = async (f) => {
    try {
      const v = await f()
      return typeof v === 'string' && v.startsWith('/') ? v : undefined
    } catch (err) {
      return undefined
    }
  }
  const root = (await read(() => $.session.root())) ?? (await read(() => $.session.cwd()))
  const home = await read(() => $.env.get('HOME'))
  return { root, home }
}

// The picked agent's bubbles moved by what was just read: its transcript when the session can read it, and its
// tool calls and the end of its run since each was sent.
function avPaneTrack(id, found, ended) {
  const sent = avState.paneSent.get(id)
  if (!sent || sent.length === 0) return
  // Both only move a bubble forward: the transcript first, then what the agent did since, for a message the
  // transcript does not show as sent (framed or escaped differently).
  avState.paneSent.set(id, msgFallback(msgTrack(sent, found), { calls: progressStats(id)?.calls, endedAt: ended?.at, answer: ended?.answer }))
}

// An agent did something (a request, a tool call, the end of its run): refresh the open pane, at most once
// per VIEW_REFRESH_MS, the last event never lost. Not awaited by the hooks that call it.
function avNote($, agentId) {
  // An open agent did something: read it again (a finished one that runs again after a message, too).
  const cached = agentId !== undefined ? avState.band.cache.get(agentId) : undefined
  if (cached) cached.stale = true
  if (!avState.open && avState.band.open.length === 0) return
  if (agentId !== undefined && agentId === avState.selected) avState.detailStale = true
  $.clock
    .now()
    .then((now) => {
      const plan = throttlePlan(avState.lastRefreshAt, now, VIEW_REFRESH_MS, avState.refreshBooked)
      if (plan.run === 'now') return avRefresh($)
      if (plan.run === 'later') {
        avState.refreshBooked = true
        $.clock.after(plan.delayMs, () => {
          avState.refreshBooked = false
          avRefresh($)
        })
      }
      return undefined
    })
    .catch(() => {
      avState.refreshBooked = false
    })
}

// A row was pressed: show that agent (a person's act, so no throttle).
function avSelect($, id) {
  avState.selected = id
  avState.paneNotes.clear()
  avState.detailStale = true
  avRefresh($)
}

// A press that only changes what is shown of the last refresh: no read, a redraw.
function avRedraw($) {
  try {
    $.ui.invalidate('ui.render')
  } catch (err) {
    // Nothing to redraw.
  }
}

// Theme keys for the tones, so the pane follows the theme the person picked; the model colour is the band's.
const AV_TONE = { ok: { color: 'success' }, warn: { color: 'warning' }, crit: { color: 'error' }, info: { color: 'suggestion' }, dim: { dimColor: true } }

// The pane's drawing, from the last refresh only (no reads here). The terminal and VS Code get the same tree;
// a tint marks the picked row on the Desktop app, a ▸ elsewhere. Text wraps: nothing the person needs is cut.
function avTree($, e) {
  const { Box, Text, Button, Input, Markdown } = $.ui.resolve(e)
  const desktop = e.surface === 'desktop'
  const lang = avLang
  const txt = (s, props = {}) => Text({ wrap: 'wrap', ...props, children: [s] })
  const one = (s, props = {}) => Text({ wrap: 'truncate-end', ...props, children: [s] }) // a name or an argument: one line
  const mute = (s, props = {}) => txt(s, { dimColor: true, ...props })
  const label = (s) => mute(s, { size: 'footnote', weight: 'semibold' })
  // A section's title and, beside it, what the section is, in a few words.
  const heading = (title, hint) => line([one(title, { size: 'footnote', weight: 'semibold' }), ...(hint ? [one(hint, { dimColor: true, size: 'footnote' })] : [])])
  const toned = (tone) => AV_TONE[tone] ?? {}
  const col = (children, props = {}) => Box({ flexDirection: 'column', ...props, children })
  const line = (children, props = {}) => Box({ flexDirection: 'row', alignItems: 'center', gap: 1, ...props, children })
  const linkButton = (key, text, onPress) => Button({ key, plain: true, dimColor: true, onPress, children: [Text({ size: 'footnote', children: [text] })] })
  const snap = avState.snapshot
  // No refresh behind it: the session restarted (/clear, /resume) under a pane that stayed on screen.
  if (!snap) return col([mute(t(lang, 'view_reopen'))], { paddingX: 1 })
  const children = []

  // The counts, as small chips.
  if (snap.chips.length > 0) {
    const chip = (c) => Box({ borderStyle: 'round', borderColor: CARD_LOOK.border, paddingX: 1, children: [one(c.text, { ...toned(c.tone), size: 'footnote', weight: 'medium' })] })
    children.push(line(snap.chips.map(chip), { flexWrap: 'wrap' }))
  } else children.push(mute(t(lang, 'view_none')))

  // The list: running first, then finished; each row one button, its time and tokens at the right edge.
  const selected = avState.selected
  const agentRow = (r) => {
    const on = r.id === selected
    const parts = []
    if (!desktop) parts.push(Text({ color: 'suggestion', weight: 'bold', children: [on ? '▸ ' : '  '] }))
    parts.push(Text({ ...toned(r.tone), children: [r.glyph + ' '] }))
    parts.push(one(r.name, { color: modelColor(r.rawModel), weight: on ? 'bold' : 'medium' }))
    if (r.model) parts.push(one('  ' + r.model, { dimColor: true, size: 'footnote' }))
    // Its group says running or finished; a wait or a failure is said in words too.
    if (r.status === 'waiting' || r.status === 'background' || r.status === 'error') parts.push(one('  ' + t(lang, 'view_status_' + r.status), { ...toned(r.tone), size: 'footnote' }))
    const figures = [r.time, r.tokens].filter((x) => x !== '').join(' · ')
    const look = desktop ? (on ? { backgroundColor: CARD_LOOK.border } : { hover: { backgroundColor: CARD_LOOK.bg } }) : {}
    return Box({
      key: 'row-' + r.id,
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'space-between',
      gap: 1,
      paddingX: 1,
      ...look,
      children: [Button({ key: 'agent-' + r.id, plain: true, onPress: () => avSelect($, r.id), children: parts }), one(figures || ' ', { dimColor: !on, tabular: true, size: 'footnote' })],
    })
  }
  const groups = paneGroups(snap.rows, { selected, all: avState.finishedAll })
  const finishedTotal = snap.rows.filter((r) => !r.live).length
  if (groups.running.length > 0) children.push(col([label(t(lang, 'view_group_running')), ...groups.running.map(agentRow)]))
  if (groups.finished.length > 0) {
    const list = [label(t(lang, 'view_group_done')), ...groups.finished.map(agentRow)]
    if (groups.hidden > 0 || (avState.finishedAll && finishedTotal > VIEW_FINISHED_MAX)) {
      const more = groups.hidden > 0
      list.push(
        linkButton('pane-more-agents', more ? t(lang, 'view_show_more', { n: groups.hidden }) : t(lang, 'view_show_less'), () => {
          avState.finishedAll = more
          avRedraw($)
        }),
      )
    }
    children.push(col(list))
  }

  // The picked agent: title, task, report, last steps.
  const d = snap.detail
  const id = selected
  const listed = id !== undefined && snap.rows.some((r) => r.id === id)
  if (d && listed) {
    const ti = d.title
    const facts = [ti.model, ti.time, ti.tokens ? t(lang, 'view_tokens', { n: ti.tokens }) : '', ti.calls].filter((x) => x !== '').join(' · ')
    const section = [
      col([
        line([one(ti.name, { color: modelColor(ti.rawModel), weight: 'bold', size: 'heading' }), one(ti.glyph + ' ' + ti.statusText, { ...toned(ti.tone), size: 'footnote', weight: 'medium' })]),
        ...(facts ? [mute(facts, { size: 'footnote', tabular: true })] : []),
      ]),
    ]
    if (d.deny) section.push(txt(d.deny, toned('warn')))
    // A folded text (the task, the latest narrative): its opening words first; the toggle, a real button beside
    // the heading (its label a string, so every surface draws and presses it), shows the whole text as markdown
    // (paragraphs, bullets, code kept, wrapped by the surface), or as wrapped lines where Markdown is missing.
    // Which one is open lives in avState, so the pane's refreshes keep it open.
    const folded = (title, hint, key, f, stateKey, props = {}) => {
      const open = f.more && avState[stateKey] === id
      const head = [heading(title, hint)]
      if (f.more)
        head.push(
          Button({
            key,
            label: paneWord(lang, open ? 'task_less' : 'task_all'),
            dimColor: true,
            onPress: () => {
              avState[stateKey] = open ? undefined : id
              avRedraw($)
            },
          }),
        )
      let body = txt(f.short, props)
      if (open) body = typeof Markdown === 'function' && f.md ? Markdown({ key: key + '-full', text: f.md, ...(props.dimColor ? { dimColor: true } : {}) }) : col(f.full.split('\n').map((l) => txt(l, props)), { gap: 'xs' })
      return col([line(head, { justifyContent: 'space-between', flexWrap: 'wrap' }), body], { gap: 'xs' })
    }
    // What it is doing now: its latest narrative, above everything else it did.
    if (d.now) section.push(folded(t(lang, 'view_now'), t(lang, 'view_now_hint'), 'pane-now-' + id, d.now, 'nowOpenFor', { italic: true }))
    if (d.task) section.push(folded(t(lang, 'view_task'), t(lang, 'view_task_hint'), 'pane-task-' + id, d.task, 'taskOpenFor', { dimColor: true }))
    if (d.report) {
      const fold = reportFold(d.report, { open: avState.reportOpenFor === id })
      const paras = fold.shown.map((b) => {
        if (b.kind === 'heading') return txt(b.text, { weight: 'semibold' })
        if (b.kind === 'code') return txt(b.text, { mono: true, dimColor: true })
        if (b.kind === 'bullet') return b.numbered ? txt(b.text) : line([mute('•'), col([txt(b.text)], { flexShrink: 1, flexGrow: 1 })], { alignItems: 'flex-start' })
        return txt(b.text)
      })
      const box = [heading(t(lang, 'view_report'), t(lang, 'view_report_hint')), col(paras, { gap: 'xs' })]
      const folds = reportFold(d.report).hidden > 0
      if (folds) {
        const more = fold.hidden > 0
        box.push(
          linkButton('pane-more-report', more ? t(lang, 'view_report_more', { n: fold.hidden }) : t(lang, 'view_report_less'), () => {
            avState.reportOpenFor = more ? id : undefined
            avRedraw($)
          }),
        )
      }
      section.push(col(box, desktop ? { gap: 'xs', padding: 1, borderStyle: 'round', borderColor: CARD_LOOK.border, backgroundColor: CARD_LOOK.bg } : {}))
    }
    if (d.steps.length > 0) {
      const steps = [heading(t(lang, 'view_steps'), t(lang, 'view_steps_hint'))]
      const all = avState.stepsAllFor === id
      const rows = all ? d.steps : d.steps.slice(-VIEW_STEPS_SHOWN)
      const foldedRows = d.steps.length - rows.length
      if (d.hidden > 0 && all) steps.push(mute(t(lang, 'view_earlier', { n: d.hidden }), { size: 'footnote' }))
      if (foldedRows > 0 || (all && d.steps.length > VIEW_STEPS_SHOWN)) {
        steps.push(
          linkButton('pane-more-steps-' + id, foldedRows > 0 ? t(lang, 'view_steps_more', { n: foldedRows }) : t(lang, 'view_steps_less'), () => {
            avState.stepsAllFor = foldedRows > 0 ? id : undefined
            avRedraw($)
          }),
        )
      }
      const markOf = (st) => Text({ ...toned(st.tone), children: [st.pending ? '◌' : st.tone === 'crit' ? '✗' : '•'] })
      // One call's words: its label (a Bash call's own description) or else its argument, dim and mono.
      const callTop = (st, prefix) => {
        const top = prefix ? [prefix] : []
        if (st.label) top.push(one(st.label))
        if (st.arg) top.push(one(st.arg, { dimColor: true, mono: true, size: 'footnote' }))
        return top
      }
      // A step's first row: the tool (a short button when it opens), a dot, then its words in a box that may
      // shrink (minWidth 0), each cut at the pane's edge with an ellipsis. A Button's children are runs of one
      // line that no surface cuts, so only the tool, the count and the arrow sit in it.
      const stepHead = (lead, words) =>
        words.length === 0 ? line([lead]) : line([lead, mute('·', { size: 'footnote' }), Box({ flexDirection: 'row', alignItems: 'center', gap: 1, flexShrink: 1, minWidth: 0, overflow: 'hidden', children: words })], { minWidth: 0 })
      const summary = (st) => (st.summary ? [txt(st.summary, { ...(st.tone === 'ok' ? { dimColor: true } : toned(st.tone)), size: 'footnote' })] : [])
      const command = (st) => (st.command ? [txt(st.command, { dimColor: true, mono: true, size: 'footnote' })] : [])
      for (const st of rows) {
        const open = avState.stepsOpen.has(st.id)
        const toggle = () => {
          if (open) avState.stepsOpen.delete(st.id)
          else avState.stepsOpen.add(st.id)
          avRedraw($)
        }
        const toolName = one(st.tool, { weight: 'semibold' })
        let body
        if (st.kind === 'group') {
          // Calls of one tool in a row: the count and the newest; a press lists them all.
          const lastOne = st.items[st.items.length - 1]
          const head = Button({ key: 'pane-step-' + st.id, plain: true, onPress: toggle, children: [toolName, one(' ×' + st.items.length, { dimColor: true, size: 'footnote', tabular: true }), one(open ? ' ▾' : ' ▸', { dimColor: true })] })
          body = [stepHead(head, callTop(lastOne))]
          if (open) for (const it of st.items) body.push(col([stepHead(markOf(it), callTop(it)), ...summary(it), ...command(it)], { paddingLeft: 2, minWidth: 0 }))
          else body.push(...summary(lastOne))
        } else {
          // A Bash call drawn by its description: the command it ran, on a press.
          body = st.command ? [stepHead(Button({ key: 'pane-step-' + st.id, plain: true, onPress: toggle, children: [toolName, one(open ? ' ▾' : ' ▸', { dimColor: true })] }), callTop(st))] : [stepHead(toolName, callTop(st))]
          if (open) body.push(...command(st))
          body.push(...summary(st))
        }
        steps.push(line([markOf(st), col(body, { flexShrink: 1, flexGrow: 1, minWidth: 0 })], { alignItems: 'flex-start' }))
      }
      section.push(col(steps, { gap: 'xs' }))
    } else if (d.empty) section.push(mute(t(lang, 'view_empty')))
    children.push(col(section, { gap: 1, paddingTop: 1 }))
  }

  // The messages sent to the picked agent from here, oldest first, each a bubble: its text (four lines at most),
  // how long ago, and how far it got (sending, delivered, read, replied; a failure in red with its reason).
  // Drawn from memory: the refreshes moved them, nothing is read here.
  const bubbles = listed ? msgView(avState.paneSent.get(id), { now: avState.lastRefreshAt, lang }) : []
  if (bubbles.length > 0) {
    const rows = [heading(t(lang, 'view_msgs'), t(lang, 'view_msgs_hint'))]
    for (const b of bubbles) {
      const body = [txt(b.text), line([one(b.status, { ...toned(b.tone), size: 'footnote', weight: 'medium' }), ...(b.ago ? [one(b.ago, { dimColor: true, size: 'footnote' })] : [])], { justifyContent: 'space-between' })]
      if (b.reply) body.push(txt(b.reply, { dimColor: true, italic: true, size: 'footnote' }))
      const look = desktop ? { paddingX: 1, borderStyle: 'round', borderColor: b.tone === 'crit' ? 'error' : CARD_LOOK.border, backgroundColor: CARD_LOOK.bg } : { paddingLeft: 2 }
      rows.push(col(body, { key: 'msg-' + b.id, ...look }))
    }
    children.push(col(rows, { gap: 'xs', paddingTop: 1 }))
  }

  // A message to the picked agent (the Desktop app, where a hook knows the field is drawn): one field across the
  // pane, its own submit is the only send control. A finished agent is started again by it: the line under the
  // field and the submit's label ("Restart and send") say so, and that press is the yes; nothing is asked
  // elsewhere. An empty or too long message is said on one more line under it.
  if (listed && desktop && typeof Input === 'function') {
    const done = !avState.selectedLive
    const name = avBandName(id)
    const draft = avState.paneDrafts.get(id)
    const note = avState.paneNotes.get(id)
    const field = Input({
      key: 'pane-msg-' + id,
      // Short: the Desktop app sizes the field itself (no width prop, wrappers and flexGrow do not widen it), and
      // the heading above already names the agent.
      placeholder: paneWord(lang, 'msg_placeholder'),
      submitLabel: done ? sendPlan(true, lang).label : t(lang, 'view_msg_send'),
      ...(typeof draft === 'string' ? { value: draft } : {}),
      onInput: (value) => {
        avState.paneDrafts.set(id, typeof value === 'string' ? value : '')
        if (avState.paneNotes.delete(id)) avRedraw($)
      },
      onSubmit: (value) => avPaneSend($, id, value, done),
    })
    // Input is a leaf with no width prop: the field sits alone on its row, every box from the pane down to it
    // spans the full width and stretches its children. Seen live, the Desktop app still draws the field at its own
    // width with its submit beside it, so the placeholder is short enough for that width.
    const box = [
      heading(t(lang, 'view_msg_title', { name })),
      Box({ key: 'pane-msg-row-' + id, flexDirection: 'column', width: '100%', alignItems: 'stretch', children: [Box({ flexDirection: 'column', width: '100%', flexGrow: 1, alignItems: 'stretch', children: [field] })] }),
      txt(t(lang, done ? 'view_msg_note_done' : 'view_msg_note_live', { name }), { ...(done ? toned('warn') : { dimColor: true }), size: 'footnote' }),
    ]
    if (note) box.push(txt(note.text, { ...toned('crit'), size: 'footnote' }))
    children.push(col(box, { gap: 'xs', paddingTop: 1, width: '100%', alignItems: 'stretch' }))
  }
  return col(children, { gap: 1, paddingX: 1, alignItems: 'stretch' })
}

// ---- agents opened in the band -------------------------------------------------------------------

const avBandName = (id) => String(avState.band.cache.get(id)?.name ?? rowAgentFacts(id)?.name ?? 'agent').replace(/^.*:/, '') || 'agent'

// Reads each open agent that has something new (or was never read); a finished agent is read once and kept
// until it runs again. The band draws what is left here.
async function avBandRefresh($, now, lang) {
  const b = avState.band
  let rows = []
  try {
    rows = await rowTimeline($, 50)
  } catch (err) {
    rows = []
  }
  const byId = new Map(rows.map((r) => [r.id, r]))
  for (const id of [...b.open]) {
    const r = byId.get(id)
    const ended = avState.ended.get(id)
    const done = r !== undefined && r.status === 'done'
    const error = r?.failed === true || (ended !== undefined && (ended.reason === 'error' || ended.reason === 'refusal'))
    const prev = b.cache.get(id)
    const name = r?.name ?? rowAgentFacts(id)?.name ?? prev?.name
    const rowLine = r ? agentListLine({ ...r, status: error ? 'error' : r.status }, { now }) : prev?.rowLine
    if (prev && !prev.stale && prev.done === done) {
      b.cache.set(id, { ...prev, name, rowLine })
      continue
    }
    let found
    try {
      found = await $.session.messages({ agentId: id })
    } catch (err) {
      found = { deny: String(err && err.message ? err.message : err) }
    }
    const section = bandSection(
      {
        name,
        messages: Array.isArray(found) ? found : undefined,
        deny: Array.isArray(found) ? undefined : String(found?.deny ?? 'unknown'),
        answer: ended?.answer,
        done,
        error,
        // The host's own figure for a finished run; else what the mod saw of it.
        durationMs: typeof ended?.durationMs === 'number' ? ended.durationMs : r && typeof r.startMs === 'number' ? (typeof r.endMs === 'number' ? r.endMs : now) - r.startMs : undefined,
        tokens: r?.tokens,
        calls: progressStats(id)?.calls,
      },
      { lang },
    )
    b.cache.set(id, { section, done, name, rowLine, stale: false })
  }
}

// What the band needs to draw the open agents; no reads.
function avBandView() {
  const b = avState.band
  return { open: [...b.open], cache: b.cache, composing: b.composing, lang: avLang }
}

// A row of the band was pressed: open the agent under it, or close it (a person's act: read at once).
function avBandToggle($, id) {
  const b = avState.band
  const wasOpen = b.open.includes(id)
  b.open = toggleOpen(b.open, id)
  for (const k of [...b.cache.keys()]) if (!b.open.includes(k)) b.cache.delete(k)
  for (const k of [...b.composing]) if (!b.open.includes(k)) b.composing.delete(k)
  for (const k of [...b.drafts.keys()]) if (!b.open.includes(k)) b.drafts.delete(k)
  if (wasOpen) {
    try {
      $.ui.invalidate('ui.render')
    } catch (err) {
      // Nothing to redraw.
    }
    return
  }
  avRefresh($)
}

function avToast($, key, vars) {
  try {
    $.ui.toast(t(avLang, key, vars), { timeoutMs: 8000 })
  } catch (err) {
    // A toast is a courtesy.
  }
}

// The agent's whole transcript in the main view. Called first thing in a press: the host only allows it
// while it answers the person's own input.
function avBandFullView($, agentId) {
  let asked
  try {
    asked = $.ui.view(agentId === undefined ? {} : { agentId })
  } catch (err) {
    avToast($, 'band_view_deny', { reason: String(err && err.message ? err.message : err).slice(0, 120) })
    return
  }
  Promise.resolve(asked)
    .then((r) => {
      if (r && typeof r.deny === 'string') avToast($, 'band_view_deny', { reason: r.deny.slice(0, 120) })
    })
    .catch((err) => avToast($, 'band_view_deny', { reason: String(err && err.message ? err.message : err).slice(0, 120) }))
}

// The message field of one open agent: shown or hidden (its draft goes with it).
function avBandCompose($, id) {
  const b = avState.band
  if (b.composing.has(id)) {
    b.composing.delete(id)
    b.drafts.delete(id)
  } else b.composing.add(id)
  try {
    $.ui.invalidate('ui.render')
  } catch (err) {
    // Nothing to redraw.
  }
}

function avBandDraft(id, value) {
  if (avState.band.composing.has(id)) avState.band.drafts.set(id, typeof value === 'string' ? value : '')
}

function avBandDraftOf(id) {
  return avState.band.drafts.get(id)
}

// Sends what was typed to the agent ($.session.send). Never an empty message, never more than MESSAGE_MAX
// characters; a finished agent is started again by it, so the person says yes first (the safe answer, first,
// is not to send; no answer within AV_CONFIRM_MS is a no). The text is neither logged nor kept once sent.
async function avBandSend($, id, value, doneNow) {
  const name = avBandName(id)
  const check = checkMessage(value)
  if (!check.ok) {
    avToast($, check.error === 'empty' ? 'band_empty' : 'band_long', { max: MESSAGE_MAX })
    return
  }
  // The pane says whether its agent still runs; the band's own cache otherwise.
  const done = typeof doneNow === 'boolean' ? doneNow : avState.band.cache.get(id)?.done === true
  const plan = sendPlan(done, avLang)
  if (plan.confirm) {
    const no = t(avLang, 'band_confirm_no')
    const question = t(avLang, 'band_confirm_q', { name })
    if (uiAsking()) {
      avToast($, 'band_confirm_busy')
      return
    }
    // As askWithDeadline does: the surfaces read again when the start-up read gave none, and the dialog when the
    // band cannot ask (a surface it does not cover); a dismissed dialog is a no.
    await rowRefreshSurfaces($)
    const ask = uiAskStart($, question, [no, plan.label])
    let asked
    try {
      asked = ask !== undefined ? ask.promise : $.ui.ask(question, [no, plan.label])
    } catch (err) {
      asked = Promise.resolve(no)
    }
    Promise.resolve(asked).catch(() => {})
    let timer
    let answer
    try {
      answer = await Promise.race([
        Promise.resolve(asked).catch(() => no),
        new Promise((resolve) => {
          timer = $.clock.after(AV_CONFIRM_MS, () => resolve(no))
        }),
      ])
    } finally {
      try {
        if (timer) timer.cancel()
      } catch (err) {
        // Already fired.
      }
      if (ask !== undefined) ask.close()
    }
    if (answer !== plan.label) return
  }
  let sent
  try {
    sent = await $.session.send({ to: { agentId: id }, text: check.text })
  } catch (err) {
    sent = { isDelivered: false, reason: String(err && err.message ? err.message : err) }
  }
  if (sent && sent.isDelivered === true) {
    avState.band.drafts.delete(id)
    avState.band.composing.delete(id)
    avToast($, done ? 'band_sent_done' : 'band_sent', { name })
    avNote($, id)
  } else {
    avToast($, 'band_not_sent', { name, reason: String(sent?.reason ?? 'unknown').slice(0, 120) })
  }
  try {
    $.ui.invalidate('ui.render')
  } catch (err) {
    // Nothing to redraw.
  }
}

// The pane's send: the press on the field's own submit is the person's yes, also for a finished agent (its label
// says it restarts it), so no question is raised in the band. The message becomes a bubble at once (sending),
// then delivered or failed as the send answers; the refreshes move it on (avPaneTrack). The text lives in that
// bubble, in memory for the session alone: never logged, stored or sent anywhere else.
async function avPaneSend($, id, value, done) {
  const notes = avState.paneNotes
  avState.paneDrafts.set(id, typeof value === 'string' ? value : '') // a redraw keeps what was typed until it goes
  const check = checkMessage(value)
  if (!check.ok) {
    notes.set(id, { kind: 'error', text: t(avLang, check.error === 'empty' ? 'view_msg_empty' : 'view_msg_long', { max: MESSAGE_MAX }) })
    avRedraw($)
    return
  }
  notes.delete(id)
  let at
  try {
    at = await $.clock.now()
  } catch (err) {
    at = avState.lastRefreshAt
  }
  const key = 'm' + String(at) + '-' + String((avState.paneSent.get(id) ?? []).length)
  const bubble = { id: key, text: check.text, at, state: 'sending', restarted: done === true, callsAt: progressStats(id)?.calls ?? 0 }
  const set = (patch) => {
    const list = avState.paneSent.get(id) ?? []
    avState.paneSent.set(id, list.map((b) => (b.id === key ? { ...b, ...patch } : b)))
  }
  avState.paneSent.set(id, [...(avState.paneSent.get(id) ?? []), bubble].slice(-MSG_KEPT))
  avState.paneDrafts.set(id, '') // the field empties at once; a failure puts the text back
  avRedraw($)
  let sent
  try {
    sent = await $.session.send({ to: { agentId: id }, text: check.text })
  } catch (err) {
    sent = { isDelivered: false, reason: String(err && err.message ? err.message : err) }
  }
  if (sent && sent.isDelivered === true) {
    set({ state: 'delivered' })
    if (avState.selected === id) avState.detailStale = true
    avNote($, id)
  } else {
    set({ state: 'failed', reason: String(sent?.reason ?? 'unknown').slice(0, 120) })
    if (!avState.paneDrafts.get(id)) avState.paneDrafts.set(id, check.text)
  }
  avRedraw($)
}

async function avPaneOpen($) {
  try {
    const list = await $.ui.panes()
    return (Array.isArray(list) ? list : []).some((p) => p && p.id === AV_PANE_ID)
  } catch (err) {
    return false
  }
}

function registerAgentView(on) {
  on('command.run', { command: 'crew-agents' }, async ($, e) => {
    const word = String(e.args || '').trim().toLowerCase()
    // The same command again (or `close`) closes it: no second command to remember.
    if (word === 'close' || (await avPaneOpen($))) {
      try {
        await $.ui.close({ id: AV_PANE_ID })
      } catch (err) {
        // Not open.
      }
      avClosed()
      return { text: 'crew-agents: closed.' }
    }
    const opened = await avOpenPane($)
    if (!opened.ok) return { text: opened.deny === 'room' ? 'crew-agents: no room for the pane (' + opened.reason + ').' : 'crew-agents: the pane could not be opened (' + opened.reason + ').' }
    return { text: 'crew-agents: open. Click an agent to look inside; it refreshes while agents work. Esc, ctrl+x x or /crew-agents again closes it. Nothing it shows is stored.' }
  })
}

// Opens the agents pane (the command, or a press on a band row): { ok } or { ok: false, deny: 'room'|'error', reason }.
async function avOpenPane($) {
  avState.open = true
  avState.detailStale = true
  await avRefresh($) // the first drawing has its data
  let opened
  try {
    opened = await $.ui.open({ id: AV_PANE_ID, title: 'Agents', focus: true, closeOnEscape: true })
  } catch (err) {
    avClosed()
    return { ok: false, deny: 'error', reason: String(err && err.message ? err.message : err).slice(0, 120) }
  }
  if (opened && opened.isPlaced === false) {
    avClosed()
    return { ok: false, deny: 'room', reason: String(opened.reason ?? 'unknown') }
  }
  avStopTick()
  try {
    // The list's times move; a running agent's transcript is read again, a finished one's is not.
    avState.tick = $.clock.every(AV_TICK_MS, () => {
      // A running agent, or a message of the picked one not yet seen answered: its transcript is read again.
      const pending = msgPending(avState.paneSent.get(avState.selected))
      if (avState.selectedLive || pending) avState.detailStale = true
      // Nothing live in the list and nothing awaited: no time moves and nothing is read again, so the tick does
      // not redraw (an invalidate redraws the band above the prompt too). The agents' own events still refresh.
      const live = avState.snapshot === undefined || avState.selectedLive || pending || avState.snapshot.rows.some((r) => r.live)
      if (live) avNote($, undefined)
    })
  } catch (err) {
    // The agents' own events still refresh it.
  }
  return { ok: true }
}

// A band row was pressed (the user's pick, 2026-11-15): that agent's steps and report open in the side pane,
// not under the row. An open pane just switches to it.
async function avBandOpenPane($, id) {
  avState.selected = id
  avState.detailStale = true
  if (avState.open && (await avPaneOpen($))) {
    avRefresh($)
    return
  }
  const opened = await avOpenPane($)
  if (!opened.ok) avToast($, 'band_pane_deny', { reason: opened.reason.slice(0, 120) })
}

// Called from the mod's session.start: the command exists from the first moment.
async function avSessionStart($) {
  avReset()
  try {
    avLang = await resolveLang($) // the band draws its buttons in it before any refresh
  } catch (err) {
    avLang = 'en'
  }
  try {
    // immediate: the command also runs while a subagent works, which is when it is wanted.
    await $.command.register({ name: 'crew-agents', description: 'Look inside this session\'s subagents: what each did, its tool calls, its report', argumentHint: '[close]', immediate: true })
  } catch (err) {
    // The name is taken: the notices still work.
  }
}

// ===== crew-panes ============================================================
// crew-chief panes. Part of the mod in hooks/register.js (Claude Code 2.1.287+). Nothing here opens by itself:
// each pane opens when the person types its command.
//
//   /crew-panel tasks|agents|guard   a pane with the project's tasks.json, a timeline of this session's subagents,
//                                    or what the command guard stopped; /crew-panel close shuts them
//   /crew-guard log                  the guard pane too (the same toggle as /crew-panel guard)
//
// The panes are text lines laid out in hooks/panes-logic.mjs and refreshed every two seconds while one is open.
// On the Desktop app the guard pane is drawn as cards instead (guardView): a header with the guard's state and
// counts, one card per entry newest first, and a pressed card opens to its detail and what to check.
// A pane is closed with its mark, ctrl+x x, or the command; its timer stops with it. Any failure leaves the
// engine's own drawing.
const PANEL_IDS = { tasks: 'crew-tasks', agents: 'crew-agents', guard: 'crew-guard' }
const PANEL_ROWS = 12
const PANEL_REFRESH_MS = 2000

let panelTimer
const openPanels = new Set()
// What the guard pane draws from besides the guard's own log: the time of the last refresh, the language
// resolved when the pane was opened, the pressed entry. Kept here so drawing reads nothing.
let paneNow = 0
let paneLang = 'en'
let guardSelected
// pane id -> { e, sig }: what each pane drew last (the drawing's props, the content as a string), so the refresh
// timer redraws only when what a pane shows would change. Every redraw also redraws the band above the prompt.
const paneSeen = new Map()

function stopTimer(timer) {
  try {
    if (timer) timer.cancel()
  } catch (err) {
    // Already stopped.
  }
}

function panelsStop() {
  stopTimer(panelTimer)
  panelTimer = undefined
  openPanels.clear()
  paneSeen.clear()
  guardSelected = undefined
}

// Called when a session ends or a new one starts: timers do not outlive it.
function panesReset() {
  panelsStop()
}

function panelsStart($) {
  if (panelTimer) return
  panelTimer = $.clock.every(PANEL_REFRESH_MS, async () => {
    try {
      paneNow = await $.clock.now()
    } catch (err) {
      // The last time stands; the panes still redraw.
    }
    try {
      if (await panesChanged($)) $.ui.invalidate('ui.render')
    } catch (err) {
      // Nothing to redraw.
    }
  })
}

// What a pane shows, as a string: the same string, the same drawing.
async function paneSig($, e) {
  if (e.requestId === PANEL_IDS.guard && e.surface === 'desktop') return JSON.stringify(guardData())
  return JSON.stringify(await panelLines($, e))
}

// Whether an open pane would draw something else now (or has not been drawn yet).
async function panesChanged($) {
  for (const id of openPanels) {
    const seen = paneSeen.get(id)
    if (!seen) return true
    if ((await paneSig($, seen.e)) !== seen.sig) return true
  }
  return false
}

// Keeps what a pane drew, with the few props its content depends on.
function paneNote(e, content) {
  const props = { bodyColumns: e.props?.bodyColumns }
  paneSeen.set(e.requestId, { e: { requestId: e.requestId, surface: e.surface, props }, sig: JSON.stringify(content) })
}

// The ids of this plugin's panes the engine has open (its record, which survives a reload of the module).
async function openPaneIds($) {
  try {
    const list = await $.ui.panes()
    return (Array.isArray(list) ? list : []).map((pane) => pane && pane.id).filter((id) => typeof id === 'string')
  } catch (err) {
    return []
  }
}

const pad2 = (n) => String(n).padStart(2, '0')
const clockLabel = (ms) => {
  const d = new Date(ms)
  return pad2(d.getHours()) + ':' + pad2(d.getMinutes())
}

async function readTasks($) {
  const h = await findHandoff($)
  if (!h || !h.tasks) return undefined
  try {
    return await $.fs.read(h.tasks)
  } catch (err) {
    return undefined
  }
}

async function panelTree($, e) {
  const lines = await panelLines($, e)
  paneNote(e, lines)
  return uiLinesTree($, e, lines)
}

async function panelLines($, e) {
  const columns = typeof e.props?.bodyColumns === 'number' ? e.props.bodyColumns : 100
  const maxLines = PANEL_ROWS - 2
  let pane
  if (e.requestId === PANEL_IDS.tasks) {
    const text = await readTasks($)
    pane = text === undefined ? { header: [{ t: 'tasks ', tone: 'dim' }, { t: 'no tasks.json found for this project', tone: 'dim' }], lines: [] } : taskPane(text, { width: columns, maxLines })
    if (pane.error) pane = { header: [{ t: 'tasks ', tone: 'dim' }, { t: pane.error, tone: 'crit' }], lines: [] }
  } else if (e.requestId === PANEL_IDS.agents) {
    pane = timelinePane(await rowTimeline($), await $.clock.now(), { width: columns, barWidth: Math.max(10, Math.min(30, columns - 62)) })
  } else {
    pane = guardPane(guardLogList(), { width: columns, maxLines, clock: clockLabel })
  }
  const lines = [pane.header, ...pane.lines]
  if (pane.lines.length === 0) lines.push([{ t: e.requestId === PANEL_IDS.guard ? 'nothing stopped or warned yet this session' : 'nothing to show yet', tone: 'dim' }])
  return lines
}

function guardData() {
  return guardView(guardLogList(), { summary: guardSummary(), now: paneNow, selected: guardSelected, lang: paneLang })
}

// Theme keys for the tones guardView hands out: the cards take the person's theme, no fixed palette.
const GUARD_COLOR = { crit: 'error', warn: 'warning', info: 'suggestion', ok: 'success', dim: 'inactive' }

// A card was pressed: open it, or close it when it was open already (a person's act: redrawn at once).
function guardPick($, key) {
  guardSelected = guardSelected === key ? undefined : key
  try {
    $.ui.invalidate('ui.render')
  } catch (err) {
    // Drawn at the next refresh.
  }
}

// The guard pane on the Desktop app, from state only: the guard's log and summary, paneNow, paneLang.
function guardTree($, e) {
  const { Box, Button, Text } = $.ui.resolve(e)
  // Ink and mute are theme keys (they follow a light or dark theme); the card fill and frame are see-through greys.
  const L = { bg: CARD_LOOK.bg, border: CARD_LOOK.border, ink: 'text', mute: 'inactive' }
  const lang = paneLang
  const v = guardData()
  paneNote(e, v)
  const txt = (s, props = {}) => Text({ wrap: 'truncate-end', ...props, children: [s] })
  const para = (s, props = {}) => Text({ wrap: 'wrap', ...props, children: [s] })
  const small = (s, color, extra = {}) => txt(s, { color, size: 'footnote', ...extra })
  const chip = (children, borderColor) => Box({ flexDirection: 'row', alignItems: 'center', gap: 1, borderStyle: 'round', borderColor, paddingX: 1, flexShrink: 0, children })
  const spacer = () => Box({ flexGrow: 1, flexShrink: 1, minWidth: 0 })
  const stateColor = v.state === 'on' ? GUARD_COLOR.ok : v.state === 'off' ? GUARD_COLOR.dim : GUARD_COLOR.warn

  const header = Box({
    flexDirection: 'row',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: 1,
    children: [
      txt(v.title, { color: L.ink, weight: 'bold', size: 'heading' }),
      chip([txt('●', { color: stateColor }), small(v.stateLabel, L.ink, { weight: 'medium' })], L.border),
      spacer(),
      ...v.chips.map((c) => {
        const live = c.count > 0
        return chip([txt(c.glyph, { color: live ? GUARD_COLOR[c.tone] : L.mute }), txt(String(c.count), { color: live ? L.ink : L.mute, weight: 'bold', tabular: true }), small(c.label, L.mute)], live ? GUARD_COLOR[c.tone] : L.border)
      }),
    ],
  })

  const card = (r) => {
    const tone = GUARD_COLOR[r.tone]
    const top = Box({
      flexDirection: 'row',
      alignItems: 'center',
      gap: 1,
      minWidth: 0,
      children: [
        Button({ key: r.key, plain: true, label: r.label, onPress: () => guardPick($, r.key), children: [Text({ color: tone, weight: 'bold', children: [r.glyph + ' '] }), Text({ color: L.ink, weight: 'semibold', wrap: 'truncate-end', children: [r.label] })] }),
        spacer(),
        small(r.ago, L.mute, { tabular: true }),
      ],
    })
    const meta = [small(r.level, tone, { weight: 'medium' })]
    if (r.rule) meta.push(small(t(lang, 'gp_rule'), L.mute), small(r.rule, L.ink, { mono: true }))
    if (r.hosts) meta.push(small(t(lang, 'gp_host'), L.mute), small(r.hosts.join(', '), L.ink, { mono: true }))
    if (r.readOnly) meta.push(small(t(lang, 'gp_readonly'), L.mute))
    const children = [top, Box({ flexDirection: 'row', alignItems: 'center', flexWrap: 'wrap', gap: 1, minWidth: 0, children: meta })]
    if (r.detail) {
      children.push(
        Box({
          flexDirection: 'column',
          marginTop: 1,
          gap: 1,
          children: [
            para(r.detail.text, { color: L.ink, mono: true, size: 'footnote' }),
            txt(t(lang, 'gp_check_title'), { color: L.mute, size: 'caption', weight: 'semibold' }),
            ...r.detail.checks.map((c) => para('› ' + c, { color: L.ink, size: 'footnote' })),
          ],
        }),
      )
    }
    return Box({ key: 'card-' + r.key, flexDirection: 'column', borderStyle: 'round', borderColor: r.selected ? tone : L.border, backgroundColor: L.bg, paddingX: 1, hover: { borderColor: tone }, children })
  }

  const children = [header]
  if (v.hint) children.push(txt(v.hint, { color: L.mute, size: 'caption' }))
  if (v.empty) children.push(Box({ flexDirection: 'row', alignItems: 'center', gap: 1, borderStyle: 'round', borderColor: L.border, backgroundColor: L.bg, paddingX: 1, paddingY: 1, children: [txt('●', { color: stateColor }), para(v.empty, { color: L.ink })] }))
  for (const r of v.rows) children.push(card(r))
  if (v.moreLabel) children.push(small(v.moreLabel, L.mute))
  const f = v.footer
  children.push(Box({ flexDirection: 'row', alignItems: 'center', flexWrap: 'wrap', gap: 1, marginTop: 1, children: [small(f.command, L.ink, { mono: true }), small(f.label, L.mute), small('·', L.mute), small(t(lang, 'gp_config'), L.mute), small(f.path, L.mute, { mono: true })] }))
  return Box({ flexDirection: 'column', gap: 1, children })
}

function registerPanes(on) {
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    try {
      // The agent view of /crew-agents (hooks/src/agent-view.js) draws in this same hook.
      if (e.requestId === AV_PANE_ID) return avTree($, e)
      if (!Object.values(PANEL_IDS).includes(e.requestId)) return next(e)
      if (e.requestId === PANEL_IDS.guard && e.surface === 'desktop') return guardTree($, e)
      return await panelTree($, e)
    } catch (err) {
      return next(e)
    }
  })

  // Closed by the person (the mark, ctrl+x x) or by a command: the refresh timer goes when none is left.
  on('ui.close', async ($, e, next) => {
    try {
      if (e.id === AV_PANE_ID) avClosed()
      if (Object.values(PANEL_IDS).includes(e.id)) {
        openPanels.delete(e.id)
        paneSeen.delete(e.id)
        if (openPanels.size === 0) {
          stopTimer(panelTimer)
          panelTimer = undefined
        }
      }
    } catch (err) {
      // The pane closes either way.
    }
    return next(e)
  })

  on('command.run', { command: 'crew-panel' }, async ($, e) => {
    const word = String(e.args || '').trim().toLowerCase()
    if (word === 'close') {
      // Every pane of ours the engine has open, whatever this module remembers (it may have been reloaded).
      const ids = new Set([...Object.values(PANEL_IDS), ...(await openPaneIds($)).filter((id) => id.startsWith('crew-'))])
      for (const id of ids) {
        try {
          await $.ui.close({ id })
        } catch (err) {
          // Not open.
        }
      }
      panelsStop()
      avClosed()
      return { text: 'crew-panel: closed.' }
    }
    return panelToggle($, word)
  })

  // /crew-guard log opens the guard pane; every other /crew-guard word goes on to the guard (hooks/src/guard.js).
  on('command.run', { command: 'crew-guard' }, async ($, e, next) => {
    if (String(e.args || '').trim().toLowerCase() !== 'log') return next(e)
    return panelToggle($, 'guard')
  })
}

// /crew-panel <word> and /crew-guard log: open the pane, or close it when it is open already.
async function panelToggle($, word) {
  const id = PANEL_IDS[word]
  // The same command again closes its pane: no second command to remember.
  if (id !== undefined && (await openPaneIds($)).includes(id)) {
    try {
      await $.ui.close({ id })
    } catch (err) {
      // Gone already.
    }
    openPanels.delete(id)
    paneSeen.delete(id)
    if (openPanels.size === 0) panelsStop()
    return { text: `crew-panel: ${word} pane closed.` }
  }
  if (id === undefined) return { text: 'crew-panel: tasks (tasks.json of this project) | agents (a timeline of this session\'s subagents) | guard (what the command guard stopped) | close.' }
  // Read now, not while drawing: the guard pane's clock and language.
  try {
    paneNow = await $.clock.now()
    paneLang = await resolveLang($)
  } catch (err) {
    // The last ones stand.
  }
  let opened
  try {
    opened = await $.ui.open({ id, title: word[0].toUpperCase() + word.slice(1), focus: true, closeOnEscape: true, rows: PANEL_ROWS })
  } catch (err) {
    return { text: 'crew-panel: the pane could not be opened (' + String(err && err.message ? err.message : err).slice(0, 120) + ').' }
  }
  if (opened && opened.isPlaced === false) return { text: 'crew-panel: no room for the pane (' + String(opened.reason ?? 'unknown') + ').' }
  openPanels.add(id)
  panelsStart($)
  return { text: `crew-panel: ${word} pane open (refreshes every 2 s; Esc or ctrl+x x closes it).` }
}

// Called from the mod's session.start: the commands exist from the first moment.
async function panesSessionStart($) {
  panesReset()
  for (const [name, description, argumentHint] of [
    ['crew-panel', 'Open a pane: tasks, agents, guard', '[tasks|agents|guard|close]'],
  ]) {
    try {
      // immediate: the command also runs while a subagent works, which is when the agents pane is wanted.
      await $.command.register({ name, description, argumentHint, immediate: true })
    } catch (err) {
      // The name is taken: the other commands still work.
    }
  }
}

// ===== overlap ===============================================================
// A note, never a block, when an Agent call for a writing agent (implementer, implementer-hard, mechanic, ui-implementer) names
// files that another running writer's brief also named: parallel edits to one file collide, and the routing
// skill says to give parallel implementers disjoint file sets. The model sees the note with the call's result
// and decides; nothing is stopped. Briefs are free text, so the files are found by shape (hooks/overlap-logic.mjs).
let writers = [] // { paths, who } of the writing agents started in this stretch of the session

function overlapReset() {
  writers = []
}

async function overlapObserve($, e) {
  try {
    if (e.tool !== 'Agent' || !isWriterType(e.subagent_type)) return undefined
    const list = await $.agent.list()
    const running = Array.isArray(list) ? list.filter((a) => a.status === 'pending' || a.status === 'running').length : 0
    if (running === 0) writers = [] // nothing else is running, so nothing can collide
    const paths = briefPaths(e.prompt)
    const who = String(e.subagent_type).replace(/^.*:/, '')
    let note
    for (const w of writers) {
      const hit = overlapping(paths, w.paths)
      if (hit.length > 0) {
        note = `crew-chief: this brief names the same file(s) as a ${w.who} you started earlier and that may still be running: ${hit.slice(0, 4).join(', ')}. Two agents editing one file at once collide. Wait for it to finish, or give each agent its own files.`
        break
      }
    }
    if (paths.length > 0) writers.push({ paths, who })
    return note
  } catch (err) {
    return undefined
  }
}

// ===== handoff-offer =========================================================
// The handoff setup offer at a fresh session start. Part of the mod in hooks/register.js. The rules are in
// hooks/handoff-offer-logic.mjs; the shell's text line (scripts/session-policy.sh) is the fallback and stays
// quiet while this mod is loaded (the marker file below).
//
//   - every session.start where the mod is loaded writes the marker `mod-offer-active` (a unix time) into the
//     plugin's data folder, before anything else, so the shell does not also print its offer;
//   - on a fresh startup (no prompt sent yet, a person at the prompt) it asks: Set up / Later / Never (a
//     folder with no git: git init then set up / Set up without git / Later / Never). Same record file and
//     same suppression rules as the shell. The question has a deadline: unanswered counts as Later;
//   - Set up submits one prompt that runs the crew-chief:crew-handoff skill; the user already said yes.
// The question runs detached: it never holds up the session start or the person's first prompt.
const HO_STORE_PREFIX = 'handoff-offer:'
const HO_SURFACE_POLLS = 5
const HO_SURFACE_POLL_MS = 2000
// The model is told once, with the first prompt (prompt.submit's `context`), to ignore the shell's offer text: the shell
// may have printed it before the marker existed, and this mod asks in a dialog instead.
const HO_IGNORE_SHELL_NOTE =
  'crew-chief already asked the user about handoff files in a dialog in this session: ignore any <crew-chief-handoff-offer> instruction (do not add the closing line and do not record anything).'
let hoIgnoreShell = false

// The note for the next prompt, once; undefined when the mod is not asking in this session.
function handoffOfferNote() {
  if (!hoIgnoreShell) return undefined
  hoIgnoreShell = false
  return HO_IGNORE_SHELL_NOTE
}

const HO_KEYS = ['ho_setup', 'ho_git_setup', 'ho_nogit_setup', 'ho_later', 'ho_never']

async function hoTry(fn, fallback) {
  try {
    return await fn()
  } catch (err) {
    return fallback
  }
}

// The plugin's data folder: where the shell keeps handoff-offers.tsv. undefined when it cannot be worked out.
async function hoDataDir($) {
  const env = await hoTry(() => $.env.get('CLAUDE_PLUGIN_DATA'), undefined)
  const home = await hoTry(() => $.env.get('HOME'), undefined)
  const configDir = await hoTry(() => $.env.get('CLAUDE_CONFIG_DIR'), undefined)
  const found = resolveDataDir({ env, pluginRoot: $.plugin.root, pluginName: $.plugin.name, home, configDir })
  await hoTry(() => $.ui.log('crew-chief: handoff offer data folder ' + (found ? `${found.dir} (${found.source})` : 'unknown, the mod stays out of it'), { to: 'debug' }), undefined)
  return found === undefined ? undefined : found.dir
}

// First thing at session.start: the marker the shell reads. Never throws.
async function handoffOfferMarker($) {
  hoIgnoreShell = false
  try {
    // Switched off: the shell offers nothing either (it reads the same variable), so there is nothing to keep quiet.
    if ((await hoTry(() => $.env.get('CREW_CHIEF_HANDOFF_OFFER'), undefined)) === 'off') return
    const dir = await hoDataDir($)
    if (dir === undefined) return
    const sec = Math.floor((await $.clock.now()) / 1000)
    await $.fs.write(`${dir}/${MARKER_FILE}`, `${sec}\n`)
  } catch (err) {
    // The shell's line then offers as before.
  }
}

// After the session is bound: the offer itself, detached.
function handoffOfferStart($, e) {
  void handoffOfferRun($, e).catch(() => {})
}

async function hoInteractive($, e) {
  if (e && e.isInteractive === true) return true
  // A host that draws later (the Desktop app attaches after the start) is given a few seconds to show up.
  for (let i = 0; i < HO_SURFACE_POLLS; i++) {
    const surfaces = await hoTry(() => $.session.surfaces(), [])
    if (Array.isArray(surfaces) && surfaces.length > 0) return true
    await new Promise((resolve) => {
      $.clock.after(HO_SURFACE_POLL_MS, resolve)
    })
  }
  return false
}

async function hoGitRoot($, cwd) {
  const r = await hoTry(() => $.process.run(['git', '-C', cwd, 'rev-parse', '--show-toplevel'], { timeoutMs: 3000 }), undefined)
  if (!r || r.exitCode !== 0) return undefined
  const top = String(r.stdout ?? '').trim()
  return top === '' ? undefined : top
}

// Handoff-like files at the root or one folder below (the shell's search).
async function hoHasHandoffFiles($, proj) {
  const entries = await hoTry(() => $.fs.list(proj), [])
  for (const entry of Array.isArray(entries) ? entries : []) {
    if (entry && entry.kind !== 'dir' && isHandoffName(entry.name)) return true
  }
  for (const name of subdirsToSearch(entries)) {
    const inner = await hoTry(() => $.fs.list(`${proj}/${name}`), [])
    for (const entry of Array.isArray(inner) ? inner : []) {
      if (entry && entry.kind !== 'dir' && isHandoffName(entry.name)) return true
    }
  }
  return false
}

async function hoRecordAnswer($, dir, proj, answer) {
  const file = `${dir}/${OFFERS_FILE}`
  const sec = Math.floor((await $.clock.now()) / 1000)
  let existing = ''
  if (await hoTry(() => $.fs.exists(file), false)) {
    // A file that is there but cannot be read is left alone: writing would erase every other project's record.
    existing = await $.fs.read(file)
  }
  await $.fs.write(file, appendRecord(existing, recordLine(proj, answer, sec)))
}

async function handoffOfferRun($, e) {
  if ((await hoTry(() => $.env.get('CREW_CHIEF_HANDOFF_OFFER'), undefined)) === 'off') return
  const cwd = e && typeof e.cwd === 'string' ? e.cwd : await hoTry(() => $.session.cwd(), undefined)
  if (!cwd) return
  // Only a fresh startup: a resumed or forked session already has prompts. (session.start carries no `source`.)
  if ((await hoTry(() => $.session.turns(), 1)) !== 0) return
  const sid = await hoTry(() => $.session.id(), undefined)
  const storeKey = sid ? HO_STORE_PREFIX + sid : undefined
  // A reload of the mod runs session.start again for the same session: ask once per session.
  if (storeKey && (await hoTry(() => $.store.get(storeKey), undefined)) !== undefined) return
  const dir = await hoDataDir($)
  if (dir === undefined) return
  const home = await hoTry(() => $.env.get('HOME'), undefined)

  let proj = await hoGitRoot($, cwd)
  const hasGit = proj !== undefined
  if (!hasGit) {
    const names = (await hoTry(() => $.fs.list(cwd), [])).map((x) => x.name)
    if (!isProjectFolder(cwd, home, names)) return
    proj = cwd
  }
  if (skipRoot(proj, home)) return
  if (await hoHasHandoffFiles($, proj)) return
  const claudeMd = await hoTry(() => $.fs.read(`${proj}/CLAUDE.md`), '')
  if (hasHandoffBlock(claudeMd)) return
  const tsv = (await hoTry(() => $.fs.exists(`${dir}/${OFFERS_FILE}`), false)) ? await hoTry(() => $.fs.read(`${dir}/${OFFERS_FILE}`), '') : ''
  const nowSec = Math.floor((await $.clock.now()) / 1000)
  if (recordSilences(lastRecord(tsv, proj), nowSec)) return

  if (!(await hoInteractive($, e))) return
  // A night is open: nobody is there to answer, and "later" must not be recorded for them.
  const night = await hoTry(() => nightQuietNow($), undefined)
  if (night) return void (await hoTry(() => nightSkipped($, night, 'the handoff setup offer'), undefined))
  // The person may have typed already while the checks ran.
  if ((await hoTry(() => $.session.turns(), 1)) !== 0) return
  if (storeKey) await hoTry(() => $.store.set(storeKey, '1'), undefined)
  hoIgnoreShell = true

  const lang = await resolveLang($)
  const messages = Object.fromEntries(HO_KEYS.map((k) => [k, t(lang, k)]))
  const answers = answerLabels(messages, hasGit)
  const question = t(lang, hasGit ? 'ho_ask_git' : 'ho_ask_nogit')
  let picked
  try {
    picked = await askWithDeadline($, question, answers, messages.ho_later)
  } catch (err) {
    picked = messages.ho_later // dismissed
  }
  const kind = answerKind(messages, hasGit, picked)
  if (kind === 'later' || kind === 'never') {
    await hoTry(() => hoRecordAnswer($, dir, proj, kind), undefined)
    await hoTry(() => $.ui.toast(t(lang, kind === 'never' ? 'ho_toast_never' : 'ho_toast_later'), { timeoutMs: 8000 }), undefined)
    return
  }
  await $.prompt.submit({ text: setupPrompt(kind, cwd) })
}

// ===== register ==============================================================
// crew-chief saver mod: watches your plan limits and asks whether to turn on a token saver.
//
// What it does (Claude Code 2.1.287 or later; older versions never load this file):
//   - When the 5-hour window crosses 70/80/90 % or the weekly window 50/75/85/90 %, asks once per
//     threshold and window whether to turn the saver on for THIS session. A new session, /clear,
//     and /resume always start with the saver off.
//   - While the saver is on, subagent requests are capped: Opus (and Fable) at medium effort,
//     Sonnet at high (no xhigh or max). Haiku and the main session are never touched.
//   - One toast when the session is 8 hours old.
//   - The compact flow (hooks/compact-flow.mjs): at a phase boundary past 250k tokens it proposes a compaction,
//     asks first, has the handoff files updated, and compacts with a detailed brief so nothing is lost.
//   - /saver [on|off|status]
//   - One status line with every running subagent's model, effort and tokens (hooks/src/agent-row.js), for
//     the Desktop app, VS Code and terminals where the shell panel row cannot draw. CREW_CHIEF_ROW_MOD.
//   - Every question the mod asks has a deadline (hooks/src/ask.js): unanswered after
//     CREW_CHIEF_ASK_TIMEOUT_MIN minutes (default 20), it counts as "not now" / "no" / "cancel".
//   - Once, after the first finished turn of a session where the advisor is off: offers to turn on
//     /advisor (a stronger model Claude can ask at hard moments). It asks first, remembers "not now"
//     for a week and "never" for good, and runs /advisor only after a yes.
//   - An opt-in command guard (hooks/src/guard.js): built-in and personal deny/warn rules and an ssh
//     "first contact" gate for production hosts, configured in ~/.claude/crew-chief-guard.json (written with defaults on the first interactive run). CREW_CHIEF_GUARD, CREW_CHIEF_GUARD_AUTOSETUP.
//     A first attempt at a "confirm" command is stopped with a checklist; the identical retry passes.
//     /crew-guard [status|suggestions|on|off]; the tool crew_guard_suggest lets Claude flag what the config misses.
// Environment: CREW_CHIEF_SAVER=off silences the saver questions and toasts (not the advisor offer);
// CREW_CHIEF_SAVER_FIVE_HOUR and CREW_CHIEF_SAVER_SEVEN_DAY set the thresholds ("70,80,90");
// CREW_CHIEF_ADVISOR_OFFER=off never offers the advisor; CREW_CHIEF_COMPACT=off turns the compact flow off;
// CREW_CHIEF_LANG=tr|en forces the language of the messages (otherwise: Claude Code's `language`
// setting, then what you have been writing, then the last language seen, then the locale).
// Kept between sessions, in the plugin's store: the language ("tr" or "en") and the answer to the
// advisor offer ("never", "answered", or "later:<time>"). Nothing leaves the machine.
const TURN_STALE_MS = 10 * 60 * 1000
const STEP_STALE_MS = 5 * 60 * 1000

// Per-session state; resetState() puts it back when the session ends, /clear, or /resume.
let saver = false
let ultra = false // a mode of the saver: subagents stay off Opus (hooks/saver-logic.mjs ultraAgentCall)
let ultraOpus = false // the person's standing yes to Opus for the session (/saver ultra opus on)
let ultraToasted = false
let pending = null
let lastPromptAt = 0
let lastCompleteAt = 0
let lastStepAt = 0
let registered = false
let quiet = false
let ageToasted = false
let capToasted = false
let advisorChecked = false
// The saver question's memory ("don't ask again", thresholds already asked), mirrored in the plugin store
// per session id so a module reload, with or without a new session.start, keeps it (askLoad / askSave).
let asks = askStateNew()
let askSid // the session id `asks` is stored under; undefined: not looked up (or no store)
let askLoading = null

function resetState() {
  overlapReset()
  handoffReset()
  saver = false
  ultra = false
  ultraOpus = false
  ultraToasted = false
  open.saver = false
  pending = null
  lastPromptAt = 0
  lastCompleteAt = 0
  lastStepAt = 0
  registered = false
  quiet = false
  ageToasted = false
  capToasted = false
  advisorChecked = false
  resetLang()
  resetResetFlow()
  statsReset()
  progressReset()
  asks = askStateNew()
  askSid = undefined
  askLoading = null
}

async function readConfig($) {
  // saver.ask, saver.five and saver.seven: /crew-config, or the environment variables of the same meaning.
  const off = (await cfgGet($, 'saver.ask')) === 'off'
  const five = await cfgGet($, 'saver.five')
  const week = await cfgGet($, 'saver.seven')
  return { off, five, week }
}

// Brings back this session's saver-question memory after a module reload, and drops other sessions' stale
// copies. Once per module life (and again after resetState); any failure keeps the memory in this module only.
function askLoad($) {
  askLoading ??= (async () => {
    try {
      const sid = await $.session.id()
      if (typeof sid !== 'string' || sid === '') return
      const stored = await $.store.get(ASK_STORE_PREFIX + sid)
      const back = askStateRestore(stored)
      // Kept from both: an answer given while the load was under way is not lost.
      asks = { never: asks.never || back.never, windows: { ...back.windows, ...asks.windows } }
      askSid = sid
      const now = await $.clock.now()
      for (const k of await $.store.keys()) {
        if (k.startsWith(ASK_STORE_PREFIX) && k !== ASK_STORE_PREFIX + sid && askStateStale(await $.store.get(k), now)) await $.store.delete(k)
      }
    } catch (err) {
      // No session id or no store: remembered for this module's lifetime only.
    }
  })()
  return askLoading
}

async function askSave($) {
  await askLoad($)
  if (askSid === undefined) return
  try {
    await $.store.set(ASK_STORE_PREFIX + askSid, { ...asks, savedAt: await $.clock.now() })
  } catch (err) {
    // Remembered for this module's lifetime only.
  }
}

async function askNever($, value) {
  await askLoad($)
  asks.never = value
  await askSave($)
}

// The window that most needs a question, or undefined (hooks/saver-logic.mjs askHit).
async function findHit($, rateLimits, cfg) {
  await askLoad($)
  const { hit, changed } = askHit(asks, rateLimits, { five_hour: cfg.five, seven_day: cfg.week })
  if (changed) await askSave($)
  return hit
}

async function ageNotice($, usage) {
  const now = await $.clock.now()
  if (!ageToasted && typeof usage.startedAt === 'number' && now - usage.startedAt >= SESSION_AGE_TOAST_MS) {
    ageToasted = true
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'toast_age', { duration: formatDuration(now - usage.startedAt, unitsFor(lang)) }), { timeoutMs: 12000 })
  }
}

async function askUser($, hit) {
  open.saver = true
  try {
    const lang = await resolveLang($)
    // The ultra-saver is offered here and nowhere else on its own; unanswered counts as "not now", never as a yes.
    const answers = [t(lang, 'answer_on'), t(lang, 'answer_ultra'), t(lang, 'answer_not_now'), t(lang, 'answer_never')]
    const now = await $.clock.now()
    const left = hit.resetsAt ? Date.parse(hit.resetsAt) - now : 0
    const duration = left > 0 ? formatDuration(left, unitsFor(lang)) : ''
    const reset = duration !== '' ? t(lang, 'reset_in', { duration }) : ''
    // On Desktop the question is the quiet card (as the compact one): a topic, one short line, the window and its
    // reset as chips, what each mode does in one line, short labels on the same answers.
    const card = {
      kind: 'card',
      topic: t(lang, 'saver_topic'),
      question: t(lang, 'saver_question'),
      facts: [
        t(lang, hit.kind === 'five_hour' ? 'saver_fact_five' : hit.kind === 'seven_day' ? 'saver_fact_week' : 'percent', { percent: hit.percent, n: hit.percent }),
        duration !== '' ? t(lang, 'saver_fact_reset', { duration }) : '',
      ].filter((f) => f !== ''),
      note: t(lang, 'saver_note'),
      labels: [t(lang, 'saver_label_on'), t(lang, 'saver_label_ultra'), t(lang, 'saver_label_not_now'), t(lang, 'saver_label_never')],
      accent: 1, // the ultra answer's text in the saver's ultra colour
      quiet: 3, // "don't ask again": a quiet text button at the end
    }
    // At night (hooks/src/night.js): the plain saver, never ultra (the user's rule).
    const answer = await askWithDeadline($, t(lang, 'ask', { window: windowName(lang, hit.kind), percent: hit.percent, reset }), answers, answers[2], card, { answer: answers[0] })
    if (answer === answers[0]) {
      saver = true
      $.ui.toast(t(lang, 'toast_saver_on'), { timeoutMs: 8000 })
    } else if (answer === answers[1]) {
      saver = true
      ultra = true
      $.ui.toast(t(lang, 'toast_ultra_on'), { timeoutMs: 8000 })
    } else if (answer === answers[3]) {
      await askNever($, true)
    }
  } catch (err) {
    // Dismissed, or a run with nobody to ask: treat it as "not now".
  } finally {
    open.saver = false
  }
}

// Ultra-saver: a call asks for the strongest model. Asks the person; no answer, a dismissed dialog or another
// question being open all mean no (the call then runs on Sonnet at high).
async function askOpus($, e) {
  if (open.saver || open.compact || open.reset) return false
  open.saver = true
  try {
    const lang = await resolveLang($)
    const answers = [t(lang, 'ultra_yes'), t(lang, 'ultra_no')]
    const agent = typeof e.subagent_type === 'string' && e.subagent_type !== '' ? e.subagent_type : 'an agent'
    const why = t(lang, typeof e.model === 'string' && e.model !== '' ? 'ultra_why_named' : 'ultra_why_xhigh')
    const answer = await askWithDeadline($, t(lang, 'ultra_ask_opus', { agent, why }), answers, answers[1])
    return answer === answers[0]
  } catch (err) {
    return false
  } finally {
    open.saver = false
  }
}

// Not awaited on purpose: the hook that calls this must not wait for the person to answer.
function launchAsk($) {
  const hit = pending
  if (hit !== null && !open.saver && !open.compact && !open.reset) {
    pending = null
    askUser($, hit)
  }
}

async function evaluate($) {
  const cfg = await readConfig($)
  quiet = cfg.off
  if (cfg.off) return
  const usage = await $.session.usage()
  await ageNotice($, usage)
  await askLoad($)
  if (saver || asks.never || open.saver) return
  const hit = await findHit($, usage.rateLimits, cfg)
  if (hit !== undefined) pending = hit
}

async function onCloudProvider($) {
  // The advisor is a server tool of the Anthropic API; these routes do not have it.
  const flags = [
    await $.env.get('CLAUDE_CODE_USE_BEDROCK'),
    await $.env.get('CLAUDE_CODE_USE_VERTEX'),
    await $.env.get('CLAUDE_CODE_USE_FOUNDRY'),
    await $.env.get('CLAUDE_CODE_USE_ANTHROPIC_AWS'),
    await $.env.get('CLAUDE_CODE_USE_ANTHROPIC_GOOGLE_CLOUD'),
  ]
  return flags.some(isEnvFlag)
}

async function rememberAdvisorAnswer($, value) {
  try {
    await $.store.set('advisor', value)
  } catch (err) {
    // Not remembered: the offer may come back next session.
  }
}

// The command writes the setting a moment after it returns, so look a few times before giving up.
async function advisorIsSet($) {
  for (let attempt = 0; attempt < 5; attempt++) {
    const settings = await $.settings.read()
    if (settings.advisorModel) return true
    if (attempt < 4) await $.clock.sleep(400)
  }
  return false
}

// Runs outside the hook that scheduled it (a hook the turn waits on may not run commands). Only a
// result that is visible in the settings counts as "answered"; a refusal (a policy, Fable credits)
// is remembered as "never" so the offer does not repeat a command that cannot work.
async function enableAdvisor($, advisor, lang) {
  try {
    await $.command.run({ command: 'advisor', args: advisor })
    if (!(await advisorIsSet($))) throw new Error('the advisor setting did not change')
    await rememberAdvisorAnswer($, 'answered')
    $.ui.toast(t(lang, 'advisor_toast_on', { advisor: t(lang, 'model_' + advisor) }), { timeoutMs: 8000 })
  } catch (err) {
    await rememberAdvisorAnswer($, 'never')
    $.ui.toast(t(lang, 'advisor_toast_failed'), { timeoutMs: 12000 })
  }
}

// Offers the advisor once. Every gate that says "not for this person or this setup" returns
// quietly; a dismissed dialog (or a run with nobody to ask) leaves no trace, so it can come back.
async function offerAdvisor($) {
  if (open.saver || open.compact || open.reset) return
  open.saver = true
  try {
    if ((await $.env.get('CREW_CHIEF_ADVISOR_OFFER')) === 'off') return
    if (isEnvFlag(await $.env.get('CLAUDE_CODE_DISABLE_ADVISOR_TOOL'))) return
    if (await onCloudProvider($)) return
    const settings = await $.settings.read()
    if (settings.advisorModel) return
    const commands = await $.command.list()
    if (!commands.some((c) => c.name === 'advisor')) return
    const plan = advisorPlan(await $.session.model())
    if (plan === undefined) return
    const night = await nightQuietNow($)
    if (night) return void (await nightSkipped($, night, 'the advisor offer'))
    let stored
    try {
      stored = await $.store.get('advisor')
    } catch (err) {
      // No store: treated as never asked.
    }
    const now = await $.clock.now()
    if (!advisorOfferAllowed(stored, now)) return
    const lang = await resolveLang($)
    const answers = [t(lang, 'advisor_answer_on'), t(lang, 'advisor_answer_later'), t(lang, 'advisor_answer_never')]
    const main = t(lang, 'model_' + plan.family)
    const advisor = t(lang, 'model_' + plan.advisor)
    let answer
    try {
      // Unanswered: "remind me in a week", the same as clicking it.
      answer = await askWithDeadline($, t(lang, plan.kind === 'second' ? 'advisor_ask_second' : 'advisor_ask_standard', { main, advisor }), answers, answers[1])
    } catch (err) {
      return
    }
    if (answer === answers[0]) {
      $.clock.after(300, () => enableAdvisor($, plan.advisor, lang))
    } else if (answer === answers[1]) {
      await rememberAdvisorAnswer($, 'later:' + (now + ADVISOR_LATER_MS))
    } else if (answer === answers[2]) {
      await rememberAdvisorAnswer($, 'never')
    }
  } catch (err) {
    // Anything unexpected: stay quiet rather than get in the way.
  } finally {
    open.saver = false
  }
}

// A main-thread turn is running when a prompt or a model request went out after the last finished
// turn. Model requests count too: a prompt queued while the previous turn ran, a turn longer than
// TURN_STALE_MS, and a turn started by a background notification never pass through prompt.submit
// at the right time. Both marks go stale so a lost turn.complete cannot block questions for good.
async function turnInFlight($) {
  const now = await $.clock.now()
  const byPrompt = lastPromptAt > lastCompleteAt && now - lastPromptAt < TURN_STALE_MS
  const byStep = lastStepAt > lastCompleteAt && now - lastStepAt < STEP_STALE_MS
  return byPrompt || byStep
}

async function statusText($) {
  await askLoad($)
  const lang = await resolveLang($)
  const units = unitsFor(lang)
  const usage = await $.session.usage()
  const now = await $.clock.now()
  const parts = [t(lang, saver ? 'status_on' : 'status_off') + (ultra ? t(lang, 'status_ultra') : '') + (asks.never ? t(lang, 'status_snoozed') : '')]
  for (const w of usage.rateLimits) {
    const left = w.resetsAt ? Date.parse(w.resetsAt) - now : 0
    parts.push(windowName(lang, w.kind) + ' ' + t(lang, 'percent', { n: w.percentUsed }) + (left > 0 ? t(lang, 'status_resets', { duration: formatDuration(left, units) }) : ''))
  }
  if (usage.rateLimits.length === 0) parts.push(t(lang, 'status_no_data'))
  if (usage.context && typeof usage.context.tokens === 'number') parts.push(t(lang, 'status_context', { tokens: tokensLabel(usage.context.tokens) }))
  return parts.join(' · ')
}

// True only when the listed /saver is a plugin command that crew-chief itself added (an earlier
// registration that a reload or /clear kept). The list names the adding plugin as `name@marketplace`,
// `name@inline` (--plugin-dir) or `name`; anything else (a built-in, another plugin, the user's own
// command, or an entry that does not say) is not ours, and our command.run hook stays out of its way.
async function ownsSaver($) {
  try {
    const commands = await $.command.list()
    return commands.some((c) => c.name === 'saver' && c.source === 'plugin' && /^crew-chief(@|$)/.test(String(c.plugin ?? '')))
  } catch (err) {
    return false
  }
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    resetState()
    await handoffOfferMarker($)
    const result = await next(e)
    try {
      await $.command.register({
        name: 'saver',
        description: t(await resolveLang($), 'cmd_description'),
        argumentHint: '[on|off|status]',
      })
      registered = true
    } catch (err) {
      // The name is taken: by a built-in or another plugin's command (leave it alone), or by this
      // plugin's own earlier registration (/clear, /resume run session.start again), see ownsSaver.
      registered = await ownsSaver($)
    }
    // CREW_CHIEF_ULTRA=on starts the session in ultra-saver (for trying it in a scripted run; nothing turns it on by itself).
    if (isEnvFlag(await $.env.get('CREW_CHIEF_ULTRA'))) {
      saver = true
      ultra = true
    }
    await configSessionStart($)
    await compactSessionStart($)
    await tidySessionStart($)
    await statsSessionStart($)
    rowSessionStart($)
    await guardSessionStart($)
    await uiSessionStart($)
    await panesSessionStart($)
    await avSessionStart($)
    await nightSessionStart($)
    handoffOfferStart($, e)
    return result
  })

  on('session.end', async ($, e, next) => {
    resetState()
    resetCompact()
    rowSessionEnd($)
    panesReset()
    avReset()
    await guardSessionEnd($)
    nightReset()
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    lastPromptAt = await $.clock.now()
    compactNoteActivity()
    nightNoteActivity(lastPromptAt, true)
    // Only what the person types counts: task notifications, peer sessions, schedules, and other
    // plugins also come through prompt.submit, and their text is usually English.
    const kind = e.origin ? e.origin.kind : undefined
    const verdict = kind === undefined || kind === 'composer' || kind === 'bridge' ? classifyText(e.text) : undefined
    if (verdict !== undefined) {
      addLanguageVote(verdict)
    }
    if (kind === undefined || kind === 'composer' || kind === 'bridge') {
      resetNotePrompt(lastPromptAt)
      await cacheOnPrompt($)
    }
    const notes = [await compactNudge($), guardNudge(), ...(await handoffOnPrompt($, e)), handoffOfferNote()].filter((n) => n !== undefined)
    return next(notes.length === 0 ? e : { ...e, context: [...(e.context ?? []), ...notes] })
  })

  on('session.measure', async ($, e, next) => {
    uiTouch($)
    await compactUpdate($, e)
    await resetOnUsage($, e)
    await nightMeasure($, e)
    await evaluate($)
    if (pending !== null && !(await turnInFlight($))) launchAsk($)
    return next(e)
  })

  // The measure event can arrive mid-turn or not at all; a finished main turn is the safe moment
  // to ask, and a second chance to notice the limits.
  on('turn.complete', async ($, e, next) => {
    await rowTurnComplete($, e)
    // A subagent's end: the notice and the agent view (hooks/src/agent-view.js); the main loop's end is noted.
    await avTurnComplete($, e)
    if (e.agentId === undefined) {
      lastCompleteAt = await $.clock.now()
      nightNoteActivity(lastCompleteAt, false)
      uiTouch($)
      const usage = await $.session.usage()
      await uiNoteContext($, usage)
      await compactTurnComplete($, usage, e.reason)
      await handoffTurnComplete($, e)
      await resetOnUsage($, usage)
      await nightTurnComplete($, usage)
      await evaluate($)
      launchAsk($)
      if (e.reason === 'answer' && !advisorChecked && pending === null && !open.saver) {
        advisorChecked = true
        offerAdvisor($)
      }
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId === undefined) {
      lastStepAt = await $.clock.now()
      compactNoteActivity('step')
      nightNoteActivity(lastStepAt, true)
      uiNoteMainStep(e)
    }
    await statsStepStart($, e)
    // Debug log only (claude --debug-file): what the host hands this hook for a subagent request.
    if (e.agentId !== undefined) {
      $.ui.log('saver: step agent=' + e.agentId + ' model=' + e.model + ' effort=' + String(e.effort) + ' saver=' + saver, { to: 'debug' })
    }
    let request = e
    if (saver && e.agentId !== undefined) {
      const cap = capEffort(e.model, e.effort)
      // Under ultra an Opus subagent is one the person approved (or allowed for the session): the call already
      // carries the effort that was agreed, so the step must not lower it again.
      if (cap.capped && !(ultra && cap.tier === 'heavy')) {
        if (!capToasted && !quiet) {
          capToasted = true
          const lang = await resolveLang($)
          const model = t(lang, cap.tier === 'heavy' ? 'model_heavy' : 'model_sonnet')
          $.ui.toast(t(lang, 'toast_cap', { model, from: cap.from, to: cap.effort }), { timeoutMs: 6000 })
        }
        $.ui.log('saver: subagent ' + e.agentId + ' on ' + e.model + ' effort ' + cap.from + ' -> ' + cap.effort, { to: 'debug' })
        request = { ...e, effort: cap.effort }
      }
    }
    // The row shows what the host reported (e), not what the cap wrote into the outgoing request: the host may
    // keep the agent definition's own effort (seen: planner ran high while the cap wrote medium).
    await rowStepStart($, e)
    const result = yield* next(request)
    await statsStepEnd($, e, result)
    await rowStepEnd($, e, result)
    if (e.agentId !== undefined) avNote($, e.agentId)
    return result
  })

  // The one unmatched tool.call hook of this module. First the opt-in command guard (hooks/src/guard.js):
  // off unless turned on, untouched calls skip it without waiting, and any failure lets the call through.
  // Then, while the saver is on, an Agent call for one of the Opus agents carries effort medium (the
  // turn.step cap below stays as the second line). Any failure there leaves the call as it was.
  on('tool.call', async ($, e, next) => {
    let guard
    if (guardWants(e)) {
      try {
        guard = await guardCheck($, e)
      } catch (err) {
        guard = undefined
      }
    }
    if (guard !== undefined && guard.deny !== undefined) return { deny: guard.deny }
    let request = e
    try {
      let plan
      if (ultra && e.tool === 'Agent') plan = ultraAgentCall(e, ultraOpus, await $.session.model())
      if (plan !== undefined) {
        // Ultra-saver: the model and effort of the call are rewritten (never seen live: the host may still apply
        // the agent definition's own model; the unit tests cover the rewrite, /tasks shows what really ran).
        const approved = plan.ask ? await askOpus($, e) : false
        if (!approved) {
          $.ui.log('saver: ultra Agent call ' + String(e.subagent_type) + ' model ' + String(e.model) + ' effort ' + String(e.effort) + ' -> ' + JSON.stringify(plan.rewrite), { to: 'debug' })
          request = { ...e, ...plan.rewrite }
          if (!ultraToasted && !quiet && plan.rewrite.model !== undefined) {
            ultraToasted = true
            const lang = await resolveLang($)
            $.ui.toast(t(lang, 'toast_ultra_cap', { agent: String(e.subagent_type || 'agent'), effort: plan.rewrite.effort }), { timeoutMs: 6000 })
          }
        }
      } else {
        const effort = saver && e.tool === 'Agent' ? agentCallEffort(e) : undefined
        if (effort !== undefined) {
          $.ui.log('saver: Agent call ' + String(e.subagent_type) + ' effort ' + String(e.effort) + ' -> ' + effort, { to: 'debug' })
          request = { ...e, effort }
        }
      }
    } catch (err) {
      request = e
    }
    // Subagent progress (hooks/src/progress.js): counts the call, and returns a reminder only where the
    // shell hook cannot run.
    const reminder = await progressObserve($, e)
    const overlap = await overlapObserve($, e)
    const result = await next(request)
    if (typeof e.agentId === 'string') avNote($, e.agentId)
    const handoff = await handoffAfter($, e, result)
    if (guard === undefined && reminder === undefined && overlap === undefined && handoff === undefined) return result
    return progressAfter(progressAfter(progressAfter(guard === undefined ? result : await guardAfter($, e, guard, result), reminder), overlap), handoff)
  })

  on('command.run', { command: 'saver' }, async ($, e, next) => {
    // The module can be loaded again (/reload-plugins, an update) without a new session.start, which
    // leaves `registered` false while the host still has our command: look it up before refusing.
    if (!registered) registered = await ownsSaver($)
    if (!registered) return next(e)
    const word = String(e.args || '').trim().toLowerCase()
    const lang = await resolveLang($)
    if (word === 'on') {
      // From ultra, 'on' steps down to the normal saver (it read as "saver on" and changed nothing).
      const wasUltra = ultra
      saver = true
      ultra = false
      ultraOpus = false
      await askNever($, false)
      return { text: t(lang, wasUltra ? 'cmd_ultra_off' : 'cmd_on') }
    }
    if (word === 'off') {
      saver = false
      ultra = false
      ultraOpus = false
      await askNever($, true)
      return { text: t(lang, 'cmd_off') }
    }
    if (word === 'ultra' || word === 'ultra on') {
      const wasOn = saver
      saver = true
      ultra = true
      await askNever($, false)
      return { text: t(lang, 'cmd_ultra_on') + (wasOn ? '' : ' ' + t(lang, 'cmd_ultra_needs_saver')) }
    }
    if (word === 'ultra off') {
      ultra = false
      ultraOpus = false
      return { text: t(lang, 'cmd_ultra_off') }
    }
    if (word === 'ultra opus on' || word === 'ultra opus off') {
      ultraOpus = word === 'ultra opus on'
      return { text: t(lang, ultraOpus ? 'cmd_ultra_opus_on' : 'cmd_ultra_opus_off') }
    }
    if (word === '' || word === 'status') return { text: await statusText($) }
    return { text: t(lang, 'cmd_usage') }
  })

  registerAsk(on)
  registerConfig(on)
  registerCompact(on)
  // The saver word at the end of the Desktop status line: off -> saver -> ultra-saver -> off. A press does not
  // touch the "never ask" answer (that stays with /saver on|off and the question).
  registerUi(on, () => (ultra ? 'ultra' : saver), () => {
    if (!saver) {
      saver = true
      return 'cmd_on'
    }
    if (!ultra) {
      ultra = true
      return 'toast_ultra_on'
    }
    saver = false
    ultra = false
    ultraOpus = false
    return 'toast_saver_off'
  })
  registerPanes(on)
  registerAgentView(on)
  registerReset(on)
  registerTidy(on)
  registerStats(on)
  registerGuard(on)
  registerNight(on)
}
